INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498689842', 'Cesto Organizador 8,2 Litros Flow CFW400 - Ou', 'Cesto Flow 8,2 Litros - Ou Organize sua casa com praticidade e estilo utilizando o Cesto Flow 8,2 Litros da Ou. Este cesto é a solução perfeita para manter tudo em ordem, desde produtos de limpeza e roupas até acessórios ou alimentos. Com um design moderno e funcional, ele se adapta facilmente a qualquer ambiente, proporcionando uma rotina mais prática e eficiente. Seu formato conta com pegas arredondadas, garantindo um encaixe confortável dos dedos e facilitando o transporte. Além disso, os cestos Flow possuem área livre para a aplicação de etiquetas, permitindo a identificação rápida e personalizada dos itens armazenados. Para uma organização ainda mais eficiente, é possível utilizá-lo com uma tampa (vendida separadamente), tornando-os empilháveis e otimizando o uso do espaço. Fabricado em PP (polipropileno) de alta qualidade, o Cesto Flow é leve, resistente e fácil de limpar, garantindo maior durabilidade no dia a dia. Seja para o quarto, cozinha, lavanderia ou escritório, ele oferece versatilidade e organização, contribuindo para um ambiente mais harmonioso. Especificações Marca: Ou Material: PP (polipropileno) Altura: 9 cm Largura: 27 cm Profundidade: 34 cm Peso: 276 g Capacidade: 8,2 litros Linha: Flow', 46.9, 34.9, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-7rdxl-mbnyvnvbe59866', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314243679%2F23498689842', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
