INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998297386', 'Tinta Spray Tekbond Uso Geral Grafite 350ml', 'Características Principais: Marca: Tekbond Cor: Grafite Litragem: 350 ml Peso: 250g Informações adicionais: Acrílica de secagem rápida, com excelente acabamento e resistência. Ideal para ferro, madeira, cerâmica, gesso, MDF, parede e outros materiais. Pode ser usada em ambientes internos e externos, com ótimo poder de cobertura. Proporciona durabilidade e resistência a condições climáticas extremas. Modos de Uso: Remova restos de pintura antiga, ferrugem, gordura e poeira. Proteja as partes que não serão pintadas com papel, papelão ou plástico. Em metais com ou sem oxidação, utilize o Primer Spray Super Color Uso Geral, lixe com lixa d¿água 400 para nivelar. Agite bem a lata antes do uso e entre as demãos. Aplique de 2 a 3 demãos finas, aguardando 4 a 9 minutos entre cada uma. Toque seco em 30 minutos. Manuseio seguro em 3 horas. Máxima resistência em 24 horas. Cuidados: Não armazenar em temperatura acima de 50°C (risco de explosão). Manter em local fresco, seco, ventilado e distante de fontes de ignição. Armazenar a lata em pé e à temperatura ambiente. Fornecedor: Atb ind. e com.de adesivos S.A', 27.45, 14.9, NULL, 'Home & Living > Tools & Home Improvement > Others', 'https://cf.shopee.com.br/file/sg-11134201-824g0-mpibhye2wwstff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F20998297386', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793962583', 'Sanduicheira Plasútil Mickey - Embalagem com 10 Unidades', 'Carcterísticas do produto: Marca: Plasútil Ean: 17899808865788 Material: Polipropileno (PP), um plástico durável e resistente Informações adicionais: Tipo de Fechamento: Fechamento: Tampa acoplada com aba, proporcionando uma forma prática e eficiente de abrir e fechar a sanduicheira, com fácil manuseio até para as crianças Design: Tema: A sanduicheira possui um design exclusivo com o tema do Mickey, em uma versão 3D que dá um toque divertido e lúdico, ideal para atrair a atenção das crianças e agregar à sua coleção de produtos do personagem Estilo: Compacta e leve, com cores vibrantes e detalhes que tornam o uso mais interessante Indicação de Uso: Ideal para ser utilizada em lancheiras escolares, bolsas de passeio ou como um item de armazenamento de lanches para qualquer momento do dia, como piqueniques, festas e viagens Vantagens: Praticidade: Compacta, com um design de fácil abertura para crianças e adultos Segurança: A decoração 3D injetada evita o risco de adesivos se soltam, sendo mais seguro para as crianças Durabilidade: Material resistente ao desgaste, mantendo a integridade da sanduicheira mesmo com o uso frequente Manutenção e Cuidados: Limpeza: Pode ser limpa com um pano úmido ou esponja macia. Não recomendado o uso de produtos abrasivos Instruções: Para prolongar a vida útil do produto, evite deixar exposto ao sol por longos períodos e não utilize em micro-ondas ou lava-louças Fornecedor: Plasutil Ind.Com. De Plasticos Ltda', 104.6, 104.6, NULL, 'Home & Living > Others', 'https://cf.shopee.com.br/file/sg-11134201-824j7-mpiaceu7dclnc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23793962583', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
