INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263476734', 'CD Demi Lovato - It''s Not That Deep (Standard) - Importado', 'CD Demi Lovato - It''s Not That Deep (Standard) - Importado "It''s Not That Deep" captura Demi em seu momento mais radiante, resgatando o espírito despreocupado de seus primeiros anos e lançando 11 hinos dance-pop perfeitos para noites e pistas de dança. Com produção executiva de Zhone, o álbum pulsa com confiança, liberdade e alegria, liderado pelo single elegante "Fast" e pela contagiante "Here All Night". Tracklist: 1. Fast 2. Here All Night 3. Frequency 4. Let You Go 5. Sorry To Myself 6. Little Bit 7. Say It 8. In My Head 9. Kiss 10. Before I Knew You 11. Ghost', 89.9, 79.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-825am-mqqn3fxfjapv95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F58263476734', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259543072', 'Ar-Condicionado Split Inverter 9000 BTUs LG +AI Dual Inverter Voice Quente e Frio S3-W09AA31E 220V', 'Ar-Condicionado Split Inverter 9000 BTUs LG +AI Dual Inverter Voice Quente e Frio S3-W09AA31E 220V Ar-Condicionado Split Inverter LG 9000 BTUs Quente e Frio Dual Inverter Voice S3-W09AA31E com Wi-Fi O Ar-Condicionado LG Dual Inverter 9000 BTUs oferece climatização inteligente, econômica e silenciosa para o dia a dia. Com tecnologia AI, aprende seus hábitos e ajusta automaticamente a temperatura ideal, garantindo mais conforto sem esforço. Conta com Wi-Fi integrado, permitindo controle pelo app LG ThinQ™ ou por comando de voz via Google Assistente e Alexa. A tecnologia DUAL Inverter proporciona refrigeração até 40% mais rápida e economia de até 70% de energia. Possui Active Energy Control com 4 níveis de consumo, filtro antialérgico para um ar mais saudável e funcionamento silencioso com maior durabilidade. Ideal para quem busca conforto térmico, tecnologia e economia em um só produto.', 2302.52, 2302.52, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-820ob-mng4mna9uwauee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1527564302%2F58259543072', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
