INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394228664', '[Venda em combo]Gaabor kit com 2 panelas elétricas multifuncionais 1L capacidade pequena ideal para 1 tigela de arroz', 'A Panela de Arroz Elétrica Gaabor é ideal para quem busca praticidade e eficiência na cozinha, oferecendo aquecimento uniforme sem queimar o alimento. Seu design compacto, elegante e de fácil utilização torna o preparo das refeições mais simples e rápido. Seja para o dia a dia ou para ocasiões especiais, essa panela é o aliado perfeito para oferecer sabor e qualidade em suas receitas. Adquira agora a sua Panela de Arroz Elétrica Gaabor e tenha refeições sempre deliciosas e prontas para servir com o mínimo esforço. Operação com um botão: Mantenha automaticamente o arroz aquecido após o cozimento, pronto para servir a qualquer hora. Aquecimento tridimensional de alta potência: Distribui o calor de maneira uniforme, oferecendo um cozimento perfeito sem queimar o alimento. Revestimento Antiaderente: Facilita a limpeza, evitando que os alimentos grudem, tornando o uso ainda mais prático. Aço Inoxidável: A estrutura em aço inoxidável proporciona durabilidade e resistência, além de agregar um toque de elegância à sua cozinha. Condução de energia e calor rápida: Cozinhe suas refeições de maneira eficiente com uma distribuição rápida e uniforme do calor. Válvula de vapor removível: Facilita a montagem, desmontagem e limpeza, tornando o uso diário mais prático. Tampa Basculante com Trava: A tampa prática e segura com sistema de travamento oferece um manuseio fácil e seguro durante o preparo. Acessórios Inclusos: Acompanha colher, copo medidor e bandeja para preparo no vapor, proporcionando mais versatilidade na hora de cozinhar. Características: - Peso (gramas): 2,8kg - Dimensões: 23 cm (Comprimento) x 22 cm (Largura) x 25 cm (Altura); - Potência nominal: 400w - Cor do produto: Prata - Operação: Touch - Revestimento: Antiaderente - Utilização: Multi uso #gaabor #panelaelétricadearroz #xicaras #panelaindustrial #minipanela #minipanelaelétricadearroz #panelaelétricadearroz #panelaarroz #minifogãoelétrico #pressurecooker #panelamultifuncional #panelaarrozeletrica #panelaelétricamultifuncional #legumeira #cabodepanelaelétricadearroz #DOMUS STORE_', 756.0, 428.0, NULL, 'Home Appliances > Kitchen Appliances > Rice Cookers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcaecxwe3qow77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1541348350%2F23394228664', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
