INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28664304439', 'HERA Protetor UV Tonificante PA + ,, 50ml', 'Tom-up PA+++, 50ml protetor UV HERA Pele BRILHANTE Creme de sol tonificante diário que restaura o brilho saudável natrual da pele e Oferece proteção contra estímulos no ambiente nocivo da cidade Incluindo raios UV, raios infravermelhos, luz azul e PM 2,5. Creme MILD-SUN #Mild Uv, poderoso contra raios UV e ambientes nocivos e ainda funciona suavemente na pele. Teste de irritação da pele primária *Teste de irritação da pele primária Sistema DE 5 DEFENSO Uva, UVB, luz azul, PM2.5 e IR Proteção forte contra raios UV e o ambiente nocivo da cidade. Tom DE''VITALIDADE'' PARA PELE MAIS CLARA E SAUDÁVEL Creme semelhante a fluidos com textura que se aplica à pele suavemente para melhorar naturalmente O tom da pele e crie uma pele brilhante uniforme e brilhante sem qualquer elenco branco. Melasolvtm, ingrediente de clareamento original da Amorepacific, Suprime a melanogênese e traz de volta o brilho natural da pele.', 213.66, 213.66, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134207-7rd6j-m7m5n9144z0d84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F28664304439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
