INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298892119', 'POMADA REPARADORA INTENSIVA EUCERIN AQUAPHOR 49G', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. Eucerin Aquaphor é um creme com reparação intensiva da pele muito seca, áspera ou hipersensibilizada. Formulado com Pantenol, Glicerina e Bisabolol, hidrata e acalma a área afetada, criando uma barreira protetora que protege a umidade da pele. Possui uma textura suave e é ideal para diversos tipos de necessidades.', 89.42, 89.42, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-824gs-mekimp9lnvgj52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F23298892119', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
