INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52208240922', 'Kit com 6 unid Mordedores para cachorro 100% natural', '🐶🦴 KIT COM 6 MORDORES NATURAIS PARA CÃES 🦴🐶 ✨ VARIEDADE, SAÚDE E DIVERSÃO PARA O SEU PET! ✨ Kit com 6 mordedores naturais selecionados para proporcionar momentos de diversão e bem-estar para o seu cachorro. Ideal para estimular a mastigação, reduzir o estresse e ainda auxiliar na saúde bucal. 📦 Conteúdo do kit: ✔ 6 unidades de mordedores naturais variados (podendo incluir: traqueia, orelha, fêmur, casco ou similares) 🐾 Benefícios: ✔ 100% natural – sem conservantes e aditivos ✔ Auxilia na limpeza dos dentes ✔ Reduz tártaro e mau hálito ✔ Ajuda a aliviar estresse e ansiedade ✔ Estimula a mastigação saudável ✔ Variedade para manter o interesse do pet 🐕 Indicação: Ideal para cães de todos os portes ⚠️ Importante: • Produto natural – pode haver variação de tamanho, cor e formato • Oferecer sempre sob supervisão • Armazenar em local seco e arejado 🚚 Envio rápido e bem embalado 💰 Perfeito para testar diferentes mordedores ou presentear seu pet 👉 Garanta agora e proporcione mais saúde, diversão e sabor para o seu melhor amigo! 🐾', 18.5, 13.88, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/sg-11134201-81zwu-mmm15ntaai2w5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908280603%2F52208240922', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
