INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209467485', 'Picanha Congelada Burg', 'A verdadeira picanha brasileira, agora congelada para sua maior conveniência! A Picanha Burg é feita com cortes selecionados e conservada para manter todo o sabor, maciez e suculência. Produto congelado, porcionado e pronto para ir direto do freezer para a sua grelha ou churrasqueira. Ideal para aquele almoço especial ou churrasco de última hora.', 119.99, 98.99, NULL, 'Food & Beverages > Fresh & Frozen Food > Meat', 'https://cf.shopee.com.br/file/sg-11134201-81zw1-miyqcw21bd35c5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703290516%2F58209467485', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094945403', 'Banana Nanica Orgânica Sítio Cambara', 'A Banana Nanica Orgânica do Sítio Cambará é cultivada sem agrotóxicos, garantindo uma fruta saborosa, macia e rica em nutrientes essenciais como potássio, fibras e vitaminas. Perfeita para o consumo in natura, vitaminas, sobremesas e lanches saudáveis.', 9.49, 8.06, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-82618-mk0x0tob2nt02e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703290516%2F23094945403', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262960510', 'Escorredor de Talheres de Plástico', 'Escorredor de Talheres de Plástico Dimensao: (Comp x Larg x Alt): 22,5x12,2x14,7 cm Uma linha completa para você deixar sua pia e cozinha organizada. Toda linha pia possui composição coordenada. Cinza: tom neutro e atemporal que contrasta bem com diversos ambientes. Compacto e adequado a qualquer tamanho de pia. Fabricado em polipropileno (PP). Livre de bisfenol-A (BPA FREE). *Não acompanha talheres. Imagem apenas para sugestão de uso..', 14.9, 14.9, NULL, 'Home & Living > Kitchenware > Kitchen Racks', 'https://cf.shopee.com.br/file/sg-11134201-824hs-mps12bgozthn3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F58262960510', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399600098', 'Fusível Térmico Geladeira Brastemp W10257565', 'Fusível Térmico Geladeira Brastemp W10257565 O Fusível Térmico Geladeira Brastemp W10257565 é um componente essencial para garantir a segurança e o bom funcionamento do seu eletrodoméstico. Ele é responsável por proteger o sistema elétrico da sua geladeira contra superaquecimento, interrompendo o fluxo de corrente elétrica caso ocorra um aumento anormal de temperatura. Isso evita danos maiores aos outros componentes e prolonga a vida útil do equipamento, proporcionando tranquilidade no uso diário. Compatível com diversas geladeiras da linha Brastemp, esse fusível térmico é uma solução eficaz para manter sua geladeira funcionando de maneira eficiente e segura. Com sua capacidade de detectar variações de temperatura, ele age de forma preventiva, garantindo que seu eletrodoméstico opere dentro dos padrões ideais. A instalação do fusível térmico é simples, garantindo que você possa substituir a peça com rapidez, restaurando o desempenho da sua geladeira.', 25.9, 25.9, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-824g0-mpdxy3sh2eptfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F21399600098', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251879260', 'Fita de Aço Perfurada 17mm x 30 Metros Hulter', 'Fita de Aço Perfurada 17mm x 30 Metros Hulter A Fita de Aço Perfurada 17mm x 30 Metros Hulter é uma solução versátil e resistente, ideal para fixações, ancoragens e suportes em instalações diversas, como sistemas elétricos, hidráulicos, estruturais e de climatização. Fabricada em aço de alta durabilidade, oferece excelente resistência mecânica, garantindo segurança e firmeza nas aplicações mesmo em ambientes que exigem confiabilidade ao longo do tempo. Com largura de 17mm e rolo de 30 metros, a fita possui perfurações uniformes que facilitam a fixação com parafusos ou abraçadeiras, proporcionando instalação rápida e versátil sem necessidade de cortes ou ferramentas especiais. Seu formato flexível permite moldagem em diferentes superfícies, cantos e curvas sem comprometer a estrutura, atendendo tanto demandas residenciais quanto industriais.', 44.9, 44.9, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-82301-mi6dbxp0foy0b2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F58251879260', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493492827', 'Kit De 2 Pneus Pirelli Aro 17 215/55 R 17 94v Powergy', 'PNEU 215/55R17 94V POWERGY PIRELLI O NOVO POWERGY™ É a escolha inteligente para condutores que procuram segurança e alto desempenho com um baixo impacto ambiental. O Powergy foi construído com tecnologia de ponta e materiais de alta qualidade para proporcionar melhor aderência e em piso molhado. A baixa resistência ao rolamento garante um elevado conforto na condução um baixo consumo de combustível. CHEVROLET CHEVROLET: MONTANA, TRACKER HONDA HONDA: HR-V JEEP JEEP: COMPASS LEXUS LEXUS: ES350, GS350 MITSUBISHI MITSUBISHI: AIRTREK NISSAN NISSAN: ALTIMA PEUGEOT PEUGEOT: 407, 407 SW SUBARU SUBARU: FORESTER, OUTBACK SUZUKI SUZUKI: S-CROSS, VITARA TOYOTA TOYOTA: CAMRY, PREVIA VOLKSWAGEN VOLKSWAGEN: FUSCA DÚVIDAS FREQUENTES… Faturamento para CNPJ? Não faturamos para CNPJ Contribuinte. Apenas para CNPJ Isentos de Inscrição Estadual; Os produtos são novos? Possuem Garantia? Sim, todos os produtos são novos e possuem garantia de fábrica, de 5 anos, contra defeito de fabricação. Acompanha Nota Fiscal? Sim, todas nossas vendas são realizadas com emissão de Nota Fiscal. A mesma, é enviada junto aos produtos do pedido. Posso retirar os produtos na loja? Não. As entregas são realizadas via transportadora para o endereço indicado no cadastro do comprador. Vocês aceitam outro produto como troca? Aceitam Usados? Não. Trabalhamos somente com a venda de produtos novos, sem troca. Esses Pneus são Remold? Não, trabalhamos apenas com produtos Novos e Originais. Qual o prazo de envio do produto comprado? Até 2 dias úteis após o Mercado Livre liberar seu pedido em nosso sistema, os seus produtos serão enviados, e a partir de então o prazo de entrega da mercadoria começa a contar. Ao receber os produtos, devo conferir? Sim, sempre deve ocorrer a conferência dos produtos no momento da entrega. Se tiver alguma divergência, não receba os mesmos. Preciso realizar a troca e/ou devolução? Em relação a trocas e/ou devoluções, salientamos que deve observar o prazo para realizar a mesma. Os itens devem estar obrigatoriamente, no mesmo estado em que recebeu e com suas etiquetas. NÃO ACEITAMOS DEVOLUÇÕES DE PNEUS QUE JÁ FORAM MONTADOS E/OU USADOS. Ainda tenho algumas dúvidas. Se você ainda tem dúvidas, utilize o campo de perguntas do Mercado Livre para falar com os nossos consultores. E atenção, só clique no botão comprar após ter certeza de que as condições descritas acima estão de acordo.', 1795.46, 1795.46, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdwv-m1n61ljqkyav28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819034845%2F22493492827', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398156315', 'Barra Roscada Aço 7/8 Polegadas - UNC - Ciser/Belenus', '- Barra Roscada ou também conhecido como vergalhão este elemento de fixação é utilizado em diversas aplicações principalmente na construção civil - Também é utilizado em montagens mecânicas de máquinas e equipamentos Ficha Técnica: • Diâmetro: 7/8 Polegadas • Comprimento: 1 metro • Material: Aço', 119.77, 116.18, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7ra18-m5buwdaoyq5a79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F272868574%2F23398156315', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18097815743', 'Conjunto Bolsa Térmica C/ Bolsos e Pote de Marmita, Garrafa 430 ml e Porta Talheres - Jacki Design', 'A bolsa térmica da coleção JOY, foi criada pensando em oferecer mais praticidade e estilo para o consumidor moderno! A bolsa térmica é feita multicamadas e folha de alumínio para manter seu alimento fresco e conservado. Possui fecho em zíper, bolso externo para garrafa e alça de mão. É ideal para levar ao trabalho, academia ou viagens. Conheça a linha completa da coleção JOY e complete o seu kit! CUIDADOS GERAIS: Limpe a bolsa térmica com um pano úmido. Caso necessário, use sabão neutro ou álcool para higienizar o local. Deixe secar na sombra. ATENÇÃO: Para preservar a vida útil do produto, recomendamos não deixar a bolsa de molho, não levar a máquina de lavar e também não utilizar produtos químicos. Medidas: Comprimento: 19cm x Largura: 13cm x Altura: 24cm Pote Marmita de 2 Andares 950ml: Agora ficou mais fácil organizar seus alimentos para um dia longo. A marmita de 825 ml possui 2 andares, podendo ser usada em conjunto ou separadamente. Feito de material polipropileno, é resistente e possui tampa com travas para segurança evitando acidentes. Produto livre de BPA com qualidade Jacki Design. Conheça a linha completa da coleção JOY e complete o seu kit! (INSTRUÇÕES DE USO: Retire a tampa antes de levar ao micro-ondas; usar somente para aquecer comida, não para cozinhar; Vai ao freezer e lava-louças; Temperatura de uso: -20°C ~120°C; Limpe usando uma esponja macia e detergente). Medidas: Comprimento: 19cm x Largura: 12.7cm x Altura: 9.4cm O copo transparente de 430 ml é ideal para levar água, suco ou chá para o escritório ou escola. Possui um filtro infusor, fecho colorido e alça de mão. É leve e fácil de carregar. Produto com qualidade Jacki Design. Conheça a linha completa da coleção JOY e complete o seu kit! (INSTRUÇÕES DE USO: Não vai ao micro-ondas ou lava-louças; Temperatura de uso: -20°C ~80°C; Limpe usando uma esponja macia e detergente). Medidas: Comprimento: 7.5cm x Largura: 7.5cm x Altura: 17.5cm Porta Talheres Portátil: O Porta Talheres da Jacki Design é um item essencial para transportar com higiene e segurança seus talheres. Feita de material Polipropileno, ele é compacto e fácil de limpar. Conheça a linha completa da coleção JOY e complete o seu kit! Medidas: Comprimento: 25cm x Largura: 6cm x Altura: 3cm', 191.9, 154.0, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbf8fkxj44fs61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F530578890%2F18097815743', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497707914', 'Conjunto Pote organizador e Porta Acessórios Multiuso - Jacki Design', 'Pote organizador com 3 Peças Mais uma novidade para linha Sapeka, lindo pote organizador com 3 peças, com estampa divertida, contém 1 pote grande, 1 pote médio e 1 pequeno. Possui uma pequena trava de segurança. Perfeito para organizar alimentos, remédios e até brinquedos. Composição: Polipropileno Capacidade: Pote G: 2500ml Pote M: 880ml Pote P: 590ml Comprimento: 30cm x Largura: 20cm x Altura: 8,5cm Material: PP Porta Acessórios Multiuso O Porta Escova de dentes da Jacki Design é um item essencial para transportar produtos de higiene como escova e pasta de dente, e toalhas. Ele protege os itens armazenados, além de preservar a aumentar a vida útil de sua escova. Perfeito para levar para escola, viagens e passeios. Conheça a linha completa da coleção JÚNIOR e complete o seu kit! Medidas: Comprimento: 6cm x Largura: 6cm x Altura: 19cm', 70.9, 59.4, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rdvu-lypx365q8w4q27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F530578890%2F22497707914', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894421234', 'Kit 10 Rolo Fita Espuma C/cola Chicote Acabamento Anti Ruido', 'ESPUMA PARA CHICOTE AUTOMOTIVO ANTI RUIDO MARCA: SPUMTAPE CODIGO: COM COLA COR: CINZA ITEM INCLUSO 01 PACOTE COM 10 ROLOS DE ESPUMA DE 2 METROS Especificações: Espuma de Poliuretano de Poliéster expandido. Auto Extinguível(Anti-Chamas). Aplicação: Chicotes, fios, alarmes, rastreadores, som, elétrica, Ar condicionado, GNV, entre outras. DÚVIDAS FREQUENTES: - Este Produto é novo? Sim, trabalhamos somente com produtos novos e originais. - O Produto é original? Sim, nossos fornecedores são os próprios fabricantes ou os maiores distribuidores do Brasil, devidamente credenciados pelos fabricantes. - Possuem garantia? Qual o prazo de garantia? Sim, todos nossos produtos possuem no mínimo 90 dias de garantia contra defeitos de fabricação. Ou, o prazo determinado pelo fabricante, o que for mais benéfico ao consumidor. Exemplo: toda linha de amortecedores, que possuem 2 anos de garantia. - O produto é idêntico a foto? Sim. Todas as fotos são fiéis ao produto que você irá receber. - Em quanto tempo recebo minha compra? Insira seu CEP no calculador de frete do anuncio para calculo deste prazo. - Como faço para saber se o produto deste anúncio se aplica ao meu veículo? Verifique na descrição do anuncio se o seu veiculo consta como compatível. Caso não tenha encontrado, entre em contato conosco no campo de mensagens, informando seu carro, ano e modelo. E se possível, o numero do chassis, para que possamos verificar a compatibilidade. PEDIMOS A GENTILEZA NÃO AVARIAR A EMBALAGEM ORIGINAL (passar fita adesiva, colar etiquetas de envio, rasgar a embalagem). ANTES DE EFETUAR A DEVOLUÇÃO OU ABRIR UMA RECLAMAÇÃO, POR FAVOR ENTRE EM CONTATO CONOSCO PARA AUXILIÁ-LOS. ATENÇÃO - A EMPRESA não se responsabiliza pelo mau uso ou instalação indevida do produto, sempre recomendamos que a instalação seja feita por um profissional especializado', 27.99, 25.76, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mevl6h5y2mf533', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1456324506%2F22894421234', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494684831', 'Multiuso Cozinha UAU Tech Limão 500ml', 'UAU Cozinha proporciona o máximo poder de limpeza, Facilitando muito mais sua vida! Sua fórmula exclusiva e concentrada, limpa com efciência removendo as gorduras mais difíceis e deixando um suave cheirinho de limão.', 13.72, 12.4, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-821do-mgxwk8migz61f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1658245933%2F22494684831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799252493', 'Armário Multiuso Escritório NT4045 com 2 Portas e Prateleiras Preto/Tx Preto Tx', 'PUXADORES EM ABS, ESTRUTURA DE 12MM, 4 PRATELEIRAS INTERNAS, MULTIUSO COMPACTO, Apresentamos o Multiuso NT 4045 da Notável Móveis, a solução compacta e versátil para otimizar o espaço na sua casa. Com quatro prateleiras internas espaçosas e bem distribuídas, este multiuso oferece amplo espaço de armazenamento para atender às suas necessidades diárias. Seja na cozinha, no banheiro, no escritório ou na área de serviço, este móvel compacto se adapta facilmente a diferentes ambientes, proporcionando organização e praticidade onde quer que você o coloque. Simplifique sua vida e mantenha seus pertences em ordem com o Multiuso NT 4045 da Notável Móveis. Estilo: Clássico Peso (kg): 22.56 Garantia: 03 Meses Altura (cm): 173.3 Acabamento: Pintura UV Largura (cm): 47.4 Possui Pés: Não Possui Nichos: Não Tipo de Porta: Bater Possui Gavetas: Não Possui Espelhos: Não Profundidade (cm): 31.3 Armário Suspenso: Não Escala de Brilho: Fosco Material da Porta: MDP Ambiente Principal: Escritório Espessura do Tampo (mm): 12 Formato do Armário: Retangular Material Principal: MDP Necessita Montagem: Sim Tamanho do Armário: Alto (Acima de 150cm) Acabamento da Porta: Pintura UV Sapatas Niveladoras: Não Possui Mesa Retrátil: Não Orientação do Armário: Vertical Material da Prateleira: MDP Quantidade de Armários: 1 Acabamento da Prateleira: Pintura UV Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Tipo de Puxador da Porta: Externo Escala de Brilho da Porta: Fosco Peso Máximo por Prateleira: 5 Material do Puxador da Porta: MDF Material do Puxador da Gaveta: MDF Tipo de Armário de Escritório: Totalmente Fechado Escala de Brilho da Prateleira: Fosco Tipo de Dobradiça/Corrediça da Porta: Aço Marca: Notável Móveis Cor Flex: não Cor Interna: Preto Tx Cor: Preto Tx Cor do Produto: Preto Tx Itens Inclusos: 1 Armário, Kit Ferragens e Manual de Montagem Cor Predominante: Preto Linha ou Coleção: 2024', 300.91, 300.91, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134201-820m8-mqxnkw81r2123d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F21799252493', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697677059', 'Conjunto Canto Alemão Baú América com Mesa de Jantar Retangular 1,20x80 e 2 Cadeiras Dalas Yescasa', 'Transforme sua sala de jantar em um ambiente acolhedor e altamente funcional com o Conjunto Canto Alemão Baú América. Desenvolvido especialmente para quem deseja otimizar cada centímetro disponível, este conjunto une o design inteligente do canto alemão com a elegância das Cadeiras Dalas, criando o cenário perfeito para refeições em família e recepção de amigos. Otimização de Espaço com Design Moderno A grande vantagem deste conjunto é o aproveitamento dos cantos, liberando a circulação central do ambiente. O banco no estilo Canto Alemão não apenas acomoda mais pessoas com conforto, mas também oferece a funcionalidade de baú (verifique a montagem para acesso), ideal para organizar toalhas de mesa, jogos americanos e outros utensílios, mantendo sua casa sempre em ordem. Mesa Robusta e Cadeiras Confortáveis A mesa retangular possui um tampo amplo de 120 cm x 80 cm, oferecendo espaço adequado para dispor pratos e travessas confortavelmente. Sua estrutura sólida garante estabilidade durante as refeições. Já as duas Cadeiras Dalas complementam o conjunto com sofisticação; revestidas em tecido aveludado, elas proporcionam um toque suave e um assento macio, com espuma de densidade D-26, garantindo conforto mesmo em longos jantares. Qualidade e Durabilidade Fabricado com um mix de MDP e MDF de alta qualidade, o conjunto oferece resistência e longa vida útil. O acabamento em Pintura UV semi-brilho protege o móvel e facilita a limpeza do dia a dia, mantendo a aparência de novo por muito mais tempo. As cores neutras e modernas (Marfim/Mel/Bege) facilitam a combinação com diversos estilos de decoração. Dimensões Detalhadas dos Componentes Para garantir que o conjunto se adeque ao seu projeto, confira as medidas individuais: • Mesa: 79 cm de altura, 120 cm de largura e 80 cm de profundidade. • Cadeiras: 98,5 cm de altura, 38 cm de largura e 50,2 cm de profundidade. • Canto Alemão (Módulos): O conjunto é formado por dois módulos que compõem o "L". O canto maior possui 137,5 cm de largura e o menor 136 cm. A altura é de 90,5 cm e a profundidade de 46,5 cm. Dica: A montagem é de complexidade média. Recomenda-se seguir atentamente o manual ou contratar um profissional de sua confiança para garantir o nivelamento perfeito das peças. Importante: o produto não inclui itens decorativos ou acessórios mostrados nas imagens. Confira o título e a ficha técnica completa para garantir que sua compra seja exatamente o que você espera! Garanta o encaixe perfeito! Planeje seu ambiente com cuidado comparando as medidas do produto com o espaço disponível e reserve uma folga de até 2 cm para posicioná-lo com conforto. Estilo: Moderno Formato: Retangular Garantia: 03 Meses Altura (cm): 79 Largura (cm): 120 Peso da Mesa: 24.5 Possui Vidro: Não Cor Secundária: Bege Mesa Extensível: Não Profundidade (cm): 80 Escala de Brilho: Semi-Brilho Formato do Tampo: Retangular Mesa Suporta Até: 50 Material do Tampo: MDP Origem do Produto: Nacional Acabamento da Mesa: Pintura UV Ambiente Principal: Sala de Jantar Espessura do Tampo (mm): 25 Material Principal: MDF/MDP Necessita Montagem: Sim Estrutura do Assento: MDP Estrutura do Encosto: MDP/Espuma De Canto (Canto Alemão): Sim Enchimento do Assento: Espuma D-26 Enchimento do Encosto: Espuma Peso da Cadeira/Banco: 6.75 Quantidade de Lugares: 2 Cadeira/Banco Estofada: Encosto e Assento Estofados Quantidade de Cadeiras: 2 Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Material da Base da Mesa: MDP Possui Apoio para os Pés: Não Cadeira/Banco Suporta Até: 90 Acabamento da Cadeira/Banco: Pintura UV Revestimento da Cadeira/Banco: Veludo Acompanha Manual de Instalação: Sim Informações Complementares (Novo): Canto alemão com 2 cadeiras Material da Estrutura da Cadeira: MDF/MDP Material Principal das Cadeiras/Bancos: MDF/MDP Marca: Yescasa Cor: Marfim/Mel Cor do Produto: Mel/Blonde/Marfim Itens Inclusos: 1 Canto, 1 Mesa, 2 Cadeiras, Manual De Montagem, Kit Ferragem Cor Predominante: Bege Medida da Mesa (A x L x P): A:79 x L:120 x P:80cm Medida do Tampo (L x C x E): L:120 x P:80 x E:2,5cm Medida da Cadeira/Banco (A x L x P): A:98,5 x L:38 x P:50,2cm Medida do Canto Alemão (A x L x P): Canto Maior: A:90,5 x L:137,5 x P:46,5 - Canto menor: A:90,5 x L:136 x P:46,5', 1586.1, 1504.78, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-820lz-mo14u12igmip0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F18697677059', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997478246', 'Mesa de Jantar 6 Lugares 180cm com Tampo MDF e Vidro Tangará CabeCasa MadeiraOriginals Marrom Caramelo/Off White', 'Transforme sua sala de jantar em um cenário de elegância e conforto com a Mesa de Jantar Tangará da CabeCasa. Desenvolvida com um design contemporâneo que valoriza linhas simples e acabamentos nobres, esta peça é a protagonista ideal para reunir até 6 pessoas com espaço e comodidade. Design Exclusivo e Materiais Nobres A Mesa Tangará destaca-se pela sua estrutura robusta construída em Madeira Maciça Tauari, garantindo não apenas beleza natural, mas uma durabilidade superior e resistência ao uso diário. O acabamento em verniz realça os veios da madeira, trazendo aquecimento e requinte à decoração. O grande diferencial está no seu tampo: uma base sólida de MDF revestida com vidro colado e bordas chanfradas laqueadas. Essa combinação oferece segurança, facilidade na limpeza e um visual clean que amplia a sensação de espaço no ambiente. Funcionalidade para o Dia a Dia Com 180 cm de largura e 90 cm de profundidade, a mesa oferece a área perfeita para dispor pratos e travessas sem aperto. O formato retangular e a disposição dos pés (design em 4 pés recuados) favorecem a acomodação das cadeiras, permitindo que todos se sentem confortavelmente. Seja para jantares formais ou almoços em família, a Linha Tangará adapta-se a diversos estilos de decoração, do clássico ao moderno. Ficha Técnica Simplificada • Altura: 77 cm • Largura: 180 cm • Profundidade: 90 cm • Espessura do Tampo: 39 mm (MDF + Vidro) • Material da Base: Madeira Maciça Tauari • Capacidade: Ideal para 6 lugares (suporta até 50kg distribuídos). Adquira uma peça de fabricação própria que une a tradição da madeira maciça com a modernidade do vidro. Importante: o produto não inclui itens decorativos ou acessórios mostrados nas imagens. Confira o título e a ficha técnica completa para garantir que sua compra seja exatamente o que você espera! Garanta o encaixe perfeito! Planeje seu ambiente com cuidado comparando as medidas do produto com o espaço disponível e reserve uma folga de até 2 cm para posicioná-lo com conforto. Estilo: Moderno Formato: Retangular Peso (kg): 55.1 Dobrável: Não Garantia: 24 Meses Altura (cm): 77 Acabamento: Verniz Extensível: Não Largura (cm): 180 Possui Vidro: Sim Design da Base: 4 Pés Suporta Até (kg): 50 Profundidade (cm): 90 Escala de Brilho: Semi-Brilho Material da Base: Madeira Maciça Material do Tampo: Vidro/MDF Origem do Produto: Nacional Acabamento da Base: Verniz Ambiente Principal: Sala de Jantar Espessura do Tampo (mm): 39 Fabricação Própria: Sim Material Principal: Madeira Maciça Necessita Montagem: Sim Acabamento do Tampo: Laca Quantidade de Lugares: 6 Tipo de Madeira Maciça: Tauari Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Marca: CabeCasa MadeiraMadeira Cor: Caramelo/Off White Itens Inclusos: 1 Mesa, kit de ferragens e manual de montagem Cor Predominante: Marrom Linha ou Coleção: Tangará Medida da Base (A x L x P): 73cm x 80,4cm x 146,4cm Medida do Tampo (L x C x E): 180cm x 90cm x 3,9cm', 1913.38, 1913.38, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-825ah-mqbyj9h2g7ilbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22997478246', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599366507', 'K-Othrine SC 25 30ml Contra Barata Formiga Mosca - Entregamos em até 4 horas', 'K-Othrine SC 25 30ml Contra Barata Formiga Mosca Se está procurando uma solução para eliminar infestações de baratas, formigas ou moscas, acabou de encontrar! K-Othrine SC 25 foi desenvolvido pela Bayer para acabar com esses insetos que podem trazer doenças para nós humanos e até outros animais. Utilize em ambientes externos, após diluir a dose conforme indicado, com auxílio de um pulverizador, em superfícies passíveis de repouso, trânsito e esconderijo desses insetos indesejáveis! Sua ação é rápida e irá trazer de volta o conforto e harmonia do seu ambiente. - Indicado para ambientes externos; - Inseticida piretróide com ação de choque e residual; - Ideal para controle de baratas, moscas, mosquitos e formigas; - Também atua no controle de moscas (larvas e adultos) e insetos rasteiros; - Atente-se às informações da embalagem de K-Othrine SC 25; - Disponível em frasco de 30ml.', 29.9, 29.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-8261i-mlqfx7djfi0x66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1760624219%2F23599366507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206669397', 'Glicopan Gold 30ml Aminoácido Animais', 'Glicopan Gold Vetinil 30Ml. Para: Felinos, Caninos, Roedores, Répteis, Aves e Mustelídeos Para ser utilizado por via oral puro, adicionado ao alimento ou na água. Caninos, Felinos, Mustelídeos e Répteis: Dose inicial: 0,5ml por kg de peso corporal ou 5 gotas por kg de peso corporal, duas vezes ao dia, até a dosagem máxima de 40ml por dia. Aves e Roedores: Dose inicial: 1ml, ou 11 gotas, diluído em 100ml de água de bebida, ou ainda 2 a 3 gotas, uma vez ao dia, diretamente no bico ou boca.', 66.9, 66.9, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/sg-11134201-8260m-mlnwyum4tkawb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1760624219%2F58206669397', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54808298310', 'Cabide Acrílico Kit Cabides Para Roupas Transparente Adulto Reforçado Organizador', 'Kit Cabides de Acrílico Transparente Adulto Reforçado – Ideal para Calças, Camisetas e Gravatas O Kit com até 50 Cabides de Acrílico Transparente é ideal para quem busca organização, praticidade e elegância no guarda-roupa ou na exposição de peças em lojas. Fabricados em acrílico 100% transparente e material reforçado, proporcionam resistência e durabilidade, suportando roupas como calças, camisetas, camisas, casacos leves e gravatas. Com design moderno, os cabides otimizam espaço, valorizam as peças e deixam o ambiente mais organizado e sofisticado. Características do Produto: Kit com até 50 unidades Material: acrílico 100% transparente e reforçado Ideal para roupas como calças, camisetas, camisas, blusas, gravatas e acessórios Alta resistência e durabilidade Design moderno, leve e funcional Ajuda na organização do guarda-roupa ou closet Perfeito para uso doméstico, lavanderias, lojas e comércios Dimensões Aproximadas por Cabide Altura: 21 cm Largura: 40 cm Observações Importantes: As medidas podem variar levemente conforme o lote de fabricação.', 29.9, 19.9, NULL, 'Home & Living > Home Organizers > Hangers & Pegs', 'https://cf.shopee.com.br/file/br-11134207-820l5-mmqalph7rytg1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F323288678%2F54808298310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894435979', 'Capacete Protork Personalizado Project 46 Vis. Camaleão', 'Capacete Adesivado ( Sem verniz ) New Three Este capacete aberto oferece conforto e sensação de liberdade a cada quilometro percorrido. Graças ao seu desenho, você tem um amplo campo de visão e áudio, o que lhe permite se manter atento a fatores externos. Visual clara e sem inconvenientes Com sua viseira simple você desfrutar de passeios agradáveis na moto, pois evitar o ingresso de qualquer elemento do ambiente que possa prejudica-lo. Rigidez e durabilidade fabricado com materiais de alta qualidade que absorvem energia e proporcionam grande dureza. Em caso de impacto o golpe se concentra num só ponto, para amortecer o movimento e evitar contusões. Suavidade em sua caminhada Seu material interno de Nylon acolchoado e elástico, permitindo maior absorção de impacto quando o capacete para. Sinta conforto e segurança ao longo do seu percurso! Garantia de Fabrica 3 Meses', 219.9, 197.91, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf1apsz2ljie66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F652972169%2F22894435979', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598509851', 'Guarda-Roupa Rubi New 2 Portas de Correr Infinity Branco/Line/-Duna', 'O Módulo 2 Portas de correr da linha Infinity é a solução perfeita para quem busca funcionalidade e elegância no quarto modulado. Com cabideiro, gavetas com corrediças telescópicas e diversas prateleiras internas, oferece excelente organização para roupas e acessórios. Seu design moderno e acabamento de alto padrão garantem um visual harmonioso e sofisticado ao ambiente. Seu grande diferencial está na capacidade de unir beleza, praticidade e alto desempenho em um único móvel. Modular: Sim Peso (kg): 87.33 Garantia: 03 Meses Altura (cm): 217 Acabamento: Pintura Texturizada UV Largura (cm): 135.8 Possui Pés: Não Possui Portas: Sim Tipo de Porta: Correr Possui Espelhos: Não Profundidade (cm): 50.8 Escala de Brilho: Semi-Fosco Gaveta com Chave: Não Material da Porta: MDP Origem do Produto: Nacional Ambiente Principal: Quarto Material da Gaveta: MDP Material Principal: MDP Necessita Montagem: Sim Acabamento da Porta: Pintura Texturizada UV Acabamento da Gaveta: Pintura Tipo de Guarda-roupa: Casal Material da Prateleira: MDP Peso Máximo por Gaveta: 5 Tipo de Módulo do Móvel: Guarda-Roupa Acabamento da Prateleira: Pintura Complexidade da Montagem: Alta: deve ser montado por um montador especializado Tipo de Puxador da Porta: Externo Espessura da Estrutura (mm): 12 Tipo de Puxador da Gaveta: Embutido Peso Máximo por Prateleira: 5 Tipo de Corrediça da Gaveta: Metálica Telescópica Tipo de Dobradiça/Corrediça da Porta: Plástica O Módulo Pode ser Utilizado Individualmente: Sim Marca: Móveis Castro Composição: 100% MDP Cor do Produto: Branco Line / Branco -Duna Itens Inclusos: 1 módulo, Kit de Ferragens e Manual de Montagem Cor Predominante: Branco Quantidade de Portas: 2 Portas', 1460.21, 1460.21, NULL,