INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394756871', 'Pingente Rommanel Coração Liso Banhado A Ouro - 541942', 'Pingente Coração Abaulado • Rommanel / Banhado a Ouro 18k • Clássico, Delicado e Atemporal DESCRIÇÃO EMOCIONAL A joia perfeita para quem busca expressar o amor e a delicadeza através de um símbolo eterno. Com seu design abaulado (estilo "fofinho"), este pingente possui um acabamento arredondado que reflete o brilho de forma suave e elegante. Uma peça essencial, versátil e cheia de significado, ideal para compor mixes de colares ou ser usada como um detalhe solitário e charmoso. DETALHES DO PRODUTO Marca: Rommanel — original Material: Banho de Ouro 18k Design: Coração com acabamento abaulado (tridimensional) e polido Dimensões: – Altura: 10 mm (1,00 cm) – Largura: 10 mm (1,00 cm) Ajuste: Contra-argola clássica para correntes finas e médias Diferenciais: Hipoalergênica Brilho duradouro e acabamento impecável Garantia Rommanel de 12 meses Joia original com nota fiscal O QUE ACOMPANHA 1x Pingente Coração Abaulado Certificado de Garantia Rommanel Nota Fiscal Embalagem Montável ENVIO RÁPIDO Envio no mesmo dia para pedidos feitos até 11h30 Possuímos envios para entregas no mesmo dia Todas as peças são conferidas duas vezes antes da postagem para garantir que você receba sua joia impecável ATENDIMENTO PERSONALIZADO Ficou com alguma dúvida ou quer ajuda a escolher? Ao realizar a compra, pode nos chamar no campo de mensagens, que teremos o maior prazer em te ajudar. COMO CUIDAR DA SUA JOIA Para conservar sua semijoia por muitos anos: Evite contato direto com álcool, perfume e suor excessivo Não use em piscina, mar ou academia Guarde em local seco, separado de outras peças Limpe com flanela macia FAQ – PERGUNTAS FREQUENTES É original? Sim, Rommanel original com nota e garantia. Tem garantia? Sim, 12 meses Rommanel. Envia rápido mesmo? Sim! Seguimos padrões rígidos de conferência e despacho. Garanta agora seu Pingente Coração Abaulado e receba uma peça encantadora, impecável e cheia de ternura.', 74.0, 67.78, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/sg-11134201-81ztl-miro9rb4hlok98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F536715397%2F23394756871', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397345952', 'Lanterna Traseira Ranger 2004 2005 2006 2007 2008 2009 Bicolor', 'Lanterna Traseira Ranger 2004 2005 2006 2007 2008 2009 Bicolor Características: Produto novo de ótima qualidade; Bicolor ré cristal; Lente em acrílico resistente. Compatível com os modelos: Ranger 2004; Ranger 2005; Ranger 2006; Ranger 2007; Ranger 2008; Ranger 2009. Garantia: 90 dias. Dica: Dê um novo visual para o seu carro, aqui você encontra os melhores produtos com os melhores preços! Importante: NÃO somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 136.67, 123.01, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lslf9l6m134d0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1147747289%2F23397345952', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197702644', 'Silicone Líquido Plástico Painel Automotivo Vintex 1,5l', 'SILICONE LÍQUIDO VINTEX ---------------------------------------------- DESCRIÇÃO: SILICONE LÍQUIDO é um produto desenvolvido para promover brilho em borrachas e plásticos, mais precisamente painéis, laterais de porta, frisos, para-choques, vinis, etc. Ideal para revitalizar e proteger superfícies automotivas, proporcionando um acabamento brilhante e renovado. Sua fórmula líquida é fácil de aplicar e garante uma cobertura uniforme. Indicado para todas as cores de veículos, este silicone é frágil e contém líquido, com validade garantida. Não é rotacionável nem voável, assegurando uma aplicação segura e precisa. Com um volume de 1,5 litros e peso de 1500 g, é perfeito para uso em carros e motos, mantendo seu veículo com aparência de novo. MODO DE USO: 1- Limpar bem a superfície. 2- Aplicar o produto com auxílio de aplicador de espuma, espalhando-o em toda a área com movimentos uniformes.', 60.84, 60.84, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-7rdvy-lyhx0zjmje2u94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F22197702644', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697420877', 'Kit 16 Parafusos Cromado Roda Palio Siena Strada E Palio Weekend Envio Imediato PA20', 'Parafusos Cromados para Rodas Esportivas – Estilo, Segurança e Durabilidade para Seu FIAT O Jogo de Parafusos Cromados M12 x 1,25 x 30 60° é ideal para quem busca segurança, performance e um toque de sofisticação nas rodas esportivas do seu veículo FIAT. Produzidos com aço de alta resistência e acabamento cromado, esses parafusos garantem fixação firme, durabilidade e visual moderno. Principais Benefícios: ✅ Acabamento Cromado Premium Parafusos com visual brilhante e elegante, que valorizam o conjunto das rodas e trazem um toque esportivo ao carro. ✅ Alta Resistência e Segurança Produzidos em aço 10B 22, oferecem excelente resistência ao torque e às condições severas de uso. ✅ Compatibilidade Perfeita Medidas M12 x 1,25 x 30 com assento cônico 60°, ideais para rodas esportivas. Exclusivos para veículos FIAT com rodas adaptadas (não servem em rodas originais). Características do Produto: ✅ Medida: M12 x 1,25 x 30 (60°) ✅ Material: Aço 10B 22 ✅ Acabamento: Cromado ✅ Quantidade: 16 Parafusos ✅ Encaixe: Chave 19mm ✅ Uso: Rodas esportivas (não compatível com rodas originais FIAT) Itens Inclusos no Pacote: ✅ 16 Parafusos Cromados para Rodas Esportivas Compatível com os Modelos: ✅ Palio (todos) ✅ Palio Weekend (todos) ✅ Siena (todos) ✅ Strada (todos) ✅ Argo ✅ Cronos ✅ Fiorino ✅ Pulse ✅ Uno Observações: ✅ Produto novo com excelente acabamento ✅ Ideal para quem busca segurança com estilo ✅ Produto bem embalado e enviado com segurança ✅ Tire todas as suas dúvidas pelo nosso Chat Garanta agora mesmo o seu jogo de parafusos e eleve o visual', 54.9, 54.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Wheel Nuts', 'https://cf.shopee.com.br/file/sg-11134201-7rbm7-lmc