INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498569558', 'Flauta Yamah Doce Germânica Yrs-23g Com Capa', 'Flauta Doce Soprano Yamah (germanico) Yrs-23g Modelo: YRS-23G As séries 20 e 30 de flautas doce da Yamaha são projetadas para fornecer um começo perfeito na educação musical de todos. Elas oferecem uma resistência de ar ideal para controle fácil e apresentam uma precisão de entonação que você esperaria encontrar apenas em modelos mais caros. Embora as flautas doce de plástico de outro fabricante possam ter uma aparência semelhante, as flautas doce ABS da Yamaha são instrumentos verdadeiramente superiores. Os modelos estão disponíveis com sistemas de dedilhado "Alemão" ou "Barroco". A série 20, fácil de tocar em todas suas faixas, destina-se principalmente a iniciantes. As flautas doce da série 30, que possuem uma passagem de ar arqueada para um melhor controle da respiração e da expressão do tom, são para os músicos mais avançados. - Duto de Ar Reto: Fácil de tocar com um timbre puro e suave. É ideal para principiantes. Características - Marca: Yamaha - Modelo: YRS 23G - Resina ABS - Afinação em Dó (C) - Construção em 3 peças - Acompanha Tabela de Digitação - Digitação Germânica (YRS-23) - Passagem de ar reta e orifícios duplos - Acompanha bag de algodão - Cor: Branca - Origem: Indonésia Outros Informação adicional: Garantia: 03 meses', 62.26, 56.04, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Wind Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7qveq-lhj5exc74q26cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1006271683%2F21498569558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
