INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53909159570', 'Kit 2 Óculos Ciclismo Unissex Corrida Esportivo Bike Ciclismo Academia Proteção UVA', 'Óculos Esportivo – Conforto, Estilo e Máxima Proteção Desenvolvido para quem busca desempenho e conforto, o óculos Esportivo é a escolha ideal para acompanhar você em qualquer atividade. Seu design leve e ergonômico garante máximo conforto mesmo após muitas horas de uso, tornando-o perfeito para treinos intensos, competições ou aventuras ao ar livre. Com diversas opções de cores e modelos, ele combina estilo e funcionalidade em um visual moderno e unissex. Além disso, oferece proteção Anti-UV 400, bloqueando 99,9% dos raios ultravioleta, garantindo total segurança para seus olhos em dias ensolarados. Por que escolher esse modelo? - Ultra leve e confortável. - Ideal para vários tipos de esporte. - Diversas cores e estilos. - Design unissex. - Proteção UV 400 de alta eficiência. Perfeito para quem busca estilo, resistência e proteção em um só produto.', 99.9, 80.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134207-820lz-mn668avv9vr569', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379576060%2F53909159570', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22495912929', 'Pistola Aplicadora de Silicone Profissional 9'''' 225mm (718801) - Onsite', 'O Aplicador de Silicone 9'''' 225mm (718801) - Onsite, é indicado para aplicar silicone. Ideal para tubos de até 300 g/305 ml (massa). Indicado para vedações e colagens de diversos materiais como: madeiras, plásticos e borrachas. A pistola para tubo de silicone ONSITE, é a ferramenta certa para você que trabalha na construção civil ou com pequenos reparos. Características: - Compacto e fácil de manusear. - Ideal para aplicações precisas de silicone. - Modelo: Aplicador de Silicone. - Ideal para tubos de até 300 g/305 ml (massa). - Ideal para vedações e colagens de diversos materiais como: madeiras, plásticos e borrachas. Código: 718801. Marca: Onsite. Tamanho: 225mm (9''''). Ean: 6942629215561.', 19.31, 19.31, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvdj-lhnicu8cepda06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22495912929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
