INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12732815549', 'Capa Banco Para Vários Modelos De Motos Térmica Ventilada Não Esquenta No Sol', 'CAPA PARA BANCO DE MOTOCICLETA TÉRMICA VENTILADA Principais características: - Você sabia que é possível evitar o calor e o desconforto do banco quando a motocileta fica exposta ao sol? - Esta é uma capa tecida em formato de tela em nylon, com espessura de 8 mm, que armazena bem menos calor pois faz com que os raios solares não atinja diretamente o banco; - O motociclista pode utilizar-se de um artificio para evitar este problema com a capa de banco ventilada com tela; - Com a capa você poderá sentar em sua moto e seguir sua viagem sem se queimar, mesmo que a moto esteja a horas no sol; E na chuva como funciona? - Na chuva evita que a calça do motociclista encharque com a água que se acumula no banco; Como é instalada? - A capa é instalada em cima da capa existente sem danificá-la e é presa através de uma faixa de fixação; - Alem de todos esses benefícios essa capa vai deixar sua moto ainda mais bonita e proteger a capa original de sua motocicleta; - Permite a circulação do ar: - Material anatômico; - Anti derrapante; - Fácil instalação; - Não esquenta; - Fabricante: Spencer Moto Peças; Tamanho G 1G (62 x 50) compativel com os modelos: - Honda: Titan 125; - Honda: Titan 150; - Honda: Titan 160; - Suzuki: Yes 125; - Yamaha: YBR 125; - Yamaha: Factor 125; - Yamaha: Factor 150; - Yamaha: Fazer 150; - Shineray: Jef 150S; - Dafra: Horizon 150; Tamanho GG / 2G (70 x 55) compativel com os modelos: - Honda: CB Twister 250; - Honda: Twister CBX 250; - Honda: CB 300 Twister; - Honda: CB 300R; - Honda: Xre 190; - Honda: Xre 300; - Honda: Bros 125; - Honda: Bros 150; - Honda: Bros 160; - Yamaha: Fazer 250; - Yamaha: Lander 250; - Yamaha: Ténéré 250; - Yamaha: XTZ 125; Tamanho GGG 3G (90 x 60) compativel com os modelos: - Suzuki: Burgman 125; - Honda: Pcx 160; - Honda: Pop 100; - Honda: Pop 110i; - Honda: Biz 100; - Honda: Biz 110i; - Honda: Biz 125; - Honda: Lead 110; - Honda: ADV Elite 125; - Yamaha: Neo 125; - Yamaha: NMAX 160; Tamanho GGGG / 4G (105 x 65) compativel com os modelos: - Honda: Pcx 160; - Honda: Pop 100; - Honda: Pop 110i; - Honda: Biz 100; - Honda: Biz 110i; - Honda: Biz 125; - Honda: ADV Elite 125; - Yamaha: Neo 125;', 25.9, 25.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Covers', 'https://cf.shopee.com.br/file/4e3adf9094ed4b8c496cd4cbdf188f19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F509931028%2F12732815549', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
