INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198869690', 'Tênis Fila Feminino Striker', 'Conheça o tênis Fila Striker, projetado para corredores que buscam alto desempenho aliado ao conforto, combinando um design moderno com tecnologias para a sua corrida. Seu cabedal em alto relevo com micromesh de monofilamento garante excelente respirabilidade e ajuste preciso. O puxador traseiro facilita o calce, enquanto a entressola em EVA macio assegura ótimo amortecimento a cada passada. Já o solado emborrachado oferece aderência e durabilidade superiores, tornando o Striker a escolha ideal para corredores de todos os níveis. Não perca tempo e garanta o seu!', 529.89, 329.88, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-825b6-mqbwdqh4nhfz43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F22198869690', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998036406', 'Sandália Pegada Masculina Couro 2 em 1 131662', 'A Sandália Pegada 131662 é ideal para você passar o dia com conforto, sem abrir mão do estilo. Seu cabedal com é confeccionado em couro, com costura que liga o solado ao cabedal, garantindo máxima durabilidade. Sua palmilha é feita em EVA, sendo anatômica e super macia. O solado conta com a tecnologia AMORTECH, tubos absorvedores de impacto, que trazem estabilidade ao caminhar. Versátil, a sandália possui uma tira ajustável 2 em 1, uma sandália que vira chinelo. Aproveite e garanta a sua!', 289.89, 214.88, NULL, 'Men Shoes > Sandals & Flip Flops > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-8262z-mj5oim9px8ubb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F22998036406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899090190', 'VENTILADOR DE TORRE SPIRIT MAXXIMOS ELEGANT TS700 PRETO E PRATA - 110V', 'Ventilador Torre Spirit Maxximos Elegant TS700 Preto Prata 110v O Ventilador Torre SPIRIT maXXimos Elegant é a solução de ventilação portátil mais slim e elegante do mercado. Com o refinado design SPIRIT, de linhas prolongadas e vincos arrojados, o visual encanta ao mesmo tempo que é delicado o suficiente para se encaixar em todo tipo de decoração. Com o Ventilador Torre SPIRIT maXXimos Elegant você consegue uma ventilação adequada a todo o ambiente, com três velocidades e função Oscilante que distribui igualmente a ventilação. Discreto e extremamente portátil, o Torre SPIRIT maXXimos Elegant TS700 possui 75 cm de altura, ideal para se adequar a todo tipo de ambiente. Possui sistema de controle mecânico integrado à parte superior do produto, tornando seu uso muito fácil e agradável. A ventilação pode ser acionada em três opções de velocidade, tanto de forma estática, quanto com oscilação, que distribui o vento em 75º de angulação. O Torre SPIRIT maXXimos Elegant TS700 além de compor a decoração serve como solução de climatização para diversos ambientes e pela sua dimensão compacta e design slim é facilmente transportado e inserido em todos os ambientes. O visual moderno, leve e alongado do Ventilador Torre SPIRIT maXXimos Elegant TS700 o torna adequado a todos os ambientes e estilos de decoração. Apenas não é indicada sua utilização em ambientes abertos e sujeitos às ações da natureza. Informações técnicas Oscilação: Sim, acionável pelo controle manual, de 75°. Cor: Preto e Prata Eficiência: Baixo Consumo - Certificado de Conformidade INMETRO Garantia: 2 Anos Potência Nominal: 35W Tipo de Controle: Controle mecânico de 3 velocidades e oscilação Funções Especiais: Função Oscilante até 75° Direcionamento do Vento: Oscilante até 75° Graus. Esta angulação propicia uma circulação de ar mais eficiente. Altura do Ventilador Torre: 75 cm de altura Peso do Produto: 2 Kg Design: Design SLIM - Os mais finos e elegantes do mercado. Itens Inclusos 1 Ventilador Torre Slim 75cm Manual de instruções', 480.0, 480.0, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lobmndlrmisp91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F950046979%2F21899090190', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
