INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297478291', 'Porta Sacada de Alumínio 4 Folhas 210 x 180cm com Fechadura Linha 25 Branco Esquadrias Bergamo Branco', 'Porta de Correr de Alumínio Branco Sacada 4 Folhas Linha 25 - Bergamo Você irá encontrar esta porta de correr de alumínio em 2 medidas: 210cm de altura, com as larguras de 180 e 200 cm. Uma excelente opção para quem busca uma porta de alumínio com grande durabilidade e resistência. Dicas de Instalação Ao adquirir uma porta de correr é importante notar que sua instalação deve-se respeitar o nivelamento, verifique o alinhamento das extremidades com uma ferramenta de nível para garantir a qualidade da instalação. Especificações Lado de Abertura: No centro, Sendo 2 folhas fixas nas laterais e 2 móveis Largura do vão de passagem: 210 x 180 = 83 cm / 210 x 200 = 93 cm Espessura e linha do perfil do Alumínio 25 – 25mm x 50mm Acompanha vidro de 3mm tipo liso e incolor Peso (kg): 69 Elétrica: Não Garantia: 12 Meses Altura (cm): 200 Largura (cm): 180 Cor do Vidro: Incolor Espessura (cm): 8 Possui Grade: Não Tipo de Vidro: Liso Acompanha Trinco: Não Desenho do Vidro: Transparente Escala de Brilho: Semi-Brilho Lado de Abertura: Central Textura da Porta: Lisa Acompanha Batedor: Não Acompanha Batente: Sim Acompanha Puxador: Não Origem do Produto: Nacional Ambiente Principal: Sala de Estar Espessura do Vidro: 3 Largura do Batente: 8 Acompanha Dobradiça: Não Acompanha Fechadura: Sim Acompanha Guarnição: Não Possui Isolamento Acústico: Não Acompanha Manual de Instalação: Sim Dimensão da Maquina da Fechadura: 25 Material Principal Construção e Acabamento: Alumínio Marca: Esquadrias Bergamo Cor: Branco Cor do Produto: Branco Itens Inclusos: 1 Porta Cor Predominante: Branco Linha ou Coleção: Linha 25 Medida do Vão (A x L): 83 cm Tamanho do Produto: 210cm x 180cm', 2514.48, 2514