INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19797988567', 'Boneco Funko Pop! Futurama - Leela', 'Complete sua coleção de Futurama com o Boneco Funko Pop! Leela. Esta figura de aproximadamente 12 centímetros captura a icônica Turanga Leela, a capitã corajosa e mutante da Planet Express. Perfeita para os fãs da série, Leela é uma adição indispensável para qualquer coleção Funko Pop! Não perca a chance de recriar aventuras espaciais com este boneco detalhado e divertido!', 149.99, 79.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7rfgs-m4agst1w7nwobd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F19797988567', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
