INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698349179', 'Mangueira de Saída com Luva para Consul/Brastemp 130cm Afa 360209100', 'Mangueira de Saída com Luva para Consul/Brastemp 130cm Afa 360209100 A Mangueira de Saída com Luva para Consul/Brastemp 130cm (Afa 360209100) é a escolha ideal para quem busca uma solução eficiente e prática para substituir a mangueira do seu eletrodoméstico. Com 130 cm de comprimento, ela oferece a flexibilidade necessária para garantir uma instalação perfeita, compatível com diversos modelos dessas marcas. Fabricada com materiais de alta qualidade, a mangueira garante durabilidade e resistência, proporcionando maior segurança e eficiência no funcionamento do seu equipamento. A instalação da mangueira é rápida e simples, contando com uma luva que assegura uma vedação perfeita, evitando vazamentos e proporcionando um desempenho otimizado. Ideal para quem precisa de uma peça de reposição confiável, ela é perfeita para o bom funcionamento de sua lavadora, secadora ou outro eletrodoméstico que utilize essa mangueira específica. Com design que prioriza a resistência e a praticidade, essa mangueira é uma solução econômica e eficaz para manter seu aparelho funcionando perfeitamente. Invista na qualidade e performance para a sua casa com a Mangueira de Saída com Luva para Consul/Brastemp 130cm (Afa 360209100) e tenha a tranquilidade de contar com um produto que vai atender suas necessidades de forma eficiente e segura.', 25.9, 25.9, NULL, 'Home Appliances > Large Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd3p-m7qhq0194hxj1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F22698349179', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599443449', 'Cooktop 5 Bocas Electrolux KE5GR Efficient a Gás Mesa de Vidro Preto Bivolt', 'Cooktop 5 Bocas Electrolux KE5GR Efficient a Gás Mesa de Vidro Preto BivoltEscolha ideal para quem busca praticidade e elegância na cozinha. Com mesa de vidro temperado preto, ele oferece um visual moderno e sofisticado, além de facilitar a limpeza no dia a dia. Seu design compacto se adapta perfeitamente a diferentes ambientes, proporcionando mais funcionalidade sem abrir mão do estilo. Equipado com acendimento automático, garante mais agilidade e segurança ao preparar suas receitas favoritas. Com 5 queimadores eficientes, o cooktop proporciona potência e controle preciso de chama, permitindo o preparo de diversos pratos com rapidez e uniformidade. As grades individuais resistentes oferecem maior estabilidade para panelas de diferentes tamanhos, trazendo mais segurança durante o uso. Além disso, seu funcionamento a gás com alimentação bivolt garante versatilidade e compatibilidade com diferentes instalações elétricas. Pensado para facilitar a rotina, o modelo KE5GR combina desempenho e durabilidade com um excelente custo-benefício. Seu acabamento de alta qualidade aliado à tecnologia Efficient contribui para um melhor aproveitamento do gás, tornando o preparo mais econômico. Ideal para quem deseja renovar a cozinha com um produto funcional, bonito e confiável, elevando a experiência culinária em todos os momentos.', 685.76, 685.76, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-81zuj-mmvrk56zyvpd6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F22599443449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
