INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197156538', 'Scrunchie Rosé Velvet Lanossi', 'Os scrunchies dos anos 90 voltaram! O Scrunchie Rosé Velvet Lanossi dá um toque especial no seu penteado e também pode ser utilizado como acessório de pulso. Com revestimento de tecido, o prendedor de cabelo não danifica o cabelo e serve para todos os tipos de cabelo. Vem com uma unidade em rosa.', 29.9, 29.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfhc-m968y11bxlqxd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22197156538', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8564529304', 'Esquadro poliestireno 16cm x 45 graus 522 Acrimet', 'Esquadro em poliestireno, com escala gravada por transferência de imagem, garantindo alta precisão. Possui micro ressaltos na face que entra em contato com o papel para evitar o desgaste da escala. Cantos arredondados para maior segurança. Detalhes: - Modelo: 45° graus - Composição: poliestireno', 14.74, 14.74, NULL, 'Stationery > School & Office Equipment > Rulers, Protractors & Stencils', 'https://cf.shopee.com.br/file/sg-11134201-825zm-ml4yk2k1k9vsea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F8564529304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13832811537', 'Teclado multimídia preto USB TC206 Multilaser', 'Teclado multimidia preto usb - TC206 - Multilaser Detalhes: - Para jogar, fazer trabalhos, o Teclado Multimídia da Multilaser pode te ajudar muito. - Com 107 Teclas e 8 atalhos no teclado vai deixar tudo mais rápido e confortável', 65.88, 65.88, NULL, 'Computers & Accessories > Keyboards & Mice > Keyboards', 'https://cf.shopee.com.br/file/sg-11134201-7qvdj-lkgvt7n0vq2ode', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F13832811537', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697887606', 'Pincel marca texto Marking Amarelo Fluorescente com 1 unidade Bic', 'INMETRO 006403/2013 O Marcador que escreve até 3.5x mais que a concorrência! O Marcador de Texto Fluorescente BIC da linha Marking destaca-se pelo brilho de alta intensidade. Com ponta resistente, possibilita uma escrita firme, sem afundamento da ponta. Chanfrada, ela também permite a marcação em traçado duplo: fino para sublinhar e grosso para destacar. Possui boa aderência, tanto em superfícies de papel comum quanto de papel fax e cópias. A cor da tinta não perde intensidade com o tempo, além de acompanhar tampa transparente para enxergar a ponta. A BIC oferece excelentes produtos para acompanhar a volta às aulas com excelência e liderança! Detalhes: - 1 Marcador de texto amarelo fluorescente - Ponta Chanfrada - Traço 1.5 mm a 3.5 mm - Tintas fluorescentes brilhantes - Boa resistência à luz - Destaca-se mesmo em papel de fotocópia e fax - Não contém PVC - As imagens podem ser ilustrativas - Qualidade BIC.', 17.44, 14.65, NULL, 'Stationery > Writing & Correction > Highlighters', 'https://cf.shopee.com.br/file/sg-11134201-824ih-mphxkh7r241ue5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F18697887606', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094193355', 'Mop Limpa Vidros com Cabo Multi Noviça Bettanin', 'Mop Limpa Vidros com Cabo Multi Noviça Bettanin. O Mop Limpa Vidros com Cabo Multi Noviça Bettanin é 2 em 1: limpa e seca. Com cuidado e praticidade, protege suas mãos de produtos químicos e alcança os cantos mais difíceis, devido ao seu cabo extensor e a sua haste flexível. A manta de limpeza profunda lava e o rodo permite que você finalize a limpeza com a secagem dos vidros. Possui cabo extensor de 90cm. Dimensões do cabo estendido: 90 x 1,5 x 1,5 cm Dimensões do cabo recolhido: 60 x 1,5 x 1,5 cm', 69.9, 54.9, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/sg-11134201-7ra2r-mbcvy0xrzp8w34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22094193355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098056589', 'Jogo de Toalhas de Banho 6 Peças Algodão Felpuda Samba Camesa - BF Casa', 'Renove seu enxoval com o Kit de Toalhas de Banho Samba da Camesa. Com tecido macio e resistente, estas toalhas oferecem um toque suave muito agradável para sua pele. Com fios de algodão felpudo, elas proporcionam alta absorção, secagem rápida e maior durabilidade para o uso diário. Alta absorção e toque macio 400g/m² de gramatura Fios em algodão Secagem rápida Produzidas com uma gramatura de 400g/m² e tamanho de 68 cm x 132 cm, as toalhas Camesa oferecem um toque aconchegante e ótima capacidade de absorção. A barra decorativa bordada em poliéster macio adiciona um toque sofisticado, deixando seu banheiro ainda mais elegante. Ideal para quem valoriza qualidade e beleza na rotina de cuidados pessoais. Contém: 06 Toalhas de Banho (68 cm x 132 cm) Características: Composição: Corpo da toalha em algodão Composição da barra bordada: 40 Poliéster Gramatura: 400g/m² Excelente absorção Toque macio Corpo liso e acabamento premium Modelo: Samba Marca: Camesa Instruções de lavagem: Lavar com temperatura máxima de 40°C Secar em baixa temperatura Passar a ferro até 150°C Não alvejar e não limpar a seco', 219.0, 160.0, NULL, 'Home & Living > Bathrooms > Towels & Bathrobes', 'https://cf.shopee.com.br/file/sg-11134201-7rep8-m2s6y0m13wu152', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1264071501%2F22098056589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256753408', 'CHAVE COMBINADA C/CATRACA 24MM R07100240', '📋 Ficha Técnica (Gedore RED R07100240 - 24mm) Compilado de informações oficiais da Gedore e lojas especializadas: Especificação Detalhe Marca / Modelo Gedore RED / R07100240 Medida 24 mm Tipo Chave Combinada com Catraca (lado estrela com mecanismo de catraca) Material Aço cromo-vanádio Acabamento Cromado fosco acetinado, que oferece proteção contra corrosão e maior durabilidade Quantidade de Dentes da Catraca 72 dentes Ângulo de Retorno 5° (graças aos 72 dentes) Posição da Boca 15° (inclinada para facilitar o acesso) Comprimento Total Aproximadamente 285 mm Normas Técnicas Fabricada conforme DIN 3113 e ISO 3318 Peso Cerca de 0,50 kg ⚙️ Características e Diferenciais Catraca de 72 Dentes: O mecanismo de catraca no lado estrela é o principal destaque. Com 72 dentes, o movimento necessário para engatar o próximo dente é de apenas 5°, o que é perfeito para trabalhar em locais de difícil acesso onde o movimento da chave é limitado . Versatilidade: Ela possui dois lados funcionais : Lado Estrela (com catraca): Para desapertar ou apertar de forma rápida, sem precisar remover a chave do parafuso a cada movimento. Lado Boca (aberta): Para usar quando for necessário encaixar a chave por baixo ou de lado, ou para aplicar o torque final. Design e Durabilidade: Fabricada em aço cromo-vanádio, um material conhecido por sua resistência, e com acabamento cromado fosco que protege contra ferrugem e garante uma pega segura . 📦 Conteúdo da Embalagem Ao adquirir a chave avulsa, a embalagem contém: 01 Chave Combinada com Catraca de 24mm . ✅ Aplicações e Indicações Devido ao seu tamanho (24mm), esta chave é robusta e indicada para: Aplicações automotivas pesadas: Suspenções, freios, e componentes do motor . Manutenção industrial e mecânica em geral . Montagem de máquinas e estruturas metálicas que utilizam parafusos de grande porte. Uso profissional intenso em oficinas e indústrias. 💡 Informações Importantes Garantia: A Loja do Mecânico oferece garantia de 1 ano, porém a ficha técnica do produto no mesmo site menciona 8 anos e 3 meses, o que demonstra a alta durabilidade que a Gedore oferece para esta ferramenta . Vale confirmar essa informação no momento da compra. Disponibilidade: Por ser uma ferramenta de tamanho grande (24mm) e especializada, é comum que seja vendida como peça avulsa e não em jogos. Se você precisa de uma chave para parafusos grandes e quer a agilidade de uma catraca, este modelo da Gedore RED é uma excelente escolha.', 133.08, 129.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820l6-mlwgl72uwk5cad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979559296%2F58256753408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49760767714', 'Armário de Cozinha Modulada Completa Suspensa 251,5cm Milano Multimóveis MP2405', 'Transforme seu ambiente em um espaço mais funcional, organizado e elegante com a Cozinha Modulada Completa Suspensa 251,5cm Milano Multimóveis MP2405. Ideal para quem busca praticidade no dia a dia sem abrir mão de um visual moderno, ela foi projetada para otimizar cada centímetro do ambiente, facilitando a rotina e proporcionando mais conforto no preparo das refeições e na organização dos utensílios. Muito mais do que uma cozinha completa, a Milano é uma solução completa para o seu lar. Com 7 portas, incluindo modelos de correr em vidro fumê temperado que agregam sofisticação ao ambiente, e portas basculantes com pistão a gás que garantem abertura suave, ela oferece praticidade em cada detalhe. A torre quente facilita o uso de forno e micro-ondas. Seu design minimalista com puxadores alongados e acabamento acetinado valoriza o espaço, trazendo harmonia e modernidade para sua cozinha. Especificações Técnicas: - Material de alta qualidade: produzida em MDP com frontais em MDF de 15mm e acabamento acetinado, garantindo resistência, durabilidade e fácil limpeza. - 4 módulos individuais: permitem a montagem de acordo com a disposição do espaço. - Amplo espaço de armazenamento: com 7 portas, oferece excelente capacidade para manter sua cozinha sempre organizada. - Portas funcionais e sofisticadas: conta com 2 portas de correr em vidro fumê temperado e 2 portas basculantes com pistão a gás. - Balcão com tampo removível: compatível com pia de 120cm (pia não inclusa), é versátil e funcional. - Abertura suave da gaveta: corrediças telescópicas que garantem deslizamento leve, silencioso e maior durabilidade no uso. - Espaço dedicado para forno e micro-ondas: otimiza o ambiente e oferece praticidade na rotina. - Espaço para colocação de fogão ou geladeira. - Design moderno: puxadores alongados minimalistas em ABS que valorizam o visual e combinam com diferentes estilos de decoração. Conteúdo da Embalagem: 1 (um) Paneleiro Torre Quente 61,5cm 1 (um) Armário Aéreo 70cm 1 (um) Armário Aéreo c/ Portas de Vidro 120cm 1 (um) Balcão com Tampo 120cm Manual de Montagem e Kit Ferragem Dimensões do Produto Montado: Altura: 184,5cm | Largura: 251,5cm | Profundidade: 52cm *Você pode consultar as medidas detalhadas na imagem técnica do produto. As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração, eletrodomésticos e pia não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 1979.99, 1779.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-822ya-moe7q4lnzmktcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F49760767714', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17288441409', 'Aparador Cantinho do Café com Pés Quadrados e 2 Portas Multimóveis Preto/Natural', 'O Aparador Cantinho do Café com Pés Quadrados e 2 Portas Multimóveis é produzido em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade, facilidade na limpeza, além de um acabamento superior. Com 2 portas, possui um excelente espaço interno para organizar louças, bebidas e demais objetos (a prateleira interna suporta 8 Kg e o tampo 9 Kg). Os pés quadrados, em polipropileno, facilitam na hora da limpeza. Os amantes de café poderão deixar seu cantinho mais charmoso e prático para curtir os melhores momentos com os amigos e família, saboreando um delicioso cafezinho. Conteúdo da Embalagem: 1 (um) aparador 1 (um) kit com 4 pés quadrados Dimensões do produto montado: Altura: 74cm | Largura: 63cm | Profundidade: 32cm *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 359.99, 239.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-22100-si8x9x9h44iv18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F17288441409', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20251107986', 'Assento Sanitário Tampa De Vaso Sanitário Oval Almofadado Slim Deca Icasa Logasa Universal Herc', 'COMERCIAL VIPASA DISTRIBUIDORA O Assento Sanitário oval Herc é confeccionado com matéria-prima nova, atóxica, o que garante melhor acabamento e maior durabilidade. Reguláveis a todos os vasos convencionais oval. Possui Superfície lisa que impede o acúmulo de sujeira e de germes. Além de duráveis, de fácil limpeza e manuseio higiênico, o assento sanitário Herc possui rebaixo higiênico que evita contatos indesejáveis e uma solução exclusiva que mantém o assento em pé quando aberto, mesmo em caixa acoplada. Fabricado em polietileno, tampa e porcas em polipropileno, parafusos em nylon. Características técnicas: Fabricado em EVA; Preenchido em Poliuretano; Acabamento brilhante, leve, resistente e macio; Suporta carga de até 130 kg; Fácil instalação; Parafusos possibilitam ajuste de distância para fixação a louça. Composição: Conjunto de fixação; Assento; Tampa. Uso recomendado: Adaptável a todos os tipos de louças sanitárias ovais convencionais Assento almofadado para vaso sanitário Assento em PVC Herc Tampa almofadada para banheiro Assento de vaso sanitário confortável Tampa para vaso sanitário almofadada Assento sanitário macio Herc Tampa de banheiro resistente Assento de PVC para sanitários Tampa para vaso modelo 2385 Assento acolchoado para banheiro Assento de banheiro durável Tampa de vaso sanitário Herc Assento sanitário fácil de limpar Tampa de banheiro universal Assento confortável em PVC Tampa almofadada ergonômica Assento sanitário com design clássico Assento para banheiro reforçado Tampa de vaso com acabamento almofadado Assento para banheiro Herc 2385 Assento almofadado Herc 2385 Tampa de vaso sanitário almofadada Assento de PVC para banheiro Tampa confortável para vaso sanitário Assento sanitário universal Herc Tampa de banheiro resistente em PVC Assento acolchoado para banheiro Tampa para vaso modelo almofadado Assento sanitário de alta qualidade Assento almofadado durável Herc COMERCIAL VIPASA DISTRIBUIDORA', 69.99, 64.99, NULL, 'Home & Living > Bathrooms > Toilet Bowls, Seats & Covers', 'https://cf.shopee.com.br/file/sg-11134201-22090-5f0u6wacq4hvb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F20251107986', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26389525449', 'Kit Chuteira Masculina Indoor Quadra Futebol Salao Costurada + Mochila e Meiao', 'Brilhe dentro de quadra com nossa chuteira sintética de última geração! Projetada para proporcionar agilidade e precisão em ambientes fechados, esta chuteira oferece um ajuste perfeito e durabilidade excepcional. Domine o jogo com confiança, sabendo que está calçando a qualidade e o conforto incomparáveis de nossa chuteira sintética. Não deixe essa oportunidade escapar. Adquira já a sua e seja imbatível dentro de quadra! Porque o futebol não é apenas sobre fazer gols, mas sobre a paixão que você coloca toda vez que chuta a bola. É por isso que você precisa de calçados que te acompanhem em cada passo. Com as chuteiras Light, você poderá viver a incrível experiência de aproveitar todas as suas habilidades e atingir seus limites no campo. Nossos Produtos possuem garantia contra defeito de fabricação! Estilo: Quadra Material exterior: Sintético Material da sola: PVC Tipo de ajuste: Cadarço Em caso de kit: Os acessórios do kit são de cor sortida, podendo ser enviado de acordo com a disponibilidade do estoque! • A medida da numeração é feita com base no tamanho aproximado da palmilha, sempre comprar com 0,5 cm de folga, por maior segurança. • Evite problemas com trocas por tamanho, decida com atenção a numeração deseajada seguindo a tabela a cima! Tabela de medidas: 37 - 24,50cm 38 - 25,00cm 39 - 26,00cm 40 - 26,50cm 41 - 27,00cm 42 - 28,00cm 43 - 29,50cm 44 - 30,00cm INSTRUÇÕES DE LAVAGEM DA CHUTEIRA • Não lavar calçados em máquina de lavar roupas, usar apenas pano úmido • Ao lavar seu calçado, a secagem deve ser realizada na sombra Garantia do vendedor: 7 dias', 79.99, 55.99, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mby1pxjk1cbr28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908041635%2F26389525449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18157593747', 'Painel para TV até 60" Multimóveis Nairóbi FG2739 Madeirado', 'O Painel TV 60" com prateleiras de vidro Nairóbi Multimóveis é uma escolha inteligente e super em conta para deixar o seu ambiente bonito e organizado. Produzido em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade, resistência e facilidade na limpeza, possui painel para TV de até 60” (suporta até 28 Kg) com espaçamento para a passagem dos fios, o que deixa um visual clean e os cabos organizados. Possui 4 prateleiras em vidro, que deixam o móvel mais requintado e 2 nichos para acomodar os equipamentos eletrônicos. Prático e moderno para deixar sua sala de estar confortável para aproveitar o aconchego do seu lar. Conteúdo da Embalagem: 1 (um) painel para TV 1 (um) kit com 4 prateleiras de vidro Kit ferragem Manual de montagem Dimensões do produto montado: Altura: 108 cm | Largura: 191 cm | Profundidade: 31,5 cm Tamanho Painel TV: 136 x 90cm *Devido as variações de tamanho dos televisores no mercado, sugerimos que verifique as medidas da sua TV e compare com o painel antes de efetuar a compra. *Não recomendamos utilizar suporte de TV articulado. *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 609.9, 439.99, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-22100-2g8yu88gv4iv62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F18157593747', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20296980103', 'Sapateira 1 Porta com Espelho Jade Plus Multimóveis V6007', 'A Sapateira 1 Porta com Espelho Jade Plus Multimóveis é produzida em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência. Super versátil, pode ser utilizada como sapateira, estante para livros ou armário multiuso. Possui 4 prateleiras (suportam 6kg cada), sendo 2 fixas e 2 móveis, e a porta pode ser montada de ambos os lados, conforme sua preferência. Compacta, é uma excelente opção para manter seus sapatos organizados e otimizar seu espaço, para que você possa aproveitá-lo da melhor maneira possível. Cada prateleira comporta 3 pares de calçado, totalizando 15. Os espelhos na porta deixam o móvel mais requintado, criando um ambiente moderno e charmoso. Os espelhos são de vidro (o que evita que a imagem fique distorcida) e lapidados, ou seja, passam por um processo para que as bordas não fiquem cortantes, o que garante maior segurança. Com design minimalista e de fácil montagem, pode ser utilizada em qualquer ambiente. Conteúdo da Embalagem: 1 (uma) sapateira 1 (um) kit com 4 espelhos Dimensões do produto montado: Altura: 147 cm | Largura: 55 cm | Profundidade: 37,5 cm *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 709.9, 459.99, NULL, 'Home & Living > Home Organizers > Shoe Storage Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7repv-m90ppp483oup9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F20296980103', NULL, NULL, '2026-07-