INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998582116', 'Jogo De Serras Copo Bosch Para Madeira com 11 Pcs', 'Ficou alguma dúvida? Faça sua pergunta, ficaremos satisfeitos em lhe atender bem. Emitimos Nota Fiscal. Qualidade, preço Justo e atendimento Perfeito. Jogo de serras copo para madeira Bosch com 11 peças Vantagens: - O jogo de Serras copo para madeira acompanha 11 serras copo, 2 suportes compatíveis com os diâmetros das serras, uma porca e uma broca guia. Instalação feita diretamente no mandril compatível e permite uso imediato, ela efetua cortes em materiais macios como madeira, aglomerado de madeira, placas acústicas, ideal para pequenas instalações. Com este Jogo de serras copo para madeira da Bosch, você terá uma diversidade de serras para atender rapidamente suas necessidades. - Uso com 6 meses de garantia Bosch. Características: - Tipo de embalagem: Maleta; - Acabamento do acessório: Alumínio fundido; - Composição: Aço carbono; - Uso indicado: Madeira macia, placas de aglomerado de madeira, vigas de madeira, placas acústicas e gesso; - Público Alvo: Instaladores de iluminação, marceneiros, gesseiros. Dados Técnicos: - Dimensões da embalagem (AxLxP): 5 x 11 x 19,5 cm; - Peso: 0,540 kg. Componentes incluídos na embalagem: - 1 Serra copo para madeira 22 mm; - 1 serra copo para madeira 25 mm; - 1 serra copo para madeira 29 mm; - 1 serra copo para madeira 35 mm; - 1 serra copo para madeira 38 mm; - 1 serra copo para madeira 44 mm; - 1 serra copo para madeira 51 mm; - 1 serra copo para madeira 68 mm; - 1 suporte para serra copo SW8; - 1 suporte para serra copo 1/4''; - 1 porca; - 1 broca guia. Ficou alguma dúvida? Faça sua pergunta, ficaremos satisfeitos em lhe atender bem. Emitimos Nota Fiscal. Qualidade, preço Justo e atendimento Perfeito.', 139.9, 128.36, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-masqxt5vef0v9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F350962329%2F22998582116', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
