INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23411949376', 'Termogênico 2Hot 200g - Max Titanium', 'COMPOSIÇÃO DO ANÚNCIO: 01 - 2hot 200g - Max Titanium 2HOT possui, dentre seus ingredientes, taurina e a cafeína, que auxilia no aumento do estado de alerta e na melhora da concentração. Além disso, conta com alto teor de vitaminas que auxiliam no metabolismo energético contribuindo para o bem-estar e no fornecimento de energia. RECOMENDAÇÃO DE USO Ingerir uma porção pela manhã e outra antes do almoço ou conforme orientação de nutricionista ou médico. INGREDIENTES Mix de vitaminas e minerais (bitartarato de colina, ácido ascórbico (vitamina C), nicotinamida (vitamina B3), pantotenato de cálcio (vitamina B5), riboflavina (vitamina B2), piridoxina (vitamina B6), tiamina mononitrato (vitamina B1), ácido fólico, picolinato de cromo (cromo), biotina (vitamina H), cianocobalamina (vitamina B12)), taurina (800mg/200mL), glucoronolactona (500mg/200mL), maltodextrina, chá verde, cafeína anidra (70mg/200mL), gengibre, inositol (40mg/200mL), pimenta vermelha, acidulantes ácido málico e ácido ascórbico, aromatizantes, antiumectante dióxido de silício, regulador de acidez citrato de sódio, edulcorante sucralose e corantes artificiais amaranto e azul brilhante. Não Contém Glúten. DESTAQUES • Ação rápida • Alto teor de vitaminas ? Auxilia no metabolismo energético • 70mg de cafeína por porção ? Auxilia no aumento do estado de alerta e melhora da concentração • 800mg de taurina por porção • Pimenta vermelha • Gengibre • Chá verde MODO DE PREPARO Misturar 6g (1 dosador raso) de 2HOT em 200mL (1 copo) de água gelada e agitar com a ajuda de uma colher até completa dissolução. Beber imediatamente. ADVERTÊNCIAS Crianças, gestantes, nutrizes, idosos e portadores de enfermidades: consultar o médico antes de consumir o produto. Não é recomendado o consumo com bebida alcoólica. ALERGÊNICO Pode conter derivados de leite, ovo e soja. Não Contém Lactose. IMAGEM MERAMENTE ILUSTRATIVA TABELA PODE VARIAR CONFORME SABOR', 109.9, 92.5, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-820lm-mlqs7n9v7thj35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F418949963%2F23411949376', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
