INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997085425', 'Terapia cognitivo-comportamental', 'O livro clássico Judith S. Beck sobre a terapia cognitivo-comportamental (TCC), recurso fundamental para terapeutas e estudantes da área da psicologia, chega a sua 3ª edição amplamente atualizado. Além de apresentar os princípios da técnica, o livro aborda como desenvolver a relação terapêutica, fazer uma conceitualização de caso, planejar o tratamento, estruturar sessões e implementar técnicas cognitivo-comportamentais e experienciais. Ao longo do livro, também disponível no formato e-book, o leitor poderá acompanhar os casos de dois clientes, um com depressão e ansiedade moderada, e outro com traços de personalidade borderline, que ilustram como um terapeuta habilidoso administra a TCC. A autora também apresenta a terapia cognitiva orientada para a recuperação (CT-R) ao lado da TCC tradicional, inclui dicas clínicas, questões para reflexão e exercícios práticos, além de demonstrar como integrar estratégias de modalidades como terapia de aceitação e compromisso, terapia comportamental dialética e terapia cognitiva baseada em mindfulness ao tratamento.', 163.76, 163.76, NULL, 'Books & Magazines > Books > Psychology & Relationships', 'https://cf.shopee.com.br/file/sg-11134201-7rbmr-lna0a2zzutnwfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22997085425', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
