INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49856150819', 'RECHEIO ARTESANAL CREME LEITINHO 1,01KG VABENE', 'Produto com cremosidade e sabores exclusivos, a linha artesanal VaBene oferece recheios equilibrados com estrutura suave, valorizando suas receitas com um toque especial. Ideal Para: Ideal para rechear tortas, bolos, pavês, cupcakes, sonhos e donuts. Informações Importantes: Para melhor conservação, manter a embalagem devidamente fechada e em local seco, fresco e inodoro. Depois de aberto, consumir em até 30 dias. Pode haver separação entre óleos e sólidos. NOVA COMPOSIÇÃO Ingredientes: Gordura vegetal, leite em pó, açúcar, soro de leite em pó, sal, emulsificantes lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E SOJA. PODE CONTER AMENDOIM, AMÊNDOA, AVELÃ, CASTANHA-DE-CAJU, CASTANHA-DO-PARÁ E CEVADA. CONTÉM LACTOSE. CONTÉM GLÚTEN. Prazo de validade: 12 meses.', 56.85, 49.85, NULL, 'Food & Beverages > Cooking Essentials > Others', 'https://cf.shopee.com.br/file/sg-11134201-8261v-mkmhmh4mxt6sa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F49856150819', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
