INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18397746960', 'DEMON SLAYER - KIMETSU NO YAIBA 5 - PANINI', 'Tanjirou, Zenitsu e Inosuke enfrentam uma ooderosa "família" de onis no Monte Natagumo. Zenitsu está caído devido ao veneno de um dos inimigos, enquanto Tanjirou e Inosuke enfrentam um oni gigantesco ao qual chamam de "pai". Todos estão no limite de suas forças e prestes a chegar ao total esgotamento mental e físico. Porém, ainda há uma ameaça muito maior dentro dessa "família"... Haverá saída para os três?', 43.1, 43.1, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-824gg-mffk9favmcjv6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F18397746960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699647355', 'Pneu Aro 17 Michelin 180/55 ZR17 M/C 73W Power 5', 'Pneu Aro 17 Michelin 180/55 ZR17 M/C 73W Power 5 Sobre o pneu: O novo pneu MICHELIN POWER 5 utiliza as mesmas tecnologias do pneu oficial do MotoGP, com máxima segurança e aderência excepcional para você curtir a sua viagem. Sobre a marca: A marca Michelin foi fundada em 1889 em Clermont-Ferrand, França e com o passar dos anos tornou-se uma referência em pneus. Informações Adicionais: - Marca: Michelin - Modelo: Power 5 - Medida: 180/55 ZR17 - Largura: 180 - Perfil: 55% - Aro: 17 - Índice de carga: 73- 365 Kg - Índice de velocidade: W- 270 km/h - Posição do veiculo: Traseiro - Tipo de construção: Radial - Run Flat: Não - Tipo de montagem: Sem câmara - Sidewall: Letras pretas - Garantia: 5 anos contra defeitos de fábrica Aplicações: - HONDA: CB 1000 R, CB 1000 R ABS, CB 600F, CB 600F ABS, CB 600F HORNET, CB 600F HORNET ABS, CB 650F ABS, CB 650F STD, CB 650R ABS, CBR 1100, CBR 600 F, CBR 600 F ABS, CBR 600 RR, CBR 650 F ABS, CBR 650 F STD, CBR 650 R ABS, CBR 650F ABS, CBR 650F STD OBSERVAÇÕES: IMAGEM MERAMENTE ILUSTRATIVA VERIFIQUE SEMPRE NO VEÍCULO QUAL É A MEDIDA EXATA DO SEU PNEU', 1372.59, 1303.97, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd6c-m72otsnh6fc952', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F20699647355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253007543', 'INVENCIVEL 06 - PANINI', 'Mark é levado para outro planeta para que possa salvá-lo. Seria ele sua única esperança ou a origem do pior desastre que já os atingiu? Como se os eventos do volume 3 não fossem o suficiente, a vida de Mark sofre uma nova reviravolta. Segredos serão revelados e uma grande guerra parece inevitável!', 44.9, 44.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-8262o-mja4vf342mtj59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F58253007543', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5883091373', 'MENTES PERIGOSAS - EDICAO COMEMORATIVA - PRINCIPIUM', 'Eles podem ter várias faces. Disfarçados de pessoas de bem, autora de mentes ansiosas ocultam o que realmente são: seres calculistas, manipuladores e insensíveis aos sentimentos alheios. Estão ao nosso lado no trabalho, na escola, na vizinhança e no círculo familiar e, a qualquer momento, podem gerar destruição em nossa vida. Eles são os psicopatas, uma ameaça real e silenciosa para toda a sociedade. Psicopatas não sentem culpa nem compaixão. Não se arrependem. Não nutrem nenhum senso de empatia ou responsabilidade em relação aos outros. Esvaziados de emoção, são capazes de passar por cima de tudo e de todos para satisfazer seus objetivos. Em Mentes perigosas, dra. Ana Beatriz Barbosa Silva revela esse sombrio transtorno de personalidade que atinge cerca de 4% da população mundial e mostra ao leitor como se prevenir contra as perversidades de uma mente psicopata. Sucesso editorial absoluto, esta edição de aniversário inclui dois capítulos novos. Um sobre psicopatas no ambiente em que deveríamos nos sentir mais seguros ― a família ― em que a autora relata conhecidos e estarrecedores casos de psicopatia. E outro sobre a conhecida relação entre psicopatia e poder, que trata de grandes tiranos da história que usaram o poder político para dar vasão aos seus impulsos mais perversos.', 67.4, 67.4, NULL, 'Books & Magazines > Books > Psychology & Relationships', 'https://cf.shopee.com.br/file/sg-11134201-82273-mhnkr4t75n9cc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F5883091373', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210276135', 'Biscoito de Leite Passatempo', 'O Biscoito Passatempo Leite é um clássico que marcou gerações! Com sabor suave e levemente adocicado, é perfeito para acompanhar o café, o lanche da tarde ou para matar a vontade de um docinho. Com seus desenhos divertidos, estimula a imaginação das crianças e torna os momentos em família ainda mais gostosos.', 4.99, 4.99, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/sg-11134201-825ab-mqneldrp5jpn08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554802%2F58210276135', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207426168', 'Kit com 2 Shampoos Tonalizantes Color Change Castanho Médio - Kiss New York', 'Dê tchau aos grisalhos em apenas 3 minutos usando Color Change Shampoo! Com fórmula de ação rápida, o shampoo tonalizante da Kiss NY garante 100% da cobertura dos grisalhos em um período de apenas 3 a 7 minutos. Além de uma fórmula vegana, não testada em animais e livre de amônia e parabenos, o produto ainda é rico em Ginseng, ativo que fortalece a raiz do cabelo e elimina as toxinas e também conta com Extratos Naturais que promovem o crescimento dos fios e ajudam a reter a cor do cabelo por mais tempo.É indicado para todos os tipos de cabelos, inclusive os quimicamente tratados e sua fórmula garante mínima transferência para toalhas e roupas.', 75.9, 75.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8260o-mm64twpxqpdv2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1687531684%2F58207426168', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29473005806', 'Inoar Kit Cicatrifios 5 Ampolas 45ml', 'Inoar Kit Cicatrifios 5 Ampolas 45ml Ampola de tratamento para cabelos danificados. Inoar Cicatrifios Super Ampola reduz o volume, a quebra e o frizz com brilho extremo. Inoar Cicatrifios Super Ampola promove uma plástica capilar instantânea que hidrata, alinha e renova a fibra capilar para que o volume e os fios rebeldes sejam diminuídos gradativamente. Com 3 doses em apenas um frasco, também facilita o desembaraço, suaviza e deixa um toque sedoso duradouro. Pode ser usado em todos os tipos de cabelo. Ação: RejuComplex3: promove recuperação total da fibra capilar, sela os fios e reduz gradativamente o volume. Uma verdadeira plástica para fios disciplinados e renovados. Conselho de Aplicação: Depois de lavar os cabelos com shampoo, retire o excesso de água com uma toalha. Aplique uma quantidade suficiente da ampola mecha a mecha. Deixe agir por 3 minutos e enxágue. Resultado: Seu cabelo hidratado, macio, brilhante e progressivamente livre do frizz e do volume durante os 7 dias da semana.', 66.26, 59.64, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7ra26-m4rxf2xq7xfo15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290896931%2F29473005806', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794042505', 'Condicionador Bio Extratus Jaborandi 250ml', 'Condicionador Antiqueda 250ml - Bio Extratus Jaborandi, Alecrim, Quilaia, Vitaminas A, B E E Indicação - Cabelos Com Queda E Pouco Crescimento Função - Atuar Diretamente No Bulbo Capilar, Estimulando O Crescimento, Além De Auxiliar O Tratamento Antiqueda. Resultados E Benefícios - Tonifica E Nutre O Bulbo Capilar. Estimula O Crescimento E Proporciona Fios Fortes E Saudáveis. Condicionador Revitalizante, Rico Em Vitaminas. Ativa A Circulação, Através Da Massagem Durante A Aplicação Do Produto, Nutre Os Fios, Evitando A Queda E Ajudando No Crescimento Saudável Dos Cabelos. Os Resultados De Eficácia Obtidos Foram Satisfatórios Utilizando A Linha Completa Do Produto. Modo De Usar: Após Lavar Os Cabelos, Aplique O Condicionador Massageando Suavemente. Deixe Agir Por Alguns Minutos. Enxágue. Pode Ser Usado Diariamente Combinando Com O Shampoo Jaborandi. Potencialize O Resultado Aplicando A Loção Tônica Extrato Natural Jaborandi Três Vezes Por Semana.', 101.85, 61.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7raup-ma4ck3ufea6k4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22794042505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497989393', 'Tampa Arranque Partida Compatível Roçadeira Stihl Fs75 / Fs80 / Fs85', 'Puxador de Corda de Partida Completa para Roçadeiras Stihl – Confiabilidade e Praticidade Mantenha sua roçadeira funcionando com eficiência utilizando o Puxador de Corda de Partida Completa, compatível com diversos modelos da linha Stihl. Este componente é essencial para acionar o motor com facilidade, garantindo partidas rápidas e seguras da sua máquina. Ideal para profissionais e entusiastas da jardinagem que buscam praticidade e desempenho confiável. Descrição do Produto: O puxador de partida é projetado para instalação direta, proporcionando acionamento suave e eficiente. Basta puxar a corda com força moderada e, em até três tentativas, o motor entrará em funcionamento. Produto fabricado com materiais de alta resistência, garantindo durabilidade mesmo em condições de uso intenso. Principais Benefícios: Funcionamento eficiente: garante partidas rápidas e confiáveis. Durabilidade: produzido com materiais de alta qualidade que resistem ao uso contínuo. Fácil instalação: encaixe compatível com os modelos indicados, sem necessidade de adaptações complexas. Segurança: acionamento suave reduz risco de esforço excessivo ou acidentes. Compatibilidade precisa: projetado especificamente para roçadeiras Stihl, garantindo encaixe perfeito. Compatibilidade: Stihl: FS75 / FS80 / FS85 / KA85R / KM85 / FR85 / SP81 / FS81 / HT75 Itens Inclusos: 1x Tampa de Partida para Roçadeira FS85 Observação: Após instalar o puxador, puxe a corda com força moderada até o fim. Caso o motor não funcione após três tentativas, recomendamos a verificação com um mecânico de confiança. Garantia do vendedor: 3 Meses', 59.0, 43.26, NULL, 'Home & Living > Gardening > Lawn Mowers', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj731p7175dt79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177369665%2F18497989393', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47000628767', 'Politriz Polidor Automotivo Elétrico 850W com Velocidade Variável e Trava de Gatilho', 'Polidor e Politriz Elétrica 850W 5 Polegadas Velocidade Ajustável 600 a 4500RPM - Amarelo Potência, precisão e praticidade para acabamentos profissionais! Se você busca eficiência e alto desempenho em polimento e acabamento, a Politriz Elétrica 850W é a escolha certa. Compacta, ergonômica e potente, ela remove arranhões, imperfeições e marcas de pintura com rapidez e qualidade. Seu design ergonômico facilita o manuseio, proporcionando conforto e controle ao operador. Leve e portátil, é perfeita para uso em espaços confinados e permite trabalho preciso e detalhado. A politriz garante resultados profissionais, destacando-se pela sua versatilidade e facilidade de uso. Perfeita tanto para uso doméstico quanto profissional, é indicada para oficinas, funilarias, setor automotivo, marmorarias, estofados e muito mais! ESPECIFICAÇÕES TECNICAS: - Potência: 850W - Velocidade ajustável: 600 – 4500 RPM - Velocidade Fixa : Trava gatilho - Níveis de rotação: 6 posições (partida + regulagem gradual) - Voltagem: 110V ou 220V (escolha na compra) - Prato de Velcro: 5 polegadas DIFERENCIAIS DO PRODUTO: - Motor potente que garante polimento rápido e eficiente - Controle de velocidade para diferentes tipos de trabalho - Cabo emborrachado macio para maior conforto - Design compacto e ergonômico que reduz fadiga LOCAIS DE USO: - Setor automotivo (carros, motos, funilarias e oficinas) - Polimento de mármore e granitos - Móveis de madeira e superfícies diversas - Limpeza e revitalização de estofados - Lixamento de paredes com massa BENEFICIOS: - Remove arranhões, manchas e imperfeições - Proporciona brilho intenso e acabamento profissional - Fácil de usar, prática e segura - Excelente custo-benefício ITENS INLCUSOS: 1x Politriz Elétrica 850W 1x Empunhadura ergonômica 1x Espuma ondulada 1x Boinas de lã 1x Prato Velcro 5 Polegadas 1x Chave de aperto 1x Manual do usuário', 189.0, 142.39, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Polisher', 'https://cf.shopee.com.br/file/br-11134207-820mc-mqc6jrnfaepu42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177369665%2F47000628767', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994525912', 'Massa Em Pó Para Pesca 500gr - Jr Pesca', 'A Massa em Pó para Pesca 500g da JR Pesca é uma escolha versátil e eficaz para pescadores que buscam atrair grandes exemplares em pesqueiros e lagos. Com uma fórmula turbinada e exclusiva, essa massa foi desenvolvida para oferecer alto poder de atração, especialmente em pescarias de fundo. Com um aroma marcante que estimula o apetite de espécies como Tilápia, tambaqui, pacu, entre outros de grande porte. Um dos grandes diferenciais dessa massa é sua textura, que permite ao pescador modelar a isca conforme sua preferência. Basta adicionar água do próprio lago até atingir o ponto ideal de liga, garantindo praticidade e eficiência na preparação. Além disso, a massa é comercializadas em diversos sabores, permitindo que o pescador escolha o aroma mais adequado ao tipo de peixe e às condições do ambiente. Outro benefício importante é a possibilidade de combinar essa massa com outras para turbinar ainda mais a isca. Isso amplia as chances de sucesso e permite explorar diferentes estratégias de pesca. Com 500g por embalagem, a Massa em Pó JR Pesca oferece excelente rendimento e é ideal tanto para pescadores iniciantes quanto para os mais experientes que desejam melhorar sua performance nas pescarias. Atenção: Essa massa possui variação de sabores, sendo necessário escolher o sabor desejado no ato da compra. Não perca tempo e garanta já sua Massa Em Pó Para Pesca 500gr - Jr Pesca aqui na Dispropil!!! Especificações Técnicas: - Marca: JR Pesca - Modelo: Massa Em Pó Para Pesca 500gr - Jr Pesca - Aroma atrativo - Diversos Sabores - Fácil preparo - Tipo: Pó - Peso: 500g Medidas da Embalagem: - Altura: 24 cm - Largura: 14 cm Itens Inclusos: 01 - Massa Em Pó Para Pesca 500gr - Jr Pesca', 32.79, 32.79, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-8259t-mfyd5uu0c5qh1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063297286%2F23994525912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14880289710', 'Grampeador Profissional Para Madeira Tapeçaria 4-14mm Fertak', 'Olá, Bem vindo a Distribuidora Brester. Trabalhamos com uma grande variedade de ferramentas elétricas e manuais, descartáveis, eletroeletrônicos, artigos para casa, artigos de petshop e outros. Aqui você encontrará Produtos Originais, Nota Fiscal, Pronta Entrega e Envio Imediato! * Características do produto * Grampeador Profissional Para Madeira Tapeçaria 4-14mm Fertak Grampeador de Tapeceiro Profissional Metálico, resistente e de alta qualidade. Ideal para fixação de materiais em madeira, tais como, tecido, plástico, papel, tapeçaria, fixação de forros, telas (mosquiteiros), fixação de cartazes (escolas, supermercados, etc), serigrafia, vitrinismo, marcenaria, cartonagem, entre outros. Benefícios: > Compacto e funcional. > Muito leve. > De fácil manuseio. > Útil para revestir madeiras com tecidos, etc. > Com Grampos Extras Características Técnicas: > Altura: 9cm > Largura: 13cm > Profundidade: 20cm > Peso: 0,8kg > Comporta Grampos De: 4 Até 14mm > Com Grampos Extras > Alta Pressão > Controle De Pressão Da Mola > Corpo em Aço Conteúdo: - 01 Grampeador Profissional Fertak (comporta grampos de 4 a 14 mm) - 200 grampos original Fertak - Marca: Fertak - Garantia: 3 meses contra defeitos de fabricação Vantagens de comprar na Brester: - Nota fiscal para Pessoa Física e Pessoa Jurídica. - Produto novo, com garantia de fábrica. - Produto a pronta entrega. - Envio em até 24hs em dias úteis após confirmação do pagamento. Obrigado por escolher a Brester Máquinas.', 52.21, 45.95, NULL, 'Stationery > School & Office Equipment > Staplers & Staples', 'https://cf.shopee.com.br/file/b7751aff2ca8d58c308a3512fef0df68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F1488028