INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19497688981', 'Colchão Solteiro Tecido Bordado em Malha Ecoline Ecoflex D23 88x188x14cm', 'Colchão Solteiro Ecoflex Ecoline D23: Conforto e suporte ideais para jovens e bem-estar diário. O Colchão Solteiro Ecoflex Ecoline D23 oferece um descanso reparador com sua espuma 100% maciça e pura, ideal para crianças, adolescentes e visitas. Com densidade D23, proporciona suporte e firmeza ideais para um sono tranquilo. Sua certificação INMETRO assegura qualidade e resistência, enquanto o tratamento antiácaro e antialérgico promove um ambiente mais saudável. O tecido bordado em malha e a característica Double Face complementam a experiência de excelente desempenho para o seu dia a dia. Eleve a qualidade do seu descanso com o Colchão Solteiro Ecoflex Ecoline D23, uma escolha que combina conforto excepcional e longevidade. Sua espuma 100% maciça e a densidade D23 garantem o suporte ideal para um sono reparador, essencial para o bem-estar de jovens e para receber hóspedes com hospitalidade. O design com tecidos estampados em Cinza ou Floral adiciona um toque de estilo ao ambiente, enquanto as dimensões de 88x188x14cm são pensadas para otimizar seu espaço. Desfrute da praticidade de um produto certificado, projetado para oferecer excelente desempenho e resistência no seu dia a dia, suportando até 80kg por pessoa. ➡️ Manutenção e cuidados: Gire o colchão regularmente, ventile o quarto diariamente, utilize uma capa protetora, limpe-o com um pano macio e úmido, e evite saltar sobre ele para preservar a estrutura e prolongar sua vida útil. ➡️ Características do Produto: Marca: Ecoflex Modelo: Ecoline Densidade da Espuma: D23 Tipo de Espuma: 100% maciça, espuma pura Certificação: Produto Certificado Custo-Benefício: Excelente Composição: Qualidade em sua composição Suporte: Ideal para um sono reparador Conforto: Proporciona bem-estar Tratamento: Antiácaro e Antialérgico Uso: Dupla Face (Double Face) Peso Suportado: 80 Kg ➡️ Dimensões do Produto: Altura: 188cm Largura: 88cm Profundidade: 14cm Garantia: 6 meses', 429.9, 429.9, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rd6u-lw63xedvwduzfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F19497688981', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213290536', 'Kit 2un Fleischmann Mistura Para Bolo Tipo Pão De Queijo 310g', 'Mistura em pó para preparo de bolo pão de queijo, destinado ao segmento B2C, sendo necessário acrescentar ovos, leite, óleo e queijo em sua receita Ingredientes: Amido, amido modificado, gordura vegetal hidrogenada, sal e aromatizante. CONTÉM GLÚTEN. ALÉRGICOS: CONTÉM DERIVADOS DE SOJA, DE TRIGO E DE LEITE DE VACA. PODE CONTER OVO', 27.14, 27.14, NULL, 'Food & Beverages > Cooking Essentials > Flour Coating', 'https://cf.shopee.com.br/file/br-11134207-820lc-mpy1w8nj3z7n80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F58213290536', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55059720877', 'KIT FEMININO CREME HIDRATANTE SUCCES VERT + BODY SPLASH SUCCES VERT 200ML BY PRIMACIAL', 'Kit Succès Vert Creme + Body Splash Um kit pensado para quem ama unir hidratação e perfumação em uma rotina leve, elegante e refrescante. O Creme Succès Vert ajuda a deixar a pele macia, confortável e hidratada, enquanto o Body Splash Succès Vert complementa a experiência com uma fragrância cítrica floral sofisticada, perfeita para o dia a dia. Juntos, eles criam uma sensação revigorante, feminina e cheia de frescor. Sobre a fragrância: Succès Vert é uma fragrância Chipre Floral com abertura vibrante de limão siciliano, bergamota e cedro, seguida por um coração de jacinto, pimenta rosa e jasmim. No fundo, patchouli, almíscar, vetiver e âmbar trazem elegância e profundidade na medida certa. Pirâmide Olfativa: Topo: Limão Siciliano, Bergamota, Cedro Coração: Jacinto, Pimenta Rosa, Jasmim Fundo: Patchouli, Almíscar, Vetiver, Âmbar Destaques do kit: -Hidratação + perfumação em um só kit -Pele macia, cheirosa e bem cuidada -Fragrância fresca, feminina e sofisticada -Ideal para o dia a dia e pós-banho -Perfeito para climas quentes e momentos ao ar livre Dica de uso: Aplique o Creme Succès Vert na pele limpa e seca. Em seguida, use o Body Splash Succès Vert para complementar a perfumação e deixar a experiência ainda mais agradável ao longo do dia.', 94.9, 89.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-820ld-mnna3xswxwqq46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295467768%2F55059720877', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
