INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299499740', 'Rádio Portátil Benoá X8 FM USB Bluetooth', 'Rádio Portátil Benoá X8 FM USB Bluetooth Experimente a liberdade musical em qualquer lugar com o Rádio Benoá X8 FM USB Bluetooth. Este dispositivo multifuncional oferece a conveniência de sintonizar suas estações de rádio FM favoritas e a flexibilidade de reproduzir música a partir de dispositivos USB ou via conexão Bluetooth. Com um design elegante e compacto, o Benoá X8 é perfeito para acompanhá-lo em viagens, passeios ao ar livre ou simplesmente para relaxar em casa, garantindo uma experiência sonora excepcional onde quer que você vá. Tipo: Rádio Potência de áudio (RMS): 3W Entrada USB: 1 Entrada auxiliar : Sim Conexões: Bluetooth Capacidade (CDs): 1 Rádio: FM Mídias compatíveis: MP3 Formatos compatíveis: CD/CD-R /CD-RW player Bluetooth: Sim Memória para estações de rádio: Sim Toca disco: Não Tipo de display: Digital Alarme: Não Relógio: Não Controle remoto: Não Alça para transporte: Sim Consumo: 9W Alimentação: Eletricidade Voltagem: Bivolt A prova d''água: Não Peso (kg): 0.995 Dimensões (AxLxP):10.7 x 22 x 20.5 cm Referência: X8 Itens Inclusos: - 1 Rádio Portátil Benoá X8 FM USB Bluetooth Informações importantes: Imagens meramente ilustrativas. Objetos que ambientam as fotos não acompanham o produto. As tonalidades das cores dos produtos podem sofrer alterações de acordo com a calibração do seu monitor. Este produto não inclui montagem e instalação. Não nos responsabilizamos, no ato da entrega, por desmontagens, subir escadas, elevadores ou transporte por guincho para apartamentos. Eventuais despesas são de responsabilidade do cliente. Garantia Fabricante: 3 meses', 578.9, 578.9, NULL, 'Audio > Media Players > Radio & Cassette Players', 'https://cf.shopee.com.br/file/sg-11134201-7rdxx-m12vs6p3yqk4d0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F889942432%2F19299499740', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693682639', 'Fita Veda Rosca 18mm X 10m Fortlev', 'A Fita Veda Rosca Fortlev é ideal para garantir vedação eficiente em conexões roscadas de tubulações, proporcionando segurança em sistemas que conduzem água fria, água quente, vapor, combustíveis, gases e outros fluidos industriais. Seu design e material de alta qualidade asseguram um desempenho duradouro e resistente a altas temperaturas. Vantagens: Vedação perfeita para evitar vazamentos. Ampla gama de aplicação em diferentes tipos de fluidos e temperaturas. Resistente a altas pressões e temperaturas extremas. Fácil aplicação e manuseio, garantindo instalação rápida e eficaz. Dados Técnicos: Largura: 18mm Comprimento: 10m Temperatura de trabalho: -90ºC a +240ºC Aplicação: Tubulações de água fria, água quente, vapor, combustíveis, gases e fluidos industriais em geral. Garantia: Garantia de 3 meses oferecida pelo fabricante.', 29.9, 20.9, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rbm2-m5sz6cuar13iea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23693682639', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793670736', 'Silicone Preto Alta Temperatura 50g Tekbond', 'Possui excelente resistência a óleo de motor e óleos lubrificantes, pode ser aplicado em tampa de válvulas, caixas de câmbio, caixas de engrenagens, tampas de motores etc. Ideal para ser utilizado como um substituto de juntas de retentores, de papel, cortiça e feltro. Características Técnicas: - É um adesivo selante tixotrópico monocomponente. - Baixo módulo, antifungo e de cura acética. - Sua cura ocorre em temperatura ambiente e na exposição à umidade do ar. Modo de Uso para bisnagas de 50g - Aplicar um cordão de silicone de espessura entre 1,5 a 3,0 mm na superfície, pressionando a bisnaga pelo fundo. - Após 2 horas, faça o aperto final dos parafusos. - Após aberto reutilizar o produto em até duas semanas. Limitações de uso: - Este produto não deve ser usado em vidros laminados, metal corrosível, espelhos, superfícies pintadas e/ou porosas, superfícies alcalinas, aquário, acrílicos, concreto, cimento, tijolo, pedra calcária, zinco, placa de aço galvanizado. - Não recomendado para plásticos à base de polietileno, polipropileno e policarbonato. - Não indicado para fachadas de vidro e qualquer adesão estrutural que necessite resistência, contato de alimentos, imersão contínua em meios líquidos e em espaços totalmente fechados. - Não aceita pintura. Garantia: - 3 meses de garantia.', 34.9, 24.5, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rd6j-m6pqvmcy874c63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F22793670736', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20197518931', 'Pingente de Prata 925 Beach Tennis', 'Pingente de Prata 925 Beach Tennis O Pingente de Prata 925 Beach Tennis é uma peça elegante e delicada que celebra a paixão pelo esporte. Com 20mm de tamanho e 0.9g de peso, este pingente é perfeito para os amantes do beach tennis. Especificações: Tamanho: 20mm Peso: 0.9g Material: Prata 925 Elegância Esportiva Este pingente é uma expressão sofisticada da paixão pelo beach tennis. Use-o para mostrar seu amor pelo esporte com estilo e elegância. Descubra Mais na Aqua Joias Explore nossa coleção completa de pingentes de prata 925 e descubra peças exclusivas que complementam seu estilo. Na Aqua Joias, garantimos qualidade e sofisticação em cada detalhe.', 79.99, 56.99, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-looagoy9xtgi1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F20197518931', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498999868', 'Bomba Combustível PALIO 2003 2004 2005 2006 2007 2008 2009 - 17032 - GI3120', 'Bomba Combustível PALIO 2003 2004 2005 2006 2007 2008 2009 Produto novo, com garantia e nota fiscal. Bomba Elétrica GI3120 para veículos FLEX / Álcool e bicombustível. Interna - 12V / 4 Bar / 100 L/H Utilizando o kit, substitui os sistemas MARWAL e BOSCH. Podemos dividir as bombas de combustível elétricas em dois tipos, interna e externa ao tanque. A interna trabalha submersa aspirando o combustível diretamente do fundo do tanque para as mangueiras de abastecimento que ligam aos bicos injetores. A externa trabalha fixada ao chassi do veículo, próxima ao tanque ou ao motor, sugando o combustível do tubo coletor localizado no tanque', 199.38, 199.38, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbmn-lms1l7hok55ve5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21498999868', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997992432', 'Correia Poly V Hyundai Hb20 2019 a 2025 - 1353168 - 6PK1255', 'Correia Poly V Hyundai Hb20 2019 a 2025 1353168 6PK1255 Motor 1.0 12V KAPPA - (Girabrequim / Alternador / Bomba D''água / Ar Condicionado) (NÃO SE APLICA NO MOTOR T-GDI) As correias Multi V permitem a transmissão não positiva de binários. A sua função: O acionamento do alternador, ventoinha, bomba de água, compressor do ar condicionado e direção assistida nos motores modernos. As correias Multi V estão sujeitas a envelhecimento e desgaste. Por essa razão, têm de ser controladas e substituídas a intervalos regulares. Os intervalos de controle e de substituição são sempre estabelecidos pelo fabricante do veículo e devem ser respeitados.', 98.44, 98.44, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7repd-m8wpsaadf6dxbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19997992432', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18599242241', 'Bóia Tanque CELTA 2006/2009 - 18109 - T010141', 'Bóia Tanque CELTA 2006/2009 Combustível: Flex (SISTEMA BOSCH) O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 97.91, 97.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7rd6z-lufj1ekze4xxb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18599242241', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693090979', 'Tambor de Embreagem Para Roçadeira 26X9 Nakasaki', 'Tambor de Embreagem Completo para Roçadeiras 26mm x 9 Estrias – Durabilidade e Desempenho Garantidos Mantenha sua roçadeira funcionando com eficiência máxima com o Tambor de Embreagem Completo 26mm x 9 Estrias, projetado para oferecer resistência, precisão e longa durabilidade. Desenvolvido para se adaptar a diversos modelos de roçadeiras a gasolina, este tambor é ideal tanto para manutenção preventiva quanto para reparos, garantindo que sua máquina volte a operar com desempenho confiável. Características Principais: Produto compatível com múltiplas marcas e modelos de roçadeiras (verifique compatibilidade antes da compra). Inclui nota fiscal garantindo segurança e procedência do produto. Estrutura robusta, projetada para suportar uso contínuo e exigente em roçadeiras. Medidas de Acoplamento: Diâmetro total: 78mm Largura entre os furos do parafuso: 70mm Número de estrias: 9 Diâmetro do eixo: 26mm Compatibilidade: Este tambor adapta-se a uma ampla variedade de marcas e modelos de roçadeiras. Alguns exemplos: Tekna: 26CC, 33CC, 43CC, 52CC, 60CC, RL260, RL330, RL430, RL520, AL260, AL330, AL430, AL520, RL330TKY, RL335STKY4, RL430TKY, RL430ACN-TK, RL430ACN-TK2, RL430AC-G2 Nagano: 26CC, 33CC, 43CC, 52CC, 62CC, RN52L, RN72L, RMF51, NR41, RN41 Matsuyama: 26CC, 33CC, 42CC, 52CC Toyama: 26CC, 33CC, 43CC, 52CC, 63CC, TBC26, TBC33, TBC43, TBC52, TBC63, RT26, RT33, RT43, RT52, TBC26SH, TBC33SH, TBC43SH, TBC26X, TBC26DX, TBC26MTX, TBC33X Bandai, Terra, Kawashima, Vulcan, Gamma Elite, Branco, Lira, Siga Tools, Brutatec, Yamasaki, Ferrari, Cid, FortG, Tramontina, Garthen, Azen, Intech Machine, Nakasaki, Honda e muitos outros Caso sua marca ou modelo não esteja listado, consulte-nos pelo campo de perguntas para confirmar compatibilidade. Vantagens do Produto: Substituição completa do tambor de embreagem, mantendo a eficiência do motor. Estrutura resistente ao desgaste e às altas rotações. Facilita a manutenção e prolonga a vida útil da sua roçadeira. Ideal para uso doméstico, profissional e agrícola. Observação Importante: Antes de efetuar a compra, certifique-se de que o modelo da sua roçadeira é compatível com o tambor de embreagem para evitar problemas futuros. Em caso de dúvidas, utilize o campo de perguntas para atendimento personalizado. Garantia do Vendedor: 3 meses contra defeitos de fabricação', 78.0, 53.12, NULL, 'Home & Living > Gardening > Lawn Mowers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgs1kzyz9vrb79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177369665%2F22693090979', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
