INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694041602', 'Pincel marcador multisuperfícies Multimark 1.0mm Verde MM/10VD778ZF Faber-Castell', 'O Pincel Marcador Permanente Multimark 1.0 mm da Faber-Castell é ideal para quem busca versatilidade, precisão e durabilidade em superfícies diversas. Com tinta de secagem rápida e resistente à água, ele proporciona marcações permanentes em materiais como papel, plástico, vidro, metal e madeira. Sua ponta oferece traço médio e uniforme, perfeito para escrita técnica, identificação de objetos, organização de arquivos ou uso artístico. A estrutura robusta e o corpo ergonômico garantem conforto durante o uso prolongado, enquanto a tampa com sistema de vedação evita o ressecamento da ponta. Detalhes: - Cor: Verde - Design exclusivo. - Base de álcool - Cobertura translúcida. - Ponta cônica: 1.0 mm. - Corpo ergonômico - Excelente cobertura nas mais diversas superfícies: papel, cartão, madeira, plástico, vidro, metal, cerâmica, parede e muito mais - O marcador é permanente em superfícies porosas e pode ser removido em vidro ou superfícies lisas - Tinta não lavável em tecidos.', 20.68, 17.58, NULL, 'Stationery > Writing & Correction > Markers', 'https://cf.shopee.com.br/file/sg-11134201-7rdw0-mbsmlfqvj6zee6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F479054821%2F22694041602', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
