INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797063986', 'Mangueira Respiro Óleo Fiat Uno 1988 a 1997 - 102776 - 3154', 'Mangueira Respiro Óleo Fiat Uno 1988 a 1997 102776 3154 1.5 (Ventilação de bloco do motor) Essa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 31.5, 31.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbld-ln0gyyzm4ebc39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23797063986', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797474632', 'Sensor Posição Borboleta Gm Astra 1994 a 2006 - 508680 - 1908', 'Sensor Posição Borboleta Gm Astra 1994 a 2006 508680 1908 Motor 1.8 8v Álcool/Gasolina /2.0 8/16v Gasolina O Sensor de Posição da Borboleta (Throttle Position Sensor – TPS) é utilizado para monitorar a posição do acelerador em um motor de combustão interna. O sensor tem como finalidade informar a posição da borboleta do acelerador. Através do TPS, a UCE obtém informações instantâneas da posição da borboleta permitindo à central identificar a potência que o condutor está requerendo. Essas informações são utilizadas no auxílio do cálculo do tempo de injeção, avanço da ignição,etc...', 119.09, 119.09, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd5z-luh0u05e6bmq0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22797474632', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
