INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21397676178', 'O HOMEM QUE ODIAVA MACHADO DE ASSIS E SE O PRINCIPAL LIVRO DE MACHADO DE ASSIS FOSSE AUTOBIAGRÁFICO ?', 'O HOMEM QUE ODIAVA MACHADO DE ASSIS E SE O PRINCIPAL LIVRO DE MACHADO DE ASSIS FOSSE AUTOBIAGRÁFICO ? Nesteromance,umaoutrafacedeMachadodeAssiséapresentadaeconvidamososleitoresaconheceremaversãodeseuadversáriomaisdesgraçado.Doisgarotos,deorigensmuitodiferentes,sãoforçadosaconviverporalgunsanoseacabamporversuastrajetóriasenlaçadasporumdestinoirônico.DoMorrodoLivramento,passandoporPortugalepeloRiodeJaneirodofinaldoséculoXIX,osmeninos,agorahomens,sereencontrameretomamumarivalidadepelaqualvalededicaravida.Ehoje,enquantoumécelebradocomoumdosmaioresescritoresbrasileiros,PedroJunqueira,nossopersonagemmarcadopeloazarepelausurpação,tempelaprimeiravezachancedeversuahistórianarradasoboutropontodevistaPorquetercomoadversáriooescritordemaiorprestígionaliteraturabrasileiranãodeveserfrutoapenasdoacaso,masumamaldição.Junqueiranãoteveapenasideiasroubadaseoportunidadesminadas,mastambémaperdadeseugrandeamor.. Informações Adicionais Autor: ALMEIDA JÚNIOR, JOSÉ Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: O HOMEM QUE ODIAVA MACHADO DE ASSIS E SE O PRINCIPAL LIVRO DE MACHADO DE ASSIS FOSSE AUTOBIAGRÁFICO ? Idioma: INDEFINIDO Páginas: 240 Edição: 1 ISBN-13: 9788595810754 ISBN-10: 8595810753', 51.92, 49.84, NULL, 'Books & Magazines > Books > Romance', 'https://cf.shopee.com.br/file/sg-11134201-7rbmo-lp8er014mmjebb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F21397676178', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23092996368', 'UMA VIDA A HISTÓRIA DE NICHOLAS WINTON', 'UMA VIDA A HISTÓRIA DE NICHOLAS WINTON O livro que inspirou o filme Uma Vida, estrelado por Anthony Hopkins e Helena Bonham Carter. Essa é a história de Nicholas Winton, um humanitário britânico, que aos 29 anos ajudou no resgate de 669 crianças judias do Holocausto. Escrito por sua filha, Barbara Winton, e baseado em registros retirados de suas cartas, diários, anotações pessoais e conversas com familiares e amigos, este livro explora as influências sobre seu personagem, bem como os eventos históricos nos quais ele se envolveu ao receber um telefonema em dezembro de 1938 e mudar sua rota de viagem de férias. Seguindo seu lema Se alguma coisa não é impossível, deve haver algum meio de fazê la, ele assumiu a operação que outros dispensaram por considerar desnecessária, arriscada ou difícil demais. Barbara explora, com maestria, os 106 anos da vida incrível de um homem cujo legado só veio a público décadas depois. Essa história de vida é um chamado vibrante à escolha da ação em vez da apatia diante da injustiça e um lembrete de que todos nós podemos mudar o mundo.. Informações Adicionais Autor: BARBARA, WINTON Data Publicação: 04/04/2024 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: UMA VIDA A HISTÓRIA DE NICHOLAS WINTON Idioma: INDEFINIDO Páginas: 320 Edição: 1 ISBN-13: 9786557362907 ISBN-10: 6557362909', 64.22, 64.22, NULL, 'Books & Magazines > Books > Biography & Memoirs', 'https://cf.shopee.com.br/file/sg-11134201-7rd75-luf78vb2m5kib1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23092996368', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21698661110', 'Kit de Mamadeira Primeiros Passos 50/150/240ml Neutro Lillo', 'Kit de Mamadeira Primeiros Passos 50/150/240ml Neutro - Lillo A Mamadeira que acompanha todas as fases de desenvolvimento. O Kit contém 3 mamadeiras, sendo elas: A Chuquinha de 50ml com bico tamanho 0 (recém nascidos até os 3 meses) possui material macio, maleável e com furo pequeno para que o fluxo dos líquidos seja lento. A Mamadeira de 150ml com bico tamanho 1 (de 0 a 6 meses) e a de 300ml com bico tamanho 2 (acima de 6 meses) possuem bico com formato mais largo, que facilita a higienização. As Mamadeiras primeiros passos lillo foram desenvolvidas com desenhos divertidos e coloridos. Material transparente, atóxicos e livres de BPA. O MINISTÉRIO DA SAÚDE ADVERTE: A CRIANÇA QUE MAMA NO PEITO NÃO NECESSITA DE MAMADEIRA, BICO OU CHUPETA. O USO DE MAMADEIRA, BICO OU CHUPETA PREJUDICA O ALEITAMENTO MATERNO. Principais Características: - Mamadeira 50ml (De 0 à 3 meses): possui bico em silicone, com furo pequeno para que o fluxo dos líquidos seja lento. - Mamadeira 150ml (De 0 à 6 meses): possui bico em silicone de fácil higienização. - Mamadeira 240ml (6+ Meses): possui o frasco mais largo para facilitar a higienização, tampa com sistema antivazamento e e pode ser encaixada na parte de baixo da mamadeira, evitando perda. - Tampa Antivazamento - Bico de Silicone - Todas as Mamadeiras são livres de BPA Especificações Técnicas: - Conteúdo da Embalagem: 1 Kit de Mamadeira Primeiros Passos 50/150/240ml - Lillo - Material/ Composição: Polipropileno (PP) e Silicone - Garantia: 30 Dias (Contra Defeito de Fabricação pelo Fabricante) - Certificação Inmetro: CE-PUR/IQB-000632 - NBR 13793 – OCP 0006 - Código do Fabricante: 628801 - EAN: 7896033261395 - Marca: Lillo Imagens meramente ilustrativas, as cores e estampas podem variar de acordo com o lote do fabricante.', 62.9, 62.9, NULL, 'Mom & Baby > Feeding Essentials > Bottle-feeding', 'https://cf.shopee.com.br/file/sg-11134201-7qvfg-lid5urt84ikg0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F481992044%2F21698661110', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
