INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14173487893', 'Travesseiro de Corpo com Fronha Percal 130x50cm BF Colchões', 'Travesseiro Bf para quem gosta de dormir de lado, abraçado, esse é seu travesseiro. Dando apoio a cabeça e aos joelhos de forma muito confortável. As fibras de poliéster siliconada e a capa em percal agregam um grande conforto e maciez a esse travesseiro. Pensando na sustentabilidade, enviamos seu travesseiro enroladinho. É usado menos embalagens e não ocupa espaço no caminhão, que consequentemente diminui a emissão de CO2, polui menos e o frete sai bem mais barato. A natureza agradece né? Ah, e o travesseiro não deforma por ser embalado dessa forma, ok? Bons sonhos Características: Fibra siliconada com conforto de plumas Mantém a postura correta com a coluna cervical alinhada Apoia o queixo evitando a flexão do pescoço Evita virar para a posição de bruços ou de costas Evita atrito entre os joelhos e os tornozelos Contém: 01 Travesseiro de Corpo 01 Capa Percal Tamanho do Travesseiro: 130 x 50 x 20 cm Composição Travesseiro: Revestimento 50 Algodão e 50 Poliéster Enchimento 100 Fibras de Poliéster Siliconada Composição da capa: 50 Algodão 50 Poliéster Marca: BF Colchões', 285.87, 219.0, NULL, 'Home & Living > Bedding > Pillows', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m1e6i27pxz9c84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F14173487893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10596366520', 'Capa Protetor Colchão Impermeável 100% Algodão Solteiro - Emcompre', 'O protetor BF Casa é indispensável na hora de conservar o seu colchão limpinho e com aspecto de novo por muito mais tempo. Protetor de Colchão Impermeável - Veste Fácil. Com uma grande capacidade de impermeabilidade, os protetores para colchão apresentam um ótimo desempenho contra água, óleo e manchas, aumentando consideravelmente a vida útil do seu colchão. Não faz barulho, não esquenta, não alérgico, 100 impermeável e fácil de lavar e secar. Tamanho: Solteiro 88 x 1,88 X 36 cm Com elástico em toda a sua borda. Composição: 100% Poliéster Tecido:Superior: 100% Algodão Inferior: 50 Polipropileno 50 Polietileno 140 Fios', 181.87, 139.0, NULL, 'Home & Living > Bedding > Mattress Protectors & Toppers', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m1e6ote035eq72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F10596366520', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15949208919', 'Pimenta do Reino Preta Grão', 'Nome Científico: Piper nigrum Parte Utilizada: Pimenta Sinônimo Popular: Origem: Brasil A pimenta-do-reino em grão, também conhecida simplesmente como pimenta preta, é uma especiaria amplamente utilizada na culinária de várias culturas ao redor do mundo. Ela é derivada das bagas secas da planta Piper nigrum e é valorizada por seu sabor picante característico e aroma forte. *Embalagem meramente ilustrativa', 22.13, 22.13, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/br-11134207-820l7-mon1whyhvksmc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F15949208919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697979628', 'Credeli Antipulgas 225mg (cães) 5,5kg / 11kg - 3 comprimido', 'O mais rápido do mercado contra carrapatos e pulgas. Credeli é um comprimido mastigável, pequeno e saboroso, que atua rapidamente para proteger cães filhotes e adultos contra carrapatos e pulgas. Conforme bula dos produtos analisados: Por que Credeli é o mais rápido? Molécula própria desenvolvida para cães com essa finalidade. Carrapatos: Começa a eliminar em até 4 horas. Elimina 100% dos carrapatos em 8 horas. Pulgas: Começa a eliminas em até 2 horas Elimina 100% das pulgas em 6 horas. Cada embalagem contem 3 comprimidos, um para cada mês. 90 dias de proteção Credeli combate o amblyomma cajennense Além de ser o mais rápido do mercado, sua formula exclusiva também combate o Amblyomma Cajennense, mais conhecido como carrapato-estrela, causador da febre maculosa. PARA UMA DIVERSIDADE DE RAÇAS E TAMANHOS Credeli possui 100% de aceitação em 70 raças de cães, incluindo raças TOY, como Chihuahua e Yorkshire Terrier Tamanho e dosagem? Com um sabor que os cães adoram. Credeli possui principio ativo extra purificado que poupa o fígado e seguro para: Cães a partir de 1,3 Kg até 45Kg - filhotes de 8 semanas ou mais.', 280.9, 187.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-7reo7-m1ymhdwcry7r03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F18697979628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
