INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209718067', 'Chocolate Prestígio Nestlé', 'Prestígio é um delicioso chocolate com recheio de coco que te leva para um mundo de sabor a cada mordida. Ingredientes: açúcar, coco ralado, xarope de glicose, gordura vegetal, massa de cacau, leite em pó, gordura anidra de leite, manteiga de cacau, sal, umectante glicerol, emulsificantes lecitina e poliglicerol polirricinoleto e aromatizante. Alérgicos: Contém Lactose, Glúten, Leite e Derivados, Soja e Derivados. Pode Conter: Ovo, Amendoim, Trigo e Látex Natural.', 4.79, 4.79, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-82584-mqnel7nlu0oz2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554886%2F58209718067', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
