INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45252308629', 'CABO Y RCA PRETO 2F 1M PERMAK OURO PARA SOM AUTOMOTIVO', 'Descrição do Produto Os cabos RCA’s têm a função de fazer ligações de baixa potência, são ideais para ligar módulos, caixas de som, CD’s e DVD’s. RCA Ouro 20cm contém 1 plug macho e 2 fêmea, seu comprimento é de 20 cm e ele suporta até 100W de potência. Sua composição é em cobre, compondo seus condutores, PVC, presente na capa do fio e do plug, e latão banhado a zinco amarelo, componente do plug. Todos esses materiais possibilitam que esse cabo seja resistente à corrosão e a altas temperaturas, apresente boa resistência contra intempéries e tenha uma boa resistência mecânica. Especificaçoes tecnicas – Comprimento: 20cm – Potência máx: 100W – Cor: preto Conteúdo da Embalagem – 01 unidade Cabo RCA Ouro 20cm modelo 2F + 1M', 8.9, 8.9, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/sg-11134201-8227g-mhmdc0pr5mh06b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379659661%2F45252308629', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
