INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298931193', 'Calça HD Jeans Slim Preto Azul', 'Calça HD Jeans Slim Preto Azul Para o dia a dia ou para curtir os momentos de lazer, aposte na Calça HD. Produzida com material de qualidade, conta com detalhes que dão um tom mais despojado. Garanta já a Calça HD e turbine seu visual. Composição: 100% Algodão Sobre a marca A HD faz parte da vida dos jovens sonhadores que buscam fazer a mudança acontecer. Criada no início da década de 1980 e, junto com o sonho daqueles que desejavam deslizar sobre a melhor onda do mundo, no Hawaii, buscava evidenciar o espírito do primeiro esporte radical do mundo, o surf. Hoje a HD não representa apenas uma marca de roupa que resgata esse sonho, mas também a atitude e busca dos melhores momentos de cada “viagem” da vida: Sair da rotina, encarar desafios e aproveitar ao máximo cada instante da jornada. Produto Original', 209.99, 168.0, NULL, 'Men Clothes > Pants > Pants', 'https://cf.shopee.com.br/file/sg-11134201-824i6-meritoq8n9j7bb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1490043415%2F22298931193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
