INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12443558133', 'Fralda Pampers Pants Premium Care XXG 60 un', 'Experimente a nova Pampers Premium Care Pants! Com cintura elástica 360° é fácil de colocar mesmo quando eles estão em movimento, e mantendo sua pele seca e protegida. • O jeito fácil de trocar. • Fácil de colocar. • Cintura elástica 360° que se adapta ao corpinho do seu bebê com sistema de Ajuste Inteligente. • Fácil de tirar, rasgue suas laterais e retire-a normalmente. • Canais de ar que evitam que a fralda fique caída. • Ultra suave e respirável mantendo sua pele seca e protegida. • Indicador de umidade te avisa quando o bebê tem que ser trocado. • Até 12 horas* de proteção para noites inteiras de sono sequinho *Pode variar de acordo com os hábitos e características do bebê.', 176.69, 140.99, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-7rdwm-mc6imdxfzbvce5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F353664457%2F12443558133', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699833707', 'Paneleiro 70cm em Aço Grafite/Off White com Espaço para Forno Itatiaia Midi Pop Art i3', 'O Paneleiro Itatiaia da linha Midi Pop Art i3 foi desenvolvido para quem busca funcionalidade, organização e um visual moderno na cozinha. Produzido em aço com acabamento nas cores Grafite e Off White, ele alia resistência, design criativo e excelente aproveitamento do espaço, sendo ideal para ambientes compactos e contemporâneos. Diferenciais do produto Design criativo e contemporâneo Cores atuais e estampa marcante inspiradas no estilo Pop Art, que valorizam a decoração e trazem personalidade ao ambiente. Estrutura em aço com pintura eletrostática a pó Maior durabilidade e proteção contra ferrugem, umidade e desgaste do uso diário. Espaço dedicado para forno Nicho projetado para acomodar forno elétrico, com passagem de fios que facilita a instalação e mantém o visual organizado. Prateleiras bem distribuídas Excelente aproveitamento do espaço interno para organizar utensílios, mantimentos e itens de uso frequente. Puxadores em ABS Resistentes, funcionais e de fácil manuseio, ideais para a rotina da cozinha. Pés com sapata regulável Pés injetados que permitem melhor nivelamento e garantem estabilidade mesmo em pisos irregulares. Com visual moderno e estrutura robusta, o Paneleiro Midi Pop Art i3 é a escolha ideal para quem deseja uma cozinha funcional, organizada e com identidade. Informações importantes • Não faturamos para CNPJ, apenas para CPF. • A Itatiaia não se responsabiliza pela montagem e instalação dos produtos. A montagem deve ser realizada por um profissional, conforme o manual do fabricante. • Os objetos que ambientam as imagens não acompanham o produto. Atenção: as cores do produto podem variar conforme as configurações do monitor ou dispositivo. Entrega e recebimento: Para garantir agilidade e segurança no processo logístico, a entrega é realizada até a entrada principal do endereço informado. Os entregadores não realizam o transporte da mercadoria para andares superiores ou ambientes internos.', 564.59, 564.59, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-8259l-mqsh5k1i989b71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1553092714%2F20699833707', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
