INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198800876', 'Saia Midi Endless Preto', 'A Saia Midi Endless é a peça ideal para quem busca estilo e elegância com conforto. Confeccionada em Malha Star Shine, seu tecido macio e com leve brilho proporciona um visual sofisticado e moderno. O corte midi oferece um ajuste perfeito, valorizando a silhueta feminina e permitindo liberdade de movimento. Versátil, pode ser combinada com diferentes tops, criando looks para diversas ocasiões, desde o casual até o mais formal, sem abrir mão do conforto e charme.', 324.99, 178.99, NULL, 'Women Clothes > Skirts', 'https://cf.shopee.com.br/file/sg-11134201-8259k-mr22htpdul8gce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F23198800876', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194304341', 'Calça Feminina em Viscose Dobby Endless Preto', 'A Calça Feminina em Viscose Dobby Endless é a escolha ideal para quem busca conforto e estilo. Confeccionada em viscose dobby, ela oferece um toque suave e leve, proporcionando um caimento perfeito. O tecido de alta qualidade garante durabilidade e conforto ao longo do dia, enquanto o design moderno e elegante traz sofisticação ao look. Versátil, a calça é ideal para diversas ocasiões, podendo ser combinada tanto com peças casuais quanto mais formais, oferecendo liberdade de movimento.', 239.99, 179.99, NULL, 'Women Clothes > Pants & Leggings > Pants', 'https://cf.shopee.com.br/file/sg-11134201-825aw-mr2304a5le6c75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F23194304341', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42963850491', 'Sabonete Em Barra Lux Flor Do Cajueiro 100g', 'Sabonete Em Barra Lux Flor Do Cajueiro 100g Principais Características: • Fórmula enriquecida com extratos botânicos que cuidam da pele enquanto limpam. • Produz espuma cremosa que proporciona limpeza delicada sem ressecar a pele. • Fragrância inspirada na Flor do Cajueiro, trazendo sensação de frescor e bem-estar. Benefícios: • Mantém a pele macia, hidratada e suave. • Limpeza suave que respeita a barreira natural da pele. • Deixa a pele perfumada por mais tempo, ideal para o cuidado diário. Diferenciais do Produto: • Combinação de ingredientes botânicos com aroma sofisticado. • Textura cremosa que facilita o uso e proporciona sensação agradável. • Produto de qualidade premium que oferece cuidado e experiência sensorial única. Especificações Técnicas: • Peso: 100g Instruções de Uso: • Aplicar sobre a pele úmida, massageando até formar espuma. • Enxaguar completamente. Avisos e Precauções: • Uso externo. • Evitar contato com os olhos. • Manter fora do alcance de crianças. • Conservar em local seco e fresco. O que está incluso? • 1 Sabonete Em Barra Lux Flor Do Cajueiro 100g ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 18.19, 13.89, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me4qit89z01u54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F42963850491', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
