INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43251019586', 'Bíblia Leitura Perfeita | NVI | Letra Normal | Capa Luxo Rosa C/Zíper', 'Bíblia Leitura Perfeita Essa Bíblia é a escolha perfeita para quem quer uma NVI , sem renunciar uma capa versátil e estilosa com zíper. A linguagem NVI (Nova Versão Internacional) é baseada nos seguintes fundamentos: precisão, beleza de estilo, clareza e dignidade, trazendo uma versão ao mesmo tempo, fiel e contemporânea. Nela, você encontrará ainda a fonte Leitura Perfeita . Desenvolvida exclusivamente para a Thomas Nelson Brasil, a Leitura Perfeita é uma fonte singular, moderna, bonita, clara e legível, ao mesmo tempo, em que integra os melhores avanços em tipografia de bíblias modernas. O resultado é uma tipologia que traz total conforto na leitura em qualquer tamanho. Características: Texto na tradução NVI (Nova Versão Internacional) Couro Soft Fonte Leitura Perfeita Letra tamanho normal Letras de Jesus em vermelho Acabamento em glítter Com Zíper Título: Bíblia Leitura Perfeita Linguagem: Nova Versão Internacional Capa: Rosa Ilustrada Acabamento: Capa Luxo Borda: Com Zíper Índice: Sim Harpa: Não Palavras de Jesus em destaque: Sim. Destaque em Vermelho Letra: Normal Fitilho: Não Páginas: 1.184 Dimensões: Altura: 21,5 cm Largura: 13,5 cm Profundidade: 3,5 cm Peso: 0,765 kg ISBN: 9786556896298 Editora: Thomas Nelson', 113.05, 113.05, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9kpi4miqhhe6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F43251019586', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597491908', 'Bíblia Sagrada | NAA | Letra Normal | Couro Legítimo Rubi', 'Bíblia Sagrada | NAA | Letra Normal | Capa Couro Legítimo Rubi A Bíblia Rubi é um lançamento exclusivo da Editora SBB, projetada para os amantes da Palavra de Deus que valorizam qualidade e estilo. Feita com couro legítimo, esta edição apresenta uma elegante borda dourada que adiciona um toque de sofisticação. Seu design compacto a torna ideal para levar consigo em qualquer lugar. Equipada com fitilho duplo, permite marcar várias passagens simultaneamente. A letra laminada na capa garante durabilidade e resistência ao uso diário. Esta Bíblia é uma escolha excepcional para colecionadores e devotos que desejam uma edição confiável e esteticamente agradável, oferecendo um excelente custo-benefício. Páginas: 960 Altura: 24,5 cm Largura: 18 Profundidade: 2,5', 188.33, 188.33, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd6l-lv39bbzw00w686', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F23597491908', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
