INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23991626594', 'KIT RELACAO C/ RETENTOR 1045 CB 250 TWISTER 16/22 DID', 'KIT relação com Retentor DID O Kit Relação D.I.D oferece praticidade por conter em um único produto, os elementos principais para a correta substituição do conjunto de transmissão. A D.I.D oferece um produto com alto padrão de qualidade, segurança com um excelente custo-benefício que atenda às necessidades do motociclista. O Kit é composto por coroa, pinhão, corrente e elo mestre de emenda. A coroa possui têmpera nos dentes para melhor resistência ao desgaste. O pinhão e a coroa são produzidos em aço SAE 1045 termicamente tratados e com acabamento anticorrosivo. O KIT É COMPOSTO POR: - Coroa - Pinhão - Corrente APLICAÇÃO: CB 250 TWISTER 2016 ATÉ 2022 ATENÇÃO: Se houver dúvidas sobre a aplicação do produto ao seu veículo, não deixe de consultar um mecânico de sua confiança. - Imagens ilustrativas. CB 250 TWISTER 16/22', 581.97, 581.97, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lugrz10gcuad63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F362325018%2F23991626594', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
