INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297576607', 'O menino que aprendeu a ver', 'O título desse livro poderia muito bem ser O menino que aprendeu a ler, faria sentido, pois essa é a história de como Joãozinho foi, aos poucos, reconhecendo no mundo (nos outdoors, nas placas de rua, nos jornais) as letras que a professora ensinava na escola. Mas seria um título burocrático, sem graça e sem poesia.Em O menino que aprendeu a ver a gente vive, junto com o personagem, o milagre — a verdadeira visão — da descoberta das palavras, que não são, como pensava o Joãozinho, meros desenhos sem sentido.E, por falar em desenho, que lindos os que a Madalena Matoso criou para tornar ainda mais saboroso o texto da Ruth Rocha!', 77.3, 77.3, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd6d-lvv4g3dyif5b5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22297576607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199261956', 'Porta Fusível Mini Lâmina Com fio HFX 150 - DNI7514', 'O Porta Fusível Míni Lâmina com Fio HFX 150, modelo DNI7514, é um componente essencial para proteger os circuitos elétricos do seu veículo de sobrecargas e curtos-circuitos. Projetado para uso com fusíveis do tipo mini lâmina, este porta fusível oferece uma conexão segura e confiável em uma variedade de aplicações automotivas. Características Principais: Para Tensão não superior a 1000V Compatibilidade com Fusíveis Míni Lâmina: Este porta fusível é projetado especificamente para fusíveis do tipo mini lâmina, comumente encontrados em sistemas elétricos de veículos. Fio HFX 150: Equipado com fio HFX 150, conhecido por sua resistência e durabilidade, proporcionando uma conexão confiável entre o fusível e o circuito elétrico. Dimensões Aproximadas: Cada porta fusível possui dimensões aproximadas de 1,4 x 2,2 x 0,6cm, garantindo compatibilidade com uma variedade de espaços de instalação. Descrição do Produto: O Porta Fusível Míni Lâmina com Fio HFX 150, modelo DNI7514, é a escolha ideal para garantir a segurança e o funcionamento confiável dos circuitos elétricos do seu veículo. Com sua compatibilidade versátil, instalação fácil, construção durável, este porta fusível proporciona uma proteção eficaz contra danos causados por sobrecargas elétricas. Adquira agora o Porta Fusível Míni Lâmina com Fio HFX 150 e mantenha os sistemas elétricos do seu veículo protegidos e funcionando perfeitamente!', 16.73, 16.73, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rd3k-lv9d4ocq3gkyd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972460632%2F18199261956', NULL, NULL, '2026-07-28T02:11:31.708458+