INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099031713', 'Corrente Elo Curto Soldada 5,0mm (3/16") Galvanizada - Selecione a quantidade de metros', 'O preço da corrente está por metro linear Escolha quantos metros quer e lhe enviamos em um só lance, por exemplo , se comprar 10 unidades de 01 metro te enviaremos um lance único de 10metros e assim por diante Corrente 3/16 - 4,8mm Corrente em aço carbono zincado Para usos diversos que não necessitem calibração - Corrente Soldada Zincada - Diâmetro: 4,8 mm (3/16") - Peso por metro: 404 gramas - Resistência Tração: 250 Kgf - Resistência Ruptura: 1000 Kgf - Material: Aço Zincado #TNTFERRAMENTAS', 59.85, 27.9, NULL, 'Home & Living > Tools & Home Improvement > Others', 'https://cf.shopee.com.br/file/br-11134201-820m6-mqxflsajard071', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308179417%2F21099031713', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
