INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594143042', 'Cadeado Para Bicicleta Espiral Elleven 1 Metro Com Chave Cor Preto', 'Aumente sua segurança com o cadeado/corrente Elleven de 1 metro de comprimento e 12mm de espessura, ideal para proteger sua bicicleta contra furtos. Este cadeado é feito de cabo de aço inoxidável, garantindo alta resistência e durabilidade. Seu fechamento em chave proporciona um nível adicional de segurança, e o produto acompanha duas chaves para sua conveniência. O suporte para canote facilita o transporte, permitindo que você leve o cadeado com facilidade em seus passeios. Com um design espiral, o cadeado é compacto e prático, pesando apenas 228 g. A capa protetora de plástico e borracha evita danos à sua bicicleta, tornando-o uma escolha inteligente para ciclistas que buscam proteção eficaz e confiável. Escolha Elleven e pedale com tranquilidade!', 22.48, 22.48, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rasr-maur36ry1qhva3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22594143042', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
