INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898688327', 'Malato de Magnésio 60 Cápsulas Nutrilibrium', 'MALATO DE MAGNÉSIO - O magnésio auxilia no funcionamento neuromuscular; - O magnésio auxilia no processo de divisão celular; - Fonte de magnésio.; - O magnésio auxilia no equilíbrio dos eletrólitos; - O magnésio auxilia no metabolismo de proteínas, carboidratos e gorduras. INGREDIENTES: Magnésio (Malato de Magnésio) e Antiumectante Talco Farmacêutico. INGREDIENTES DA CÁPSULA: Gelatina, Água purificada e Corante Dióxido de Titânio. NÃO CONTÉM GLÚTEN. SUGESTÃO DE USO: Sugere-se a ingestão de 1 (uma) cápsula 1 (uma) vez ao dia. PRODUTO INDICADO PARA MAIORES DE 19 ANOS. ADVERTÊNCIAS: “ESTE PRODUTO NÃO É UM MEDICAMENTO.” “NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM.” “MANTENHA FORA DO ALCANCE DE CRIANÇAS.” CONSERVAÇÃO: Manter em lugar fresco, não úmido e ao abrigo da luz. Não consumir o produto se o lacre de proteção estiver violado. Após aberto, consumir preferencialmente em 60 dias.', 66.12, 49.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi6200yewwshe1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1024736570%2F19898688327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22896349727', 'VODKA ASKOV 900ML', 'Vodka Askov apresenta as suas diversas combinações desde 1948, estando presente em momentos de descontração entre familiares e amigos. Possui 40% de graduação de álcool ela pode ser consumida pura, ou também pode ser usada para preparar outros tipos de bebidas, combina bem com festas e baladas.', 24.9, 24.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljh1lfotzehy41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F22896349727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257909027', 'Kit Farol Milha Farolete Auxiliar Cibie Neblina Completo Gol Voyage G6 2013 2014 2015 16 Plug Play + Touch + Xenon 8000K', '------------------------------ -------------------------------------- O farol de milha é um acessório de segurança em seu carro que lhe proporciona melhor conforto visual na estrada diante de situações adversas de tempo. É importante ter seus milhas em bom estado e claro, ter um produto de ótima qualidade. Compre o seu kit completo conosco e conte com a melhor qualidade de produtos de iluminação automotiva nacionais e importados. ITENS INCLUSOS: > 02 Faróis de Milha; > 02 Molduras Pretas; > 01 Chicote; > 01 Botão Touch; > 01 Relê; > 06 Parafusos; > 06 Porcas Rápidas Automotiva; > 01 Par de Lâmpadas Xenon 8000K H11. APLICAÇÕES: > Gol G6 2013; > Gol G6 2014; > Gol G6 2015; > Gol G6 2016; > Voyage G6 2013; > Voyage G6 2014; > Voyage G6 2015; > Voyage G6 2016; CARACTERÍSTICAS TÉCNICAS: > Lâmpada utilizada: H11 12V. > Suporta lâmpadas até: 35W. > Material lente: Policarbonato. > Textura da lente: Lisa. > Material carcaça: Plástico Resistente. > Encaixe: H11. > Tipo de regulagem: Manual. > Modelo do botão: Touch. > Cor botão: Preto. > Excelente acabamento; > Imagens meramente ilustrativas; > ATENÇÃO: Verifique a compatibilidade com seu veículo antes da compra. GARANTIA: > 3 Meses de garantia contra defeitos de fabricação. > Atenção: Procure um profissional para realizar a instalação. Defeitos ocasionados por má instalação ou mau uso não serão cobertos por garantia. > Não recomendamos o uso de lampadas Superbrancas, comprovado a utilização dessas , ocasionará a perca da garantia. Garantia do vendedor: 3 meses ------------------------------ --------------------------------------', 248.88, 248.88, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-81zul-mn07qgy0dngi1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1310462644%2F58257909027', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17705551364', 'Manga - Vagabond - 14', 'Vagabond - 14 O recém-nascido que veio do mar. Seu nome é Sasaki Kojiro. Retrocedemos no tempo para contar uma nova história de vida. Tipo de Produto: Revista Segmentos: Mangás Marcas: Planet Manga Autor(es): Takehiko Inoue Check-List: Janeiro/2022 Gênero: Ação, Adulto, Artes Marciais, Aventura, Drama, Histórico Demografia: Seinen Editora: Editora Panini Número de páginas: 208 Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 19/01/2022 Idioma: Português', 51.9, 51.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/9c38f98f62002ebc058e5616e748cfcc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F17705551364', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49106456116', 'Mangá - Bakuman Vol. 13 - Editora JBC ISBN 9788545715221', 'Bakuman Vol. 13 Dos criadores de Death Note! O mistério por trás da criação de mangás revelado!Depois de serem informados de que sua série atual, Perfect Crime Party (PCP), não será adaptada para anime, Moritaka e Akito começam a planejar maneiras de criar uma segunda série. Sua melhor chance pode ser se sair bem em um novo concurso onde competirão com seus rivais para ver quem consegue criar a melhor história de romance!'' Autor(es): Takeshi Obata, Tsugumi Ohba ISBN: 9788545715221, 978-85-457-1522-1 Check-List: Março/2026 Editora: JBC Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 22/03/2026 Idioma: Português Condição: Novo/Lacrado', 51.9, 51.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-8262l-ml4ymhuopi4rae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F49106456116', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21160363360', 'Short Jeans Feminino Cintura Alta desfiado Levanta Bumbum Com Lycra Moda Blogueira Stillger', 'Sabe aquele short que você veste e já se sente poderosa na frente do espelho? É exatamente essa a sensação que a gente quer te entregar. Toda mulher merece uma peça-curinga que valoriza o corpo sem apertar, sem marcar e sem aquele desconforto de ficar puxando o tecido o dia todo. O problema é que a maioria dos shorts ou achata as curvas ou é tão rígido que você desiste antes de sair de casa. Este Short Jeans Feminino Cintura Alta Hot Pants foi pensado para resolver isso. A modelagem cintura alta alonga a silhueta e o caimento estratégico realça as curvas com efeito levanta bumbum natural — você se sente confiante, seja no verão, no dia a dia ou numa produção mais caprichada. Por que ele vai virar seu favorito: ✔ Cintura alta que alonga — afina a cintura e estiliza a silhueta na hora ✔ Efeito levanta bumbum — modelagem que valoriza suas curvas naturalmente ✔ Tecido com elastano — acompanha seus movimentos e se ajusta sem apertar ✔ Bolsos funcionais e zíper reforçado — praticidade e durabilidade no uso diário ✔ Fácil de cuidar — pode lavar na máquina sem perder a qualidade ✔ Combina com tudo — fica perfeito com cropped, blusa, camiseta, tênis ou salto Composição: 77% Algodão · 20% Poliéster · 3% Elastano Maciez, elasticidade e resistência numa peça que dura. ❓ Perguntas Frequentes: ➡ Estica? Sim! Possui elastano, garantindo caimento perfeito e conforto. ➡ Desbota com o tempo? Não. É confeccionado com jeans de qualidade que mantém a cor após várias lavagens. ➡ A modelagem é pequena? Não, a forma é padrão. Se prefere mais folga, escolha um número acima. ➡ É igual às fotos? Sim, o produto é exatamente como anunciado. Garanta o seu agora e receba em casa com todo conforto. 🚚', 59.99, 51.9, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/br-11134207-820mh-mq3ld2iqrr40d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F439021441%2F21160363360', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294461080', 'Borracha Guarnicao Porta Malas Opala Caravan Apos 1980', 'Bem vindo à Surielkar Você está com dificuldades ao fechar o seu porta-malas? Pode ser que a borracha esteja desgastada ou danificada, isso impede que seu porta-malas esteja bem fechado. Apresentamos à você essa borracha do porta-malas da marca Jahu, a escolha ideal para garantir a vedação completa do porta-malas do seu veículo. Compatibilidade: Opala, Caravan (1980 a 1992), Chevette, Marajó (1973 a 1994), Brasília, Variant e Variant II (todos os anos e modelos). Qualidade Jahu: Produzida com rigor tecnológico para oferecer desempenho e confiabilidade equivalentes às peças de fábrica. Durabilidade e Segurança: Desenvolvida para suportar condições extremas, proporcionando segurança e durabilidade ao seu veículo. • Informações do produto. Produto: Borracha do porta-malas. Tamanho: 3990mm. Marca: Jahu. Código: 0000317. Se caso tenha alguma dúvida, pergunte abaixo que nosso time estará pronto para atendê-lo(a).', 88.33, 69.78, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-824jk-mf7wgpybt4pb87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F963268018%2F22294461080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41125293977', 'Suporte Para TV Móvel Pedestal De 32-65 Com Bandejas Cor Preto Yesop', 'Suporte Móvel Pedestal Para Tv De 32 A 65 Com 2 Bandejas Cor Preto Yesop Liberdade total para levar sua tela onde quiser. O Suporte Móvel oferece flexibilidade, adaptando-se perfeitamente a qualquer ambiente e necessidade. Compatibilidade sem limites: Perfeito para TVs e monitores de 32" a 65", incluindo modelos LCD, LED, Plasma e curvos. Sua tela tem um lugar garantido. Ajuste perfeito, visão ideal: Encontre o conforto visual ajustando a altura da tela e inclinando-a em até 15°. Diga adeus ao reflexo e garanta o melhor ângulo para filmes, apresentações de trabalho ou videogames. Organização inteligente com 2 prateleiras: As duas prateleiras robustas (uma superior e uma inferior) são ideais para acomodar seu notebook, controle remoto, receptor de TV, câmera para videoconferências ou outros acessórios essenciais. Tudo organizado e ao seu alcance. Mobilidade total e segurança: As quatro rodinhas de alta resistência deslizam suavemente, permitindo que você mova sua tela com facilidade. As travas nas rodas garantem estabilidade. Montagem rápida e prática: O suporte foi projetado para uma montagem simples e intuitiva, com um manual de instruções claro. Em poucos minutos, seu suporte estará pronto para uso. Design versátil: Um suporte prático e elegante, com um design moderno que complementa qualquer ambiente. É ideal para salas de estar, escritórios, salas de reuniões, escolas, eventos e feiras. Versatilidade e estilo em um só produto.', 599.0, 279.0, NULL, 'Home Appliances > TVs & Accessories > TV Brackets', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgg5zoeq213b9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F464586953%2F41125293977', NULL, NULL, '2026-