INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097804255', 'Sofá Austin 2,82m Retrátil, Reclinável com Molas no Assento e Almofadas, Suede Café Cama inBox', 'Chegou o Maravilhoso Sofá Austin O que o torna especial são assentos com espuma D33 envolvidas em fibra Siliconada Compactada para que tenha um toque gostoso e aconchegante, além de seu maravilhoso designer com costuras duplas e puxes que o embelezam, proporcionando conforto de um colchão em um Belíssimo Sofá. Sua sala jamais será como antes! Características: -Encosto Reclinável com 5 posições, almofadas fixas compostas de 80% fibra siliconada e 20% flocos de espuma e percintas elasticas para maior conforto. -Assentos: Retráteis com espuma D33 envolvidas em fibra SILICONADA compactada, Molas espiral, percintas Pneumáticas com feltro para proteger do atrito com as molas. -Braços: Com 25cm de largura, espuma D33 e costuras duplas. -Fixação: Grampos galvanizados -Estrutura de Madeira maciça 100% eucalipto de reflorestamento, produto ecologicamente correto -Tecido suede com toque aveludado Medidas montado: Altura: 102cm Profundidade fechado: 117cm Profundidade aberto: 172cm Largura: 282cm Uma Praticidade: Bipartido (dividido em dois módulos) para facilitar o transporte em corredores estreitos e escadas. *Suporta até 120kg por pessoa *Fácil montagem, não é necessário montador. *6 meses de garantia Fabricante: Cama InBox Informações importantes: - Os objetos que ambientam as fotos não acompanham o produto. - Os tecidos podem sofrer alterações de tonalidades dependendo do lote de produção. - Verifique as dimensões do produto e certifique-se que o percurso que ele fará até o local de uso permite sua passagem. - Nos responsabilizamos pela entrega dos produtos adquiridos até a porta de entrada ou portaria do endereço indicado. Quaisquer despesas ou dano no transporte até o local de uso ficam a cargo do cliente. "As transportadoras não sobem escadas ou elevadores".', 3826.8, 2933.7, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-7rdym-lzot09dwjnfe2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882904544%2F21097804255', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
