INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46061519444', 'Onimusha Warlords PS4 Midia Fisica', 'ONIMUSHA WARLORDS PS4 **PRODUTO 100% ORIGINAL, LACRADO E COM NOTA FISCAL** **PRONTA ENTREGA - ENVIO IMEDIATO** - Mídia: Física (disco ou cartucho no caso se for Nintendo); - Console: Compatível com Nintendo SWITCH, LITE E OLED; - Versão: Importada; - Idioma ou Áudio: Inglês, Japonês; Legenda ou Texto: Inglês, Francês, Espanhol, Português, Japonês; - Jogadores: 1; CONTEÚDO DA EMBALAGEM: 1 (um) Jogo ONIMUSHA WARLORDS PS4; IMAGENS MERAMENTE ILUSTRATIVAS Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor GARANTIA: 90 dia(s) de Garantia - Produto 100% Original. A nota fiscal garante contra defeito de fabricação! **ATENÇÃO** Antes de finalizar a compra, pergunte quantas vezes for necessário e tire todas as suas dúvidas. Nossa equipe de vendedores está à disposição para auxiliar. Se não conseguir localizar o item que precisa ou se necessitar de mais alguma informação sobre o produto entre em contato conosco (GAMER HUT STORE). SOBRE O JOGO O retorno da aventura fascinante de samurai da Capcom! Esta versão inclui a história de vingança dramática e instensas batalhas de espada do jogo original, além de uma série de melhorias. Controles melhorados permitem que jogadores se movam e lutem com precisão do manche analógico. A nítida resolução comporta resolução 16:9 assim como a 4:3 original. Uma nova trilha sonora remete o estilo de vida do Japão feudal com um ar autêntico e intrigante. Vivencie esta versão melhorada do clássico ação-aventura campeão de vendas.', 229.97, 229.97, NULL, 'Gaming & Consoles > Video Games > Playstation', 'https://cf.shopee.com.br/file/sg-11134201-823qo-moyfzj5upbeq3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F594422693%2F46061519444', NULL, N