INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398793252', 'Fritadeira Elétrica AFN-40-BI Sem Óleo Mondial', 'Prepara diferentes tipos de alimentos muito mais rápido do que no forno convencional ou fritando a óleo. Você pode preparar: Batatas congeladas: de 12 a 16 minutos - Nuggets: de 10 a 15 minutos - Peixes: de 6 a 15 minutos - Carnes: de 8 a 14 minutos - Pão de queijo: de 5 a 8 minutos. Características: Abertura da Porta: Frontal Capacidade em Litros:4L Tipo de Fritadeira: Sem Óleo Linha: Air Fryer Modelo:AFN-40-BI Diferenciais da Fritadeira Elétrica: Sem Óleo Consumo Aproximado de Energia:1,5Kw/h Certificações: INMETRO Potência:1500w Controle de Temperatura: Manual Funções da Fritadeira Elétrica: Fritar Temperatura Máxima: 200ºC Material: Polipropileno e Inox Itens Inclusos: Cuba e cesto com revestimento antiaderente. Lâmpadas-piloto que indicam o funcionamento (luz vermelha) e o aquecimento (luz verde) do produto. Painel em aço inox. Acompanha livro de receitas. Dimensões do produto: Altura: 36cm Largura: 36cm Profundidade: 36.5cm Observações: Imagem meramente ilustrativa Verifique a voltagem do produto antes de colocar no carrinho Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor As cores podem sofrer variações de acordo com o tipo, configuração e resolução do seu monitor Não nos responsabilizamos pela montagem/instalação dos produtos', 285.1, 285.1, NULL, 'Home Appliances > Kitchen Appliances > Deep Fryers', 'https://cf.shopee.com.br/file/sg-11134201-7rdxn-md4lgv3jlcyu7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443109642%2F22398793252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
