INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20975432842', 'Panificadora Britânia Multipane Branca', 'A Panificadora Multipane com Timer Britânia facilita a vida ao preparar pães quentinhos e frescos todas as manhãs em sua casa! Ela bate a massa, descansa e assa. Com a função timer é só programar com até 13h de antecedência que o pão estará pronto na hora que você quiser. Possui 3 ajustes de cor do pão: claro, médio, escuro e combinação de até 12 programas diferentes que prepara diversos tipos de pães doces e salgados, geleias, pudins, panetones e muito mais. Ainda produz 4 tamanhos de pães: 450g, 600g, 900g e 1200. Para preparar do tamanho da sua fome! A forma é revestida em material antiaderente, não grudando nas paredes e facilitando a limpeza. E ainda seu delicioso pão fica quentinho por até 60 minutos dentro da Panificadora Multipane. Como não querer todos os dias? Você merece! Bate a massa, descansa e assa. Faz 4 tamanhos de pão 450, 600, 900, 1200gr; Combinações de até 12 programas diferentes; 3 ajustes da cor do pão; • Função Timer (13 horas); Fôrma removível revestida com base antiaderente; Fôrma com capacidade de 3L; Visor de vidro temperado; Acompanha manual de instruções com diversas receitas; Acompanha copo e colher dosadora; Acompanha gancho para remoção do batedor;', 799.9, 799.9, NULL, 'Home Appliances > Kitchen Appliances > Specialty Cookware', 'https://cf.shopee.com.br/file/sg-11134201-823p6-mord9nwq3i0xa9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811879342%2F20975432842', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28079220425', 'Cute & Comfy Desenhos Simples - Edição de Luxo - 12 Lápis de Cor', 'Se colorir é o seu hobby, o Cute & Comfy - Desenhos Simples é perfeito para você! Com 24 ilustrações encantadoras e exclusivas, este livro traz tudo o que você precisa para relaxar, soltar a criatividade e criar artes incríveis. Além disso, ele acompanha 12 lápis de cor, ideais para preencher cada desenho com cores vibrantes e detalhes únicos. 24 ilustrações originais: Cada página foi desenhada à mão para despertar sua imaginação. Desenhos amplos e simples: Perfeito para iniciantes ou quem busca momentos de descontração e foco. Acompanha 12 lápis de cor: Qualidade premium para traços precisos e preenchimentos suaves. Alta resolução: Impressões nítidas garantem um resultado impecável para suas criações. Seja para você, um familiar ou aquele amigo que ama colorir, este livro é uma ótima escolha de presente. Deixe a criatividade fluir e viva momentos de tranquilidade com o Cute & Comfy - Edição de Luxo. Adicione fofura, inspiração e muita cor às suas sessões de pintura!', 39.99, 12.9, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd4h-m7830vcrwvsfa1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F28079220425', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
