INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22124989122', 'Jogo De Garfo Para Sobremesa Brinox Turim 12 Peças Aço Inox', 'Seja Bem-Vindo(a) à Mimorada! O Jogo de Garfo para Sobremesa Brinox Turim é uma escolha prática e elegante para o seu dia a dia. Aqui estão algumas características deste jogo: - Material: Aço Inox - Quantidade: 12 Garfos de Sobremesa - Linha: Turim - Fácil de Limpar: Material em aço inoxidável é fácil de limpar e oferece durabilidade. - Versatilidade: Ideal para o uso diário, seja para servir sobremesas ou outras refeições. Os talheres da linha Turim da Brinox combinam praticidade e durabilidade, sendo uma excelente opção para compor a sua mesa. Eles são fáceis de limpar, proporcionam brilho e resistência, e são ideais para diversas ocasiões, tornando-se um complemento versátil para a sua cozinha.', 44.99, 36.55, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lp0qrc3nv35edc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F22124989122', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
