INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13997219445', 'Jogo de Cartas Now United Super Fã 110 Cartas Copag - 98818', 'O jogo de perguntas e respostas para quem é fã do grupo Now United Um incrível jogo de perguntas e respostas pra quem é super fã do grupo Now United! Gire a roleta e responda perguntas sobre o grupo, suas músicas e muitas outras que só quem é fã de verdade saberá responder. Você ainda terá a chance de testar suas habilidades cantando e dançando suas músicas preferidas, acumular pontos e avançar para se tornar SUPERFÃ. Com o propósito de inspirar, unir e transformar por meio da música, dança e respeito a diversidade o grupo de música pop Now United é formado por 17 membros de diferentes nacionalidades. Cada videoclipe do grupo é gravado nos diferentes países dos integrantes, promovendo a cultura local e imergindo os fãs em uma experiência única! O grupo que já é um sucesso não só no Brasil, mas também no mundo, vem a cada dia conquistando mais fãs em suas redes sociais. Características: - Marca: Copag - Modelo: 98818 Caracteristicas Principais: - Este incrível jogo desenvolve, interação social, memória e coordenação motora. Especificações Técnicas: - Gênero: Meninas/Meninos - Idade: 7 anos ou mais - Material:Cartão - Ocasião de Jogo: Para Família, Para Jogar, Para O Fim De Semana, Para Presente Quantidade de Pessoas: 1 ou mais, 2 ou mais - Tempo de jogo: 30 min - Tipo de Jogo: Jogos Rápidos, Memória, Raciocínio Conteúdo da Embalagem: - 110 cartas (56mm x 87mm) - 1 manual de instruções (156mm x 226mm) - 1 tabuleiro personalizado - 1 seta plástica para roleta - 2 cartelas em cartão com: 6 peões, 6 suportes para os peões, 1 base para roleta e 1 microfone.', 59.2, 53.28, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-22100-onksnzzj35iv62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F13997219445', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
