INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299186425', 'Parabarro Dianteiro Cobalt 2012 2013 2014 2015 2016 Parte Dianteira', 'Parabarro Dianteiro Cobalt 2012 a 2016 🚗🛡️ proteção ideal com encaixe perfeito Características do produto: ✅ Produto novo de ótima qualidade ✅ Fabricado em plástico resistente ✅ Acabamento perfeito ✅ Design versátil e funcional ✅ Encaixe preciso no veículo ✅ Não acompanha fixadores ✅ Apenas parte frontal do parabarro dianteiro ✅ Compatível com Cobalt 2012 a 2016 Você vai receber em sua casa: 📦 1x Parabarro dianteiro (parte frontal) Recomendações de Uso: 👉 Instalação deve ser feita por profissional especializado 👉 Verifique compatibilidade com seu veículo antes da compra 👉 Utilize fixadores adequados para melhor fixação 👉 Não nos responsabilizamos por instalação incorreta', 129.99, 129.99, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Mud Flaps', 'https://cf.shopee.com.br/file/sg-11134201-821fl-mh94zrbkxo23cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1081515950%2F23299186425', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993494026', 'Pastilha Freio Gm Vectra 2010 a 2011 - 173180 - SYL2105', 'Pastilha Freio Gm Vectra 2010 a 2011 173180 SYL2105 Motor 2.0/2.4 - (Dianteiro) (Sistema Teves) (Com Alarme Acústico) As pastilhas de freio são essenciais para a frenagem do automóvel, pois, são responsáveis por 70% desse trabalho. Elas fazem as rodas pararem, ao entrarem em contato com o disco de freio. É bom verificar a espessura das pastilhas a cada 5 mil quilômetros, mas recomenda-se determinar a periodicidade de troca adequada manual do veículo. Importante lembrar a substituição delas pode variar de acordo com o uso do veículo. A vida útil das pastilhas é de 25 a 35 mil quilômetros rodados, em média.', 129.05, 129.05, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbl0-lopx02x99ybyd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23993494026', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697631372', 'Jogo de Velas VECTRA 1993/2006 - 53096 - GV5R01', 'Jogo de Velas VECTRA 1993/2006 MOTOR 2.0/2.2 8V CD/GLS MPFI (GASOLINA) (Vela Resistiva) Conduzir a alta voltagem elétrica para a parte interna da câmara de combustão e transformar essa voltagem em faísca, gerando e inflamando a mistura ar/combustível. Apesar de pequenina e simples, trata-se de um item extremamente importante para o carro. O desempenho da vela vai definir o bom funcionamento do motor, controlar os níveis de combustível e até mesmo a emissão de poluentes.', 73.08, 73.08, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-822zj-mofkvkdzot1n91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23697631372', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897025430', 'Filtro Óleo Vw Logus 1993 a 1996 - 166474 - WUNI0002', 'Filtro Óleo Vw Logus 1993 a 1996 166474 WUNI0002 (GLI / GL / GLS) - MOTOR 1.6/1.8/2.0 AP - Gasolina/Álcool - Mecânico - (Blindado) Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 23.98, 23.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7req5-m9186bfcufpx45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23897025430', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
