INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097064344', 'Jogo Pastilha Freio TUCSON 2010/2016 - 6904 - SYL5260', 'Jogo Pastilha Freio TUCSON 2010/2016 DIANTEIRO (IMPORTADO) 130x56,5x17,6 As pastilhas de freio são essenciais para a frenagem do automóvel, pois, são responsáveis por 70% desse trabalho. Elas fazem as rodas pararem, ao entrarem em contato com o disco de freio. É bom verificar a espessura das pastilhas a cada 5 mil quilômetros, mas recomenda-se determinar a periodicidade de troca adequada manual do veículo. Importante lembrar a substituição delas pode variar de acordo com o uso do veículo. A vida útil das pastilhas é de 25 a 35 mil quilômetros rodados, em média.', 101.63, 101.63, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbkw-ln0ko89tvlxiec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23097064344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793518172', 'Flexível Freio Renault Logan 2008 a 2016 - 195987 - 8240', 'Flexível Freio Renault Logan 2008 a 2016 195987 8240 DIANTEIRO - 440mm É o componente que transmite a pressão hidráulica da tubulação para as rodas, permitindo o livre movimento das mesmas. Promover o controle do veículo em situações de baixo atrito entre pneu e solo, através da modulação da pressão hidráulica de frenagem impedindo assim o bloqueio das rodas. (Mangueira que tem a função de conduzir o fluído Hidráulico entre o cilindro mestre até a pinça de freio).', 39.41, 39.41, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd5q-luv5cq7bxon2c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22793518172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692567982', 'Polia Correia Alternador Vw Fox 2004 a 2020 - 799500 - T451125', 'Polia Correia Alternador Vw Fox 2004 a 2020 799500 T451125 1.6 8v - (Com Ar Condicionado) É o componente que está montado no eixo do rotor do alternador, e por meio de uma correia de distribuição, o alternador gira conforme a velocidade do rotação do motor(Rpm). Esta correia pode ser do tipo trapezoidal ou do tipo poly-V.', 58.53, 58.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rblk-lmxqqw1aq3bt33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22692567982', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497626566', 'Jogo Velas Ignição SPACEFOX 2008/2016 - 7798 - GV7R02', 'Jogo Velas Ignição SPACEFOX 2008/2016 MOTOR 1.6 8V TOTALFLEX (GNV/BI-C.) (Vela Resistiva) Conduzir a alta voltagem elétrica para a parte interna da câmara de combustão e transformar essa voltagem em faísca, gerando e inflamando a mistura ar/combustível. Apesar de pequenina e simples, trata-se de um item extremamente importante para o carro. O desempenho da vela vai definir o bom funcionamento do motor, controlar os níveis de combustível e até mesmo a emissão de poluentes.', 61.04, 61.04, NULL, 'Automobiles > Automobile Spare Parts > Electronics', 'https://cf.shopee.com.br/file/sg-11134201-7rd4b-lwxkovv3bpbdb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23497626566', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
