INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209469618', 'Cachaça 51', 'Aviso: Garantia de procedência. Todos os nossos produtos destilados são adquiridos diretamente da indústria ou de fornecedores homologados. A Cachaça 51 é uma das cachaças brasileiras mais tradicionais, reconhecida por seu sabor suave, equilibrado e versátil. Ideal para ser apreciada pura, com gelo ou como base para caipirinhas e coquetéis, proporcionando uma experiência autêntica, clássica e refrescante.', 17.79, 17.79, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-823pw-moo4irdw1ybl0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58209469618', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11313517029', 'Livro - Ratinhos divertidos - Ciranda Cultural', 'Era véspera de Natal e todos os ratos estavam felizes e queriam celebrar sua época favorita do ano. Eles não se cansavam de brincar! Acompanhe os ratinhos enquanto eles brincam e se preparam para celebrar o Natal e divirta-se com os lindos pop-ups deste livro encantador. Editora: Ciranda Cultural Edição: 1, 2017 Autor: Ciranda Cultural Idioma: Português Páginas: 12 Dimensões: L 24.70 x A 26.70 x E 2.00 ISBN: 9788538075424', 89.9, 89.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/6c7ebe88bc182967e7ca364503df5b88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F11313517029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
