INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597601731', 'Kit 6 Desodorante Aerosol Bozzano Invisible 90g', 'O Desodorante Aerosol Bozzano Antitranspirante Invisible garante máxima proteção contra a transpiração excessiva sem deixa resíduos nas axilas. Garante total conforto e liberdade, pois evita odores indesejáveis controlando a transpiração da pele. Além disso o Desodorante Aerosol Bozzano Anti Invisible Thermo proporciona proteção duradoura e eficaz para a pele, age controlando a transpiração excessiva da pele, mantendo até 48 horas de proteção com máxima descrição, não mancha as roupas e ainda auxilia na hidratação da pele. Modo de usar: Agite antes de usar. Pulverizar a 15 cm de distância da região onde for aplicado. Em caso de entupimento da válvula remova o botão plástico e lave-o com água quente. Sobre a marca: Bozzano é a única marca brasileira que cuida dos homens desde 1946. Só uma marca 100% brasileira e masculina poderia oferecer uma linha completa de produtos que atende todas as necessidades do homem deixando ele pronto para enfrentar seu dia-a-dia.', 72.82, 62.63, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-824gd-mpi0tflvyyvf08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22597601731', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21197997171', 'Kit 2 Esmalte Colorama Solte Suas Cores Cachoeira na Chapada 8ml', 'Sinta a energia e a beleza da natureza com o esmalte Colorama Cachoeira na Chapada. Com um tom sofisticado e acabamento cremoso, ele oferece cobertura intensa e longa duração. Perfeito para quem busca estilo e personalidade em cada detalhe. Solte suas cores e transforme seu visual com Colorama.', 13.98, 13.98, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-825a6-mqn1dttvcg7hb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F21197997171', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
