INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57752468508', 'Camiseta de Time RetrôMania São Paulo 1969 Branco - Masculino', 'Orgulho tricolor em cada detalhe! Camiseta de Time RetrôMania São Paulo 1969 Branco - Masculino Ficha Técnica: Marca: RetrôMania Gênero: Masculino Cor: Branco com detalhes em vermelho e preto Material: 100% Algodão Indicado para: Dia a Dia Time: São Paulo SP Manga: Curta Gola: V Estilo da Peça: Com logo Escudo: Bordado Indicado: Dia a dia Detalhes: Escudo bordado no meio, logotipo da marca no inferior da gola e na parte inferior da camiseta e gola e mangas com listras vermelhas, pretas e brancas Falta uma peça histórica no seu armário? Nenhum torcedor quer deixar passar a chance de ter uma réplica fiel de um dos uniformes mais simbólicos do São Paulo! Por que investir? Inspirada no manto de 1969, esta camiseta homenageia a vitória sobre o Real Madrid no Troféu Colombino. O tecido 100% algodão garante conforto, enquanto as listras vermelha e preta e o escudo bordado exaltam a tradição tricolor. Vista sua paixão com orgulho e reviva a história do clube! Conteúdo da embalagem: 1 Camiseta de Time RetrôMania São Paulo 1969 Branco - Masculino', 219.99, 173.99, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-8227t-mhrxpmezu1vn44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F57752468508', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
