INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493858699', 'VÁLVULA DE ENCHIMENTO CARABINA PCP G850 - QGK', 'VÁLVULA DE ENCHIMENTO PARA CARABINA PCP G850 QGK – EFICIÊNCIA, SEGURANÇA E DESEMPENHO A Válvula de Enchimento para Carabina PCP G850 QGK é um componente essencial para garantir praticidade e segurança no abastecimento do seu equipamento. Desenvolvida especificamente para o modelo G850, proporciona encaixe preciso e vedação eficiente, assegurando um enchimento rápido e confiável. Com construção robusta e materiais de alta qualidade, oferece excelente resistência à pressão e ao uso contínuo, contribuindo para maior durabilidade e desempenho consistente da carabina. Seu design funcional facilita o manuseio, tornando o processo de enchimento mais simples, seguro e eficiente. A vedação adequada é fundamental para manter a pressão ideal do reservatório, garantindo regularidade nos disparos e melhor aproveitamento da performance da carabina PCP. Especificações Marca: QGK Modelo Compatível: Carabina PCP G850 Aplicação: Sistema de enchimento Construção: Alta resistência e durabilidade Instalação: Encaixe preciso e seguro Ideal para reposição ou manutenção preventiva, a válvula de enchimento contribui diretamente para o bom funcionamento e a longevidade do seu equipamento. GARANTIA E SUPORTE A garantia não cobre danos causados por mau uso, desmontagem ou modificações no produto.', 119.9, 78.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rd4j-m7s1h0a0prtg7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1246438712%2F22493858699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20798748855', 'Sandália Babuche Infantil Plugt Menino Escola Antiderrapante Azul Marinho Confortável Leve Promoção', 'Sabe aquele BABUCHE MACIO, VEGANO, ESTILOSO, LINDO E SUSTENTÁVEL? Aqui na PLUGT temos o BABUCHE P-E-R-F-E-I-T-O para os seus P-E-Q-U-E-N-O-S!!! O BABUCHE PLUGT JOY FIBRAS NATURAIS MARINHO têm em sua composição FIBRAS DE COCO E BAMBU, e ele é aquele modelinho completo onde o conforto, a praticidade, a modernidade e a segurança caminham juntos para o dia-a-dia dos nossos pequenos. Além de TOOODAAAS essas qualidades, ele ainda vem com um cheirinho natural das fibras, aquele aroma de coco como sentir a praia em seus pés! Comprimento da palmilha em cm: (Atenção! Meça do dedão do pezinho da criança até o calcanhar e compare com as medidas em cm abaixo) 19/20 - 13,3 cm 21/22 - 14,6 cm 23/24 - 16 cm 25/26 - 17,3 cm -------------------------------------------------------------------------------------- SOBRE NÓS: A Plugt é uma empresa há mais de 20 anos especialista em fabricação de calçados infantis injetados. Os nossos produtos são: - Leves, flexíveis e confortáveis; - Com solado antiderrapante; - Livres de FTALATOS (aceito em toda Europa); - Fácil de lavar; - Macio; - Sustentável, Vegano e Reciclável. Com design ECO e um toque de BRASILIDADE, esse produto possui FIBRA DE COCO E BAMBU, que agrega valores de responsabilidade ambiental, um processo amigo do meio ambiente. Sempre nos inspiramos no poder da imaginação das crianças para criar produtos divertidos e coloridos assim como a Plugt é!, sem deixar de lado o conforto, a praticidade de calce e a facilidade em lavar que as mamães amam! Fabricamos Babuches do 19/20 até o 25/26.', 89.9, 49.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljh4f6zfb9u28c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F284865829%2F20798748855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
