INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898826898', 'VINHO BRANCO SUAVE CASAL GARCIA SWEET 750ML', 'Vinho Casal Garcia Sweet Branco. Elaborado com ingredientes de alta qualidade, as uvas são levadas para o centro de vinificação onde, cuidadosamente, são esmagadas a baixa pressão e logo seguem para a fermentação alcoólica sob temperaturas controladas. Antes do engarrafamento, o vinho é filtrado a frio. Perfeito para apreciar em um fim de tarde ou em um jantar com amigos. Harmoniza com pratos de frutos de mar ou de peixe, ou com sobremesas intensas e doces. A temperatura ideal para servir este vinho é entre 6 e 8ºC. Nesse vinho você encontra castas de Trajadura, Loureiro, Arinto e Azal, no solo granítico e arenoso na região de Vinho Verde/PT', 77.5, 59.99, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdosc6r9yocxa6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F22898826898', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
