INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22816638183', 'Filtro Piscina Dfr 15-7 Com Bomba 1/2 Cv Monofásica Dancor', 'Filtro para Piscina DFR 15-7 com Bomba 1/2 CV Monofásica DANCOR Composto de: Válvula seletora de 6 posições de operação, com manômetro de controle e visor de retrolavagem; Tanque produzido pelo processo de rotomoldagem com parafusos prisioneiros em aço inoxidável; Sistema drenante e meio filtrante (areia sílica) projetados segundo a ABNT; Todos os componentes funcionais são confeccionados em termo plástico de engenharia. *** Bomba para Piscinas de até: 56.000 Litros - 7,00 m³/h (com bomba de 1/2 CV) DADOS COMPLEMENTARES: Marca: Dancor Modelo: DFR-15-7 (SEM AREIA) * Indicado: Piscinas até 56.000 Litros (56m³) em aproximadamente 8 horas com Bomba de 1/2 CV (Obs: bomba de 1/2 CV inclusa) Bomba 1/2 CV DANCOR Carcaça e intermediária (interna e externa) - em ABS reforçado com fibra de vidro, termoplástico de engenharia de excelentes qualidades Rotor - do tipo fechado, injetado em Noryl reforçado com fibra de vidro com ressalto na parte posterior e roscado diretamente na ponta do eixo Vedação do eixo - por selo mecânico - Ø 3/4", tipo "16", conjunto de precisão, construído com borracha nitrílica, mola de aço inox e as faces de vedação em grafite e cerâmica o qual em conjunto com o rotor impedem, totalmente, o contato do líquido com as partes metálicas Tubulação - Sucção e Elevação: 50mm Ø Motor Elétrico Potência: 1/2cv Tensão: Bivolt Monofásico 110/220v (opcional trifásico 220/380v) Norma - Nema MG1-18.326 a MG1 - 18.341 - "Jet Pump" 2 pólos - 3.500 rpm - 60 Hz Monofásico: 110/220V Grau de Proteção: IP 21 lsolamento:Classe "B" Garantia: 18 meses Marca: Dancor Origem: Nacional ACOMPANHA: 4 Uniões para instalação da Bomba e do Filtro * Imagens meramente ilustrativas.', 1446.41, 1446.41, NULL, 'Home & Living >