INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20935511359', 'Cesto Expositor Prático de Plástico Suporta Até 8 KG Cada - Kit 5 Unidades PRESTO', 'Cesto Expositor Prático de Plástico Suporta Até 8 KG Cada - Kit 5 Unidades PRESTO COMBO COM 5 UNIDADES DESCRIÇÃO: O Cesto Expositor Prático Azul Embalagem 5 unidades é a solução inteligente para exposição e armazenamento dos mais diversos itens em estabelecimentos comerciais tais como: drogarias, perfumarias entre outros. Seu diferencial é a embalagem supercompacta que reduz consideravelmente o espaço ocupado no estoque. VANTAGENS: Mais compacto que o modelo tradicional; Pés desencaixáveis: menor custo de frete e menos espaço no estoque; Embalagem com volume até 70% menor que a dos cestos convencionais; Empilha verticalmente; Suporta: 8 kg por cesto; Produzido em polipropileno; Único com porta etiqueta; Maior vão entre os cestos. DIMENSÕES: Largura: 435 mm Altura: 280 mm Profundidade: 375 mm Carga Máxima: 8 KG Código: 42500 / Kit com 5 Unidades Marca: Presto Garantia: 12 meses * Imagens meramente ilustrativas.', 141.9, 141.9, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/2ad08689d2b784604865156da1df1ad7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F20935511359', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22096339637', 'Kit C/ 3 Cueca Boxer Microfibra - Polo Star - Preta - V1', 'Cuecas extremamente confortáveis, perfeitas para ocasiões do dia a dia. As cuecas possuem modelagem boxer e cada peça é confeccionada em microfibra de altíssima qualidade, que oferece ajuste perfeito ao corpo. Uma variedade de modelos para ter conforto em todos os momentos. Guia de Tamanhos: P - Serve 38 M- Serve 40 G - Serve 42/44 GG - Serve 46/48 Composição: 72% Poliamida 24% Poliéster 4% Elastano Este modelo não possui forro interno. O Kit é enviado de forma sortida, podendo haver repetição de cores. A Compramais tem como missão desde 2013 proporcionar satisfação e qualidade para clientes em todo o Brasil. Trabalhamos com agilidade para garantir que seu pacote chegue com rapidez em suas mãos, no conforto do seu lar e sem precisar sair de casa! Temos um catálogo extenso de moda íntima que conta com itens femininos, masculinos e infantis. Ainda tem alguma dúvida? Nos faça uma pergunta! Compramais, paixão em moda íntima.', 59.9, 54.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqeqa0wpk36na9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328687466%2F22096339637', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18297517021', 'Fita Asfáltica Vedatudo 30 cm X 10 m 5 Unidades DRYKO', 'Kit Fita Autoadesiva Asfáltica Vedatudo 30cm X 10m 5 Uni FVD30 DRYKO Dimensões: 30 CM de Altura x 10 Metros de Comprimento Fita autoadesiva multiuso à base de asfalto modificado, autoprotegida com filme de alumínio que permite sua exposição a intempéries e aos raios solares, sendo de fácil aplicação, na qual proporcionam medidas imediatas para solucionar problemas de gotejamento e vedações. Onde aplicar: Telhados. Rufos e chapas metálicas. Dutos de ventilação e ar condicionado. Sheds e cúpulas, Vedações de domos e claraboia. Reparos rápidos em baús, toldos e similares. Sistema de reflexão térmica. Válido por 24 meses a partir da data de fabricação desde que respeitadas às normas de armazenamento. Guardar em local coberto, seco, ventilado e longe de fontes de calor, em ambientes com temperatura não superiores a 30°C e na posição vertical. Garantia: 5 Anos Referência: FVD30 Marca: DRYKO * Imagens meramente ilustrativas', 242.0, 242.0, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rbmt-lnrbooziawimd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F18297517021', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
