INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498874955', 'Saia Festa Junina Preta Xadrez Adulta Com Laços E Babado', 'A Saia Caipira Xadrez Preta Adulto é a escolha ideal para quem quer um look junino moderno e sofisticado. Com acabamento em renda e laços delicados, garante presença marcante nas festas. Essa saia traz a releitura contemporânea da tradicional roupa de festa junina, unindo a estampa xadrez preto e branco com camadas de renda e acabamento em laços de cetim. Ideal para quem deseja fugir das cores típicas e apostar em um visual autêntico, fashion e confortável para os arraiais. Diferenciais: - Estilo xadrez preto clássico com renda preta - Três laços contrastantes em cetim branco e preto - Elástico na cintura para mais conforto e ajuste Indicações de tamanho de acordo com numeração de roupa: P 38 - 40 / M 42 - 44 / G 46 - 48 / GG 50 - 52. Genero: Feminina MATERIAL: Tecido 60% algodao , 40% poliester PERSONAGEM: Caipira Adulta Preta e Branco Descrição: Saia Junina Adulta Xadrez Preto e Branco Codigo do Produto: 943170 Tamanhos: P 38 - 40 / M 42 - 44 / G 46 - 48 / GG 50 - 52 Itens Inclusos: 01 Saia Junina Adulta', 174.99, 174.99, NULL, 'Fashion Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-823oc-mor1b2fyfojyc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410794727%2F22498874955', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
