INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794858943', 'Morsa para Afiação de Corrente Makita', 'Afie sua Corrente com Precisão e Segurança: Morsa para Afiação Makita Mantenha suas correntes de motosserra sempre prontas para o trabalho com a Morsa para Afiação de Corrente Makita, modelo D-67480. Projetada para oferecer afiação precisa e consistente, esta morsa garante cortes mais eficientes, reduzindo o esforço e aumentando a vida útil da sua corrente. Ideal para profissionais e usuários domésticos que buscam alta performance e segurança no cuidado de suas ferramentas. A morsa Makita simplifica o processo de afiação, permitindo que você ajuste o ângulo e a profundidade de corte com facilidade, garantindo um resultado profissional em poucos minutos. Invista na durabilidade e eficiência da sua motosserra com a Morsa para Afiação Makita – a escolha inteligente para quem não abre mão da qualidade. Especificações Código do Fornecedor: D-67480 Marca: Makita Itens Inclusos Morsa para Afiação de Corrente Perguntas Frequentes (FAQ) Pergunta: A morsa é compatível com todos os tipos de corrente? Resposta: A morsa é projetada para correntes de motosserra padrão. Verifique as especificações da sua corrente para garantir a compatibilidade. Pergunta: Qual a garantia do produto? Resposta: Garantia legal: 1 ano Pergunta: É fácil de usar? Resposta: Sim, a morsa foi projetada para ser fácil de usar, mesmo para quem não tem experiência em afiação de correntes.', 61.9, 61.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8262t-mknx50ulaaddaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F22794858943', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198042090', 'ISAAC NEWTON E SUA MAÇÃ', 'ISAAC NEWTON E SUA MAÇÃ Isaac Newton viveu há trezentos anos e vai ser famoso de morrer até o fim dos tempos. Mas por quê? Todos sabem que um dia ele se sentou à sombra de uma macieira e levou uma maçãzada na cabeça, o que o levou a descobrir a lei da gravidade. Só que a história é mais comprida e muito, mas muito mais interessante. Poucos sabem, por exemplo, que Isaac foi o último da classe.Logo nas primeiras páginas, o autor relaciona algumas coisas que contará sobre o grande sábio Por que ele enfiava coisas embaixo do globo ocular e quase ficou cego; como ele conseguiu decompor a luz; como ele inventou todo um novo sistema matemático; por que ele sempre queria guardar para si suas brilhantes descobertas; por que ele queria tocar fogo na mãe (dele); por que a Igreja o odiava; por que os falsários o odiavam; por que, na verdade, quase todo mundo o odiava; por que newtons demais matariam você; por que ele quase foi parar na forca; de quem era o nariz que ele esfregou na parede de uma igreja, e como ele conseguiu, acima de tudo, ser tão inteligente.Título Altamente Recomendável pela Fundação Nacional do Livro Infantil e Juvenil FNLIJ 2001, categoria tradução jovem. Informações Adicionais Autor: KJARTAN; REEVE, PHILIP Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: ISAAC NEWTON E SUA MAÇÃ Idioma: PORTUGUES Páginas: 192 Edição: 1 ISBN-13: 9788535901795 ISBN-10: 8535901795', 60.22, 48.18, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbmq-lpm3zq872y8rfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23198042090', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597300333', 'Progressiva de Chuveiro - Zero Absoluto 100g PROBELLE', '( MODO - LISO NO CHUVEIRO - Efeito Liso De 10 A 15 dias, ) RAPIDO E PRATICO ( MODO PROFISSIONAL - Efeito Liso De 3 A 4 Meses, ) - Resultado de Cabelos De Salão Em Casa - Alta Durabilidade Do Liso - Alisa Até Os Mais Difíceis E Rebeldes -Brilho Intenso De Salão, Volume Controlado Eliminando Completamente A Progressiva de chuveiro Zero Absoluto possuí um condicionamento intenso e sistema térmico que atua protegendo a parte externa dos fios, criando a formação de um filme protetor, efeito anti-frizz e selamento das cutículas capilares. Com a fórmula rica em Óleo de Argan, Tanino e Óleo de Macadâmia, juntos, tem o poder de serem antioxidantes naturais, alinhar, reconstruir, proteger e fortalecer os cabelos, além de dar emoliência, maciez e brilho aos fios. - Sem Formol', 27.9, 24.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-82612-mkntfeczgef610', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648982173%2F21597300333', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13767822836', 'Tonalizante Burguesinha 50g 5.0 - Castanho Claro Probelle probelle', 'TONALIZANTE BURGUESINHA Com 6 óleos essenciais e sem amônia, a BURGUESINHA possui uma fórmula luxuosa e sofisticada, com altíssimo poder colorante. Enquanto você consegue a tonalidade dos seus sonhos, a BURGUESINHA irá regenerar os fios, nutrindo-os em profundidade e devolvendo o movimento natural deles, além de prevenir o surgimento das pontas duplas e de fios ressecados e quebradiços. Cor muito mais viva, intensa e de longa duração. Cabelos ainda mais saudáveis e com um brilho impecável. Ativos: Tonalizante sem amônia e com Óleos de: Argan, Linhaça, Castanha, Lótus, Girassol e Semente de Uva.', 16.45, 16.45, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-8261j-ml6ejru57axb7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648982173%2F13767822836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
