INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23999175737', 'Fone de Ouvido Bluetooth Preto | Flow TWS Gen 2 iWill', 'Compacto, moderno e com graves intensos, o TWS Flow da iWill entrega uma experiência sonora prática e envolvente. Totalmente sem fios, ele conta com comando touch direto nos fones, permitindo controle de músicas e chamadas com apenas um toque. Com até 4.5 horas de reprodução ele oferece até 13.5 horas de uso total. Sua tecnologia True Wireless proporciona liberdade total de movimento, enquanto o Bluetooth 5.3 garante uma conexão estável e rápida, com alcance de até 10 metros. Desenvolvido com design intra-auricular e acabamento discreto, é ideal para quem busca um acessório de áudio com performance, estilo e praticidade. Especificações Técnicas: Tecnologia True Wireless (TWS) Comando touch direto nos fones Bluetooth 5.3 Até 4.5h de reprodução contínua* Tempo total de uso com o estojo: até 13.5h Design compacto e intra-auricular Frequência: 20Hz – 20KHz Impedância: 32Ω (100Hz) Sensibilidade do microfone: 42 ± 1dB Distância de funcionamento: até 10 metros** Capacidade da bateria: fones 30mAh | base 200mAh Entrada USB-C (DC 5V – 1A) Certificação ANATEL Garantia de 1 ano * O tempo de reprodução pode variar de acordo com o volume, estilo musical e uso do microfone. *A distância de funcionamento pode ser afetada por obstáculos físicos e interferências no ambiente. Imagens ilustrativas. As cores podem variar conforme o monitor ou lote de fabricação.', 249.9, 129.9, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh82px7yb08we2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013839557%2F23999175737', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299184854', 'Cabo MFi Lightning para USB Branco | Elite Cable Coca-Cola', 'O Cabo Elite USB para MFi da Coca-Cola é uma fusão de estilo e desempenho para suas necessidades de carregamento. Com design exclusivo, este cabo é construído com durabilidade em mente. Feito em termoplástico antidesgaste com revestimento de poliéster incrivelmente trançado, junto com 4 camadas de reforço interno e um housing ultra reforçado testado 20.000 vezes à torção que garantem resistência e longevidade. A velocidade de transferência de dados de até 480Mbps e a capacidade de aceitar correntes de até 2.4A tornam-no ideal para carregamentos mais rápidos. Equipado com um chip homologado Apple®, este cabo de 1,2m suporta carregamentos de até 12W, proporcionando uma experiência de carregamento eficiente e segura. Especificações: Cabo em termoplástico (TPE) com revestimento de poliéster trançado duplo, feito em material antidesgaste Possui 4 camadas de reforço interno Housing ultra reforçado testado 20.000 vezes a torção Velocidade de transferência de dados com até 480Mbps Aceita corrente de até 2.4A Chip homologado Apple® que suporta carregamentos de até 12W Comprimento: 1,2m (3’9”) 5 anos de garantia Garantia de 5 anos contra defeitos de fabricação. A garantia engloba os 3 meses de Garantia Legal. Imagens ilustrativas. As cores podem variar de acordo com o monitor ou lote de fabricação.', 149.9, 79.9, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh0x8ohtlm2ve0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013839557%2F23299184854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
