INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42382207836', 'Subwoofer Ativo Slim Bass Compact Frahm 60WRms Preto', 'Subwoofer Ativo Slim Bass Compact Frahm 60WRms Preto A Frahm, uma marca que se destaca na indústria de áudio, continua sua jornada de inovação com o lançamento do Subwoofer Slim Bass Compact. Este novo produto exemplifica o compromisso da Frahm em fornecer soluções integradas de áudio que revolucionam a maneira como experienciamos o som. Informações Técnicas: • Potência: 60W RMS • Amplfiicador: Classe D • Resposta de frequência (-10dB): 25Hz ~ 200Hz • Impedância de entrada: 10K • Alto-falante: 6 • Material do cone: Vacuum Form • Material da borda: Borracha • Volume interno: 10L • Bivolt automático: 100V ~ 240V • Dimensões (AxLxP): 332x160x280 • Peso: 4,7 Kg Conteúdo da Embalagem: • 01 Subwoofer Slim Bass Compact • 01 Fonte DC 20V 4 Ohms • 01 Manual de instruções', 817.15, 689.9, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/br-11134207-820l4-mq5e1dwurif5b3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F42382207836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494924405', 'Chuteira de Futsal Penalty Max 500 Adulto Lançamento Original', 'Desenvolvida para atletas que buscam o máximo em performance e conforto, a Chuteira Futsal Penalty Max 500 Locker Y-3 é a escolha perfeita para você que leva o futsal a sério. Com um design moderno e tecnologias inovadoras, essa Chuteira de Futsal proporciona uma experiência única em cada jogo. Benefícios: Ajuste perfeito. Conforto. Durabilidade. Desempenho. Alguns diferenciais técnicos : A Chuteira Futsal Penalty Max 500 Locker Y-3 possui o cabedal construído com um processo de termofusão sem costuras, e em tecido oferece leveza, flexibilidade e ajuste perfeito aos pés, proporcionando maior conforto e controle da bola. Com a tecnologia Neo Cushion garante amortecimento e absorção de impactos, reduzindo o stress nas articulações e proporcionando maior proteção durante as partidas mais intensas. Além disso esse Chuteira de Futsal possui solado com tecnologias Rotate, Ultra Grip e Non-Marking, combinação dessas tecnologias garante máxima aderência em diferentes tipos de piso, agilidade nos movimentos e durabilidade, sem deixar marcas na quadra.', 449.85, 239.8, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/br-11134207-820l4-mmhooeyzd4p3e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1716040168%2F23494924405', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
