INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56607630779', 'Kit 4 Ventiladores De Parede 200w 60cm Com 3 Pás Bivolt Potente P/ Igreja Academia Lojas Comércios', '1 COMPRA = 4 UNIDADES Ventilador de Parede STUART 60cm Preto, com 200W de potência, ideal para grandes espaços como lojas, escolas, igrejas, restaurantes, indústrias e ambientes que necessitam de alta ventilação. Hélices em plástico: Além de resistentes, são leves, proporcionando melhor desempenho e maior vida útil do motor. Oscilação horizontal: Garante melhor distribuição do ar por todo o ambiente. Regulagem de inclinação manual: Permite direcionar o fluxo de ar conforme a necessidade. Pintura eletrostática: Grade com alta resistência e maior durabilidade. Chave de controle de velocidade: Acompanha controle deslizante para ajuste das velocidades. Ambientes indicados: Indústria, Loja, Comércio em geral Finalidade de uso: Ventilador de Parede Marca: STUART Linha: Industrial Medida: 60cm Potência: 200W Voltagem: Bivolt Cor: Preto', 1499.99, 899.99, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/br-11134207-820m3-mm7jm00d1vr48d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F601021305%2F56607630779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
