INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698319206', 'Regulador Para Nitrogênio Alta Pressão 1000 Psi / 70bar WWSoldas', 'O Regulador de Nitrogênio de Alta Pressão W49 Da WWSOLDAS é uma peça essencial para trabalhos que exigem nitrogênio em alta pressão, garantindo controle e segurança durante o processo. Projetado para atender às demandas de aplicações industriais e profissionais, este regulador oferece precisão e durabilidade, tornando-o ideal para soldagem, testes e outras tarefas que requerem nitrogênio a altas pressões. - Principais características e vantagens: Alta Pressão: Projetado especificamente para operar em pressões elevadas, garantindo o fornecimento de nitrogênio de acordo com as necessidades do seu projeto. Controle Preciso: Este regulador permite ajustes precisos de pressão, garantindo que o nitrogênio seja entregue com a precisão exigida Construção Robusta: Construído com materiais de alta qualidade, o Regulador de Nitrogênio Hulter é durável e confiável em ambientes desafiadores. Segurança: Projetado com segurança em mente, esse regulador é uma escolha confiável para garantir a operação segura de sistemas de alta pressão. - Informações Adicionais Tipo de produto: Regulador de Nitrogênio de Alta Pressão Código: 5601434 Marca: WWSOLDAS Visores com 63mm de diâmetro e proteção emborrachada; Medidor de alta pressão de 4500 PSI; Medidor de baixa pressão de 1000 PSI; Válvula de segurança verticalizada; Registro independente para o cilindro; Válvula de Controle para o Sistema; Estagio simples. Itens que Acompanham 01 Regulador de Nitrogênio Alta Pressão W49. Espigão para mangueira 5/16', 339.0, 269.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7cksjox2edmd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F283838689%2F23698319206', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208807132', 'Extratora de Sujeiras Portátil WAP Spot Cleaner W3', 'Apresentamos a incrível Extratora Portátil WAP Spot Cleaner W3, sua solução definitiva para uma limpeza descomplicada. Com seu bico 3 em 1, você pode borrifar, esfregar e extrair, tornando-a perfeita para a limpeza impecável em áreas localizadas. A magia não para por aí! Com um design compacto e portátil, a Extratora de Sujeiras WAP Spot Cleaner W3 é sua companheira ideal para o trabalho em espaços pequenos. Fácil de guardar e transportar, sua alça permite que você a leve para onde a limpeza profissional ocasional exigir, sem esforço. O bico de autolimpeza tem como objetivo facilitar a manutenção do produto, prolongando a vida útil do produto e facilitando que o usuário não toque na sujeira ao fazer a manutenção. E com o suporte para bico e o suporte integrado para a mangueira flexível, você terá todos os acessórios essenciais da extratora ao alcance das mãos, tornando cada etapa de limpeza conveniente e eficiente. Com a Extratora WAP SPOT CLEANER W3 você está pronto para qualquer desafio! Ela possui um recipiente para água suja com capacidade total de 850 ml e um recipiente de água limpa com capacidade de até 1,1L. Dê adeus as sujeiras localizadas em tapetes, estofados, sofás, colchões, carpetes e até bancos de carros – a WAP Spot Cleaner W3 é sua aposta confiável para uma limpeza versátil e eficiente. WAP | Deixa tudo mais fácil!', 755.9, 755.9, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/sg-11134201-81zuu-mn1g2o30o16r1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1515185730%2F58208807132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998107524', 'Luva Mucambo 280 Flex Profissional Flocada Amarela Tamanho P - Embalagem com 10 Pares', 'Características do Produto: Marca: Mucambo Referência: 280 Cor: Amarela Tamanho P Luva Profissional flocada 100% algodão Menor espessura proporcionando maior precisão com conforto e segurança. Oferece resistência à abrasão, perfuração e rasgo, combinada com a flexibilidade e maleabilidade do látex natural. Palma antiderrapante em alto relevo para maior aderência no uso em meios líquidos. Muito utilizada em serviços gerais de conservação e limpeza, manutenção em fabricas, indústrias químicas, construção civil, agroindústria, preparação e manipulação de alimentos. Embalagem com 10 Pares Fornecedor:Mucambo', 47.02, 47.02, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-824ig-mpia8a1czf9n70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23998107524', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
