INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497609139', 'Capa De Chuva Motoqueiro Conjunto Pvc Impermeável Moto Race', 'Descrição: - BOLSO INTERNO E EXTERNO (com proteção) - 100% impermeável + costuras seladas - cor preto - Temos nos tamanhos P, M, G, GG e XG - Material resistente - Maleável para usar e guardar - Material: 100% Couro Sintético Pvc Flex - Segurança: Refletivos nas costas - Conforto: Flexível com costuras seladas - Cores: Preto - Versão unissex TAMANHOS: P : ALTURA 1.45 CM PESO: 60KG M: ALTURA 1.56 CM PESO: 70KG G: ALTURA 1.70 CM PESO: 80KG GG: ALTURA 1.80 CM PESO: 100KG EXG: ALTURA 1.95 C PESO: 110KG Conteúdo da Embalagem: - 01 Jaqueta - 01 Calça Conjunto motocliclista, confeccionado em PVC forrado 028mm, 100% impermeável, na cor preta, composto por: Blusão de segurança com gola alta, mangas longas raglãn com ajuste no punho por velcro, fechamento frontal por meio de zíper e velcro, carcela interna para proteção do zíper, bolso interno, bolso externo no peito com tampa fechada por velcro, elástico na cintura, refletivo nas costas e na tampa do bolso. Calça de segurança com elástico na cintura, zíper nos tornozelos para ajustes. CERTIFICAÇÃO: O conjunto motociclista se enquadra dentro da NR6, por ser considerado um equipamento de proteção individual – EPI, possui certificado de aprovação – CA, sendo o Blusão: CA 28.481 e a Calça: CA 28.482, aprovado para proteção dos usuários em atividades com uso de água e precipitação pluviométrica. MANUTENÇÃO: Lavar com água e sabão neutro, usar preferencialmente o método de lavagem manual, caso utilize a maquina de lavar colocar na posição de roupas delicadas, secar a sombra em local fresco e arejado. Não utilizar produtos químicos.', 140.43, 140.43, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Rain Coats', 'https://cf.shopee.com.br/file/br-11134207-7r