INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194326527', 'Eletrodo 2,5 x 350 mm caixa com 1 kg E6013 - 41.001', 'Produto: Eletrodo 2,5 x 350 mm caixa com 1 kg E6013 - 41.001 Marca: Disflex Descrição: O Eletrodo 2,5 x 350 mm caixa com 1 kg E6013 41.001 da Disflex é a solução prática e eficiente para seus projetos de soldagem! Este arame MIG E71T-GS é um dos destacados no mercado por ser um arame tubular auto-protegido, perfeito para a soldagem de chapas finas de aço carbono. Ideal para quem procura eficácia e praticidade em solda ao ar livre ou em lugares sem acesso fácil a gás de proteção externo. Desenvolvido para reduzir custos e aumentar a eficiência, este eletrodo é fácil de manusear e operar em todas as condições atmosféricas e posições de solda. Com a marca Disflex, você está adquirindo um produto de alta qualidade que garante segurança e durabilidade, superando as expectativas em diversos aspectos do processo de soldagem. Características: • Praticidade: Não necessita de gás externo, reduzindo a complexidade e os custos operacionais; • Versatilidade: Adequado para uso tanto em ambientes internos quanto externos, ideal para reparos rápidos ou projetos prolongados em qualquer local; • Facilidade de uso: Projetado para operar em todas as posições de solda, facilitando o trabalho em áreas de difícil acesso; • Eficiência: Alcança excelente penetração de solda e cria juntas de alta qualidade com menos passagens, economizando tempo e material. Especificações: Diâmetro: 2,5 mm Comprimento: 350 mm Quantidade: 1kg. Dimensões (C x L x A): 36.00 x 5.00 x 2.00 centímetros Peso: 1.00 Kg', 40.3, 40.3, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825b9-mqzz80a44bnl44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F23194326527', 