INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499841627', 'Alicate Bico Meia-Cana Reto 9 Eletricista 1000V Vonder', 'O alicate bico meia-cana reto 9" da Vonder é a ferramenta ideal para eletricistas que buscam precisão, segurança e multifuncionalidade em instalações elétricas. Com cabo isolado para até 1.000 V~, é indicado para corte de fios e arames macios, além de permitir o manuseio de terminais em locais de difícil acesso com total controle e firmeza. Fabricado em aço cromo vanádio, oferece alta durabilidade e resistência ao desgaste. O modelo ainda conta com função para crimpar e desencapar fios, otimizando o tempo de trabalho e reduzindo a necessidade de trocar de ferramenta. Sua pegada ergonômica com cabo emborrachado proporciona mais conforto durante o uso prolongado. Características: Modelo: Bico meia cana reto Referência: 3662009230 Material do corpo do alicate: Aço cromo vanádio Acabamento: Escurecido com faces polidas Comprimento total: 9" - 228 mm Tipo do cabo do alicate: Cabo em borracha termoplástica (TPE), isolado 1.000 V Massa aproximada: 0,390 kg Benefícios: Isolado para até 1.000 V~, ideal para trabalhos elétricos Alta durabilidade com corpo em aço cromo vanádio Funções de crimpagem e decapagem integradas Ponta longa que facilita o acesso em locais estreitos Cabo emborrachado que garante conforto e segurança Conteúdo da embalagem: 1 Alicate bico meia-cana reto.', 121.19, 92.93, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdyk-mdc652uz904mf5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F21499841627', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699506555', 'Kit Creamy B Complex 20 Calming Cream (2 produtos)', 'Kit Creamy B Complex 20 Calming Cream (2 produtos) Este Kit Contém Creamy Niacinamide B Complex 20% - Sérum Ultraconcentrado 30ml: possui um blend de vitaminas (B3, B5, B6, B12 e E) que age no fortalecimento da barreira cutânea, melhorando a aparência, textura e tonalidade da pele. Ele garante o aumento da hidratação, reduz a aparência de poros dilatados e auxilia no controle da acne. Creamy Skincare Calming Cream - Creme Hidratante Facial 40g: hidratante facial para pele sensível ou sensibilizada. Conselho de Aplicação Niacinamide B: uso diurno e noturno. Aplique uma fina camada sobre a pele completamente seca após sua rotina de limpeza facial. Calming Cream: aplicar sobre a pele completamente seca, de 1 a 2 vezes ao dia, espalhando até absorção completa. Reaplicar conforme desejado.', 307.35, 164.9, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdxv-m18sg1tkgk6y7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F18699506555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094061085', 'Haskell Lamelar - Shampoo 300ml', 'Haskell Lamelar - Shampoo 300ml Indicação: para todos os tipos de cabelo Promove limpeza equilibrada e tem ação hidratante. Com formulação equilibrada, ele inicia o processo de tratamento profundo aos cabelos graças a poderosa da tecnologia lamelar com ativos de alta performance. Repõe a massa capilar, reduz a porosidade e a aspereza das lâminas danificadas, promove alinhamento, força extra e muito brilho aos fios. pH 5.5 e vegano. Conselho de Aplicação Nos cabelos molhados, aplique o shampoo, massageando o couro cabeludo em suaves movimentos circulares. Enxágue bem. Se necessário, repita a aplicação.', 101.8, 58.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rasu-ma37la3boa5866', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22094061085', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
