INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593232479', 'Skate com Boneco SK8 CREW (Fone Azul) 96mm - Tech Deck', 'Descrição: "A nova linha de SK8 Crew chegou e desta vez estão ainda mais radicais! Faça as manobras mais incríveis que só você conseguirá realizar! Cada pack contém um skate de dedo e uma figura para colocar no skate, ambos os itens são ricos em detalhes para agradar a todos os fãs, proporcionando uma experiência autêntica de skate. Suba no seu skate e embarque em uma aventura radical, explorando diferentes locais e desafiando a gravidade com suas manobras ousadas. Deixe sua criatividade fluir enquanto você cria suas próprias rotas e desafios, tornando cada sessão de skate uma experiência emocionante e única. Com a nova linha SK8 Crew, a diversão é garantida enquanto você domina as pistas e se torna o mestre das manobras radicais!" Características: Marca: Sunny Brinquedos Referência: 4190 Idade recomendada: A partir de 6 anos Pilhas Inclusas? Tipo de Pilha/Bateria Não necessita de pilhas Possui Luzes: Não Possui Sons: Não Dimensões aproximadas da embalagem: 17,8 x 14 x 5,8cm (A x L x C) Garantia: 3 meses a contar da emissão da Nota Fiscal Embalagem: Conteúdo da embalagem: 1 Skate de Dedo e 1 Boneco Certificado Inmetro: REGISTRO 005587/2023 Produtos de decoração não inclusos. Imagens meramente ilustrativas. As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 79.99, 75.19, NULL, 'Hobbies & Collections > Toys & Games > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdxp-lzav1qa9pd6v2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F23593232479', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992778745', 'Carrinho Monster Jam 1:64 - Soldier Fortune Black Ops', 'Descrição:Recrie As Corridas De Monter Jam Com Os Mais Novos Veículos! Esta Magrinha Máquina Da Monster Jam Possui Mais Detalhes E Gráficos Do Que Nunca! Com O Oficial Bkt Tires, Jantes Cromadas Estilizadas E Um Chassis Autêntico Com Detalhes Cromados, Este Monster Truck Incorpora O Estilo E A Elegância Da Sua Contraparte Da Vida Real! Além Disso, Este Caminhão Vem Completo Com Um Driver Moldado No Banco Do Motorista E Uma Estatueta Colecionável Monster Jam, Para Que Você Possa Montar O Palco De Sua Própria Arena Monster Jam! E Agora, Com Mais Caminhões Para Colecionar Do Que Nunca, É Fácil Acompanhar Sua Coleção Com O Cartaz De Colecionador Exclusivo! Comece A Construir Sua Coleção Monster Jam Hoje Mesmo!Características:Marca: Sunny BrinquedosReferência: 2025Série: -Idade recomendada: A partir de 4 anosUsa Pilhas/Baterias ?: NâoPossui Luzes: NãoPossui Sons: NãoDimensões aproximadas do produto: 6 x 6,8 x 10cm (A x L x C)Dimensões aproximadas da embalagem: 10 x 14 x 8,5cm (A x L x C)Garantia: 3 meses a contar da emissão da Nota FiscalEmbalagem:Conteúdo da embalagem: 1 Veículo Monster Jam - Escala 1:64Certificado Inmetro: REGISTRO 003267/19 OCP 0006.Produtos de decoração não inclusos. Imagens meramente ilustrativas.As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário.', 69.99, 65.79, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-7rbkq-lptqen5bnt4q8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F22992778745', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
