INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205514314', 'BONE GP TECH JAPAN MOTEGI PRETO', 'Boné GP Tech O Boné GP Tech é a escolha ideal para quem busca estilo, conforto e durabilidade no dia a dia. Com um design moderno e versátil, ele se adapta perfeitamente a diferentes ocasiões – seja para proteger do sol ou complementar seu visual com atitude. Fabricado com uma composição de 87% poliéster e 13% algodão, oferece excelente respirabilidade, leveza e resistência. O tecido proporciona um toque macio, garantindo conforto mesmo em longos períodos de uso. Características: -Design ergonômico e ajuste confortável -Material leve e resistente -Ideal para uso casual, esportivo ou motociclismo -Fácil de limpar e secar rapidamente Seja nas ruas ou na estrada, o Boné GP Tech é seu parceiro ideal para um look urbano com performance. Garantia 3 meses defeito fabricação Foto Ilustrativa Acelere Seu Estilo com o Boné GP Tech Exclusivo da Paulinho Motos! BONE GP TECH JAPAN MOTEGI PRETO Descubra o Boné GP Tech na Paulinho Motos! Estilo e performance para os amantes de motociclismo. Compre agora e eleve seu visual!', 79.9, 79.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Clothing and Boots', 'https://cf.shopee.com.br/file/sg-11134201-82633-mkxx31rwqcxyb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1025296952%2F58205514314', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
