INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205841614', 'CD Def Leppard - Diamond Star Heroes Live From Sheffield (Limited Edition / 2CD) - Importado', 'CD Def Leppard - Diamond Star Heroes Live From Sheffield (Live From Bramall Lane, Sheffield / Limited Edition / 2CD) - Importado Em 22 de maio de 2023, 47 anos após sua formação, o Def Leppard retornou à sua cidade natal para realizar seu segundo show em estádio, no Bramall Lane, em Sheffield. Dando início à sua turnê europeia, este monumental show de retorno foi apresentado para uma plateia lotada e vibrante de quase 40.000 fãs. O repertório incluiu clássicos como "Photograph" e "Pour Some Sugar on Me", além das estreias ao vivo no Reino Unido de "Take What You Want" e "This Guitar", esta última dedicada ao saudoso guitarrista da banda, Steve Clark. Repertório dos CD: CD-1: 1. Take What You Want 2. Let''s Get Rocked 3. Animal 4. Foolin'' 5. Armageddon It 6. Kick 7. Love BItes 8. Promises 9. This Guitar 10. When Love And Hate Collide CD-2: 1. Rocket 2. Bringin'' On The Heartbreak 3. Switch 625 4. Hysteria 5. Pour Some Sugar On Me 6. Rock Of Ages 7. Photograph', 99.9, 84.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-8258b-mr0j8cwu18n64c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F58205841614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200639080', 'Par De Amortecedores Traseiro Tmac Honda Pop 100 2007 até 2015', 'Par Amortecedor Traseiro Cromado Tmac Os amortecedores desempenham um papel fundamental na absorção de impactos e na suavização das irregularidades da estrada, proporcionando uma condução mais confortável e estável. Fabricados com materiais resistentes e projetados para suportar as condições variadas das ruas, esses amortecedores garantem uma pilotagem suave e segura. Compatibilidade do Produto: Honda C-100 Biz ES/KS — 1998 a 2015 Honda Pop 100 — 2007 a 2015 Honda Biz 110i — 2016 a 2022 Honda Pop 110i — 2016 a 2022 Esses amortecedores servem perfeitamente tanto na linha Biz quanto na Pop, incluindo as versões mais recentes (110i). Com design atualizado e fabricação robusta, sua moto terá mais conforto, segurança e beleza. --- Pronta entrega com envio em 24 Horas ---', 179.0, 157.52, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-821d5-mh2cican41lab1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1645057427%2F58200639080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
