INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200093178', '10 Peças Extrator De Rolamento Prático Para Motocicleta', 'Este extrator de rolamento de motocicleta é feito de artesanato requintado e material premium, com excelente durabilidade e praticidade. O design da estrutura é razoável e o uso é mais simples e conveniente. Fácil de usar - A ferramenta extratora de rolamento de motocicleta é projetada para remoção rápida e eficiente de rolamentos de rodas de motocicleta. Com operação simples, os motociclistas podem remover facilmente os rolamentos Versátil - Este extrator manual de motocicleta para serviço pesado e extrator de rolamento cego oferece uma pegada segura e alavanca, reduzindo o esforço necessário para a remoção. O kit extrator de rolamento é adequado para a maioria dos modelos, incluindo motocicletas, carros compactos, veículos de médio porte e caminhões leves Conjunto completo de ferramentas para motocicleta - O extrator manual de motocicleta de 10 peças vem com um conjunto abrangente de ferramentas, incluindo um par de luvas e 10 mandíbulas diferentes que variam de 8 mm a 25 mm para acomodar vários rolamentos de cubo de motocicleta. Este kit de ferramentas para remoção de rolamentos de roda fornece tudo o que é necessário para remoção e substituição rápida e precisa de rolamentos Remoção de rolamentos cegos - O extrator de rolamentos de roda de motocicleta é projetado especificamente para remover rolamentos do lado cego do cubo, garantindo uma remoção fácil e segura sem danificar o cubo ou o rolamento Extrator de rolamentos portátil - Nosso kit de ferramentas para cubos de motocicleta para serviços pesados é feito de liga de aço, com a haste roscada tratada termicamente e escurecida, tornando-a uma excelente ferramenta de remoção de rolamentos. O design da caixa de armazenamento garante conveniência para armazenar e transportar Especificação: - Cor: Vermelho (caixa), Preto (extrator). - Material: Plástico (caixa), Aço de liga (extrator). - Tamanho: 21*14*6,5 cm - Nota: faixa de fixação: 25-65 mm. Lista de embalagem: 10x extratores de rolamentos 1 x caixa de plástico Garantia do vendedor: 1 meses', 499.0, 499.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-825b8-mgdidx3vk1l707', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1442717886%2F58200093178', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
