INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494191407', 'Rolamento Caixa Direção Cg 125 1976 a 1999 Xls 125 1981 a 1997 Kansas 150 2007 a 2015 (Cônico)', 'Aplicação do Rolamento Caixa de Direção Compatível com: Motos Honda: Cg125 1976 a 1999 Xls125 1981 a 1997 Cbx200 1996 a 2003 Motos Kasinski: Kansas150 2007 a 2015 Comet150 2008 a 2017 Mirage150 2009 a 2014 Next250 2006 a 2009 Obs: Considerar o ano modelo de sua moto. Exemplo: ano fabricação 2009 / ano modelo 2010 - Equivale ao ano 2010. Especificações técnicas: Código do fabricante: LAQ1102671 Material: Aço de alta resistência, garantindo durabilidade e ótimo desempenho. Acabamento: Tratamento anticorrosivo para maior vida útil e resistência ao desgaste. Compatibilidade: Desenvolvido para aplicação perfeita na caixa de direção original da motocicleta. A Marca: A GP7 tem foco em baixa e média cilindrada, é maior linha de peças de reposição para motores e chassis de motocicletas da Laquila e oferece o reconhecido e consolidado padrão de qualidade para as mais variadas soluções em motocicletas. Prazo de Garantia: 3 meses para defeito de fabricação Importante: - Para a instalação correta do produto, leve ao mecânico de sua confiança! - Não nos responsabilizamos pelo uso indevido do produto ou vícios de instalação.', 32.69, 32.69, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rdy0-mbqqcx0p1rbh32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369066095%2F23494191407', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
