INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597897841', 'HIDRATANTE HYDRO BOOST WATER GEL NEUTROGENA REFIL 50G', 'Neutrogena Hydro Boost Water Gel Refil 50g Neutrogena Hydro Boost Water Gel Refil que restabelece os níveis de água da pele ao longo do dia, estimula sua renovação, fortalecendo a barreira de proteção natural contra o ressecamento. Com exclusiva textura ultraleve gel de rápida absorção, hidrata por 48 horas controlando e reduzindo a oleosidade. Benefícios e diferenciais: -48h de hidratação: preenche instantaneamente a pele com 2 vezes mais hidratação. -Com ácido hialurônico: restabelece os níveis de água na pele e estimula sua renovação, fortalecendo a barreira natural da pele. -Textura ultra leve water gel: controle da oleosidade. -Dermatologicamente testado e não comedogênico: não obstrui poros. -Ideal para todos os tipos de pele, inclusive peles oleosas. Modo de Uso Com a pele limpa, aplique o produto sobre o rosto e pescoço e espalhe suavemente até a absorção completa. Pode ser usado diariamente, pela manhã e/ou à noite. Pode ser aplicado antes da maquiagem.', 69.99, 69.99, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7rdys-m0ukf0zadeixb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F23597897841', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28203583576', 'LAKA Fruity Glam Tint , Original (4.5g)/Mini (1.9g) | 30 Cores', 'Tint Glam Frutal, Original (4,5g) / Mini (1,9g) ❤️ Aplicação hidratante 💛 Cor da vividação 💚 Excelente coloração 💙 Brilho transparente Benefícios: O tonalidade labial Vegano em fórmula hidratante oferece cor vibrante e alto brilho aos lábios enquanto os deixa macios e carnudos. Enriquecido com dez tipos de sucos de frutas ricos em vitaminas para nutrir e revitalizar os lábios. A textura leve e aquosa é confortável nos lábios. A cor do produto adere bem nos lábios para resultados duradouros. Tons translúcidos disponíveis em 14 tons translúcidos. Modo de Usar: Aplicar no centro dos lábios e depois espalhar para fora no resto dos lábios. Aplique no centro dos lábios e depois espalhe para fora no resto dos lábios. Tamanho: Original (4,5g) / Mini (1,9g) Cores Disponíveis: 101 Alegre, 102 úmido, 103 Humming, 104 Cereja, 105 Frio, 106 Suculento, 107 Açúcar, 108 Salgado, 109 Fresco, 110 Soda, 111 Mellow, 112 Ping-Pong, 113 Prazer, 114 Harmony, 115 Inveja, 116 CandidBerry não doce Berry de neblina', 52.37, 52.37, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134207-7rd6a-m7bmu9xmb7ch38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F28203583576', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27915995175', 'CNP Creme De Olhos Própolis | Nutritivo Para Com Extrato De, 50ml', 'Creme para os olhos de própolis CNP 50mL [Propolis Altamente NOURISHANTE] Enriquecido com própolis altamente nutritivo, o Creme para os olhos de própolis CNP fornece nutrientes essenciais para rejuvenescer e revitalizar a pele delicada ao redor dos olhos. A PELE ILUMINADA E FIRME] Este creme para os olhos ilumina e firma a pele sem brilho, deixando a pele com aparência mais jovem e radiante. Aproveite os benefícios da elasticidade aprimorada e uma tez mais vibrante. [TEXTURA Macia, NÃO ESCOLHIDA] Projetado com textura macia que é suave em peles sensíveis, este creme não pegajoso absorve facilmente, garantindo uma aplicação confortável e calmante toda vez. Testes de irritação da pele SEGURO PARA TODOS OS TIPOS DE PELE] Testes de irritação da pele passados e adequados para todos os tipos de pele, incluindo pele sensível. Use-o com confiança ao redor dos olhos ou em todo o rosto para obter cuidados abrangentes. [APLICAÇÃO Versátil] Enquanto perfeito para cuidados com os olhos direcionados, o Creme para os olhos de própolis CNP também pode ser aplicado em todas as linhas de rosto, pescoço e riso para aprimoramento geral da pele e cuidados intensivos.', 120.06, 115.0, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/sg-11134207-7req2-m1zb2lcundi59a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F27915995175', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
