INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51406016502', 'Plaina Elétrica Wap Wf Pe01 Corte Preciso Guia Paralela 760W', 'DESCRIÇÃO RESUMIDA A Plaina Elétrica WAP WF PE01 é a ferramenta ideal para quem procura eficiência e precisão no trabalho com madeira. Com 760W de potência e uma rotação de 16.000 RPM, permite plainar ou desbastar superfícies com rapidez, garantindo um acabamento uniforme. Equipada com duas lâminas por eixo, proporciona cortes mais suaves e reduz a necessidade de retrabalho. O seu design inclui uma empunhadura auxiliar emborrachada para melhor controlo, botão de ajuste de profundidade de até 2mm e trava de gatilho para operação contínua e segura. Características: Marca: WAP Modelo: WF PE01 Especificações: Cor: Cinzento e Amarelo Voltagem: 127V Potência: 760W Lâminas: Duas lâminas por eixo para maior desempenho Base: 82 x 250 mm Segurança: Trava de gatilho e empunhadura emborrachada Velocidade: 16.000 RPM (Rotações por minuto) Profundidade de Corte: Ajustável até 2 mm Corrente Elétrica: 5,2 A Comprimento do Cabo: 1,8 metros Classe de Isolação: II Dimensões: 17 x 17 x 31 cm (AxLxC) Conteúdo da embalagem: 1 x Plaina Elétrica WAP WF PE01 1 x Chave para remoção da lâmina 1 x Manual de Instruções Acessórios de suporte Garantia: 12 meses Peso Peso do produto: 2,5 kg Peso com embalagem: 2,75 kg', 847.99, 387.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkiiz7ye5yira1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F359168917%2F51406016502', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7185182624', 'Cápsula Café Nespresso Compatível Café Italle 20 Und', 'KIT 20 CÁPSULAS COMPATÍVEL COM NESPRESSO CAFÉ TURIM - Intensidade 10: Os Cafés Italle são colhidos por pequenos produtores brasileiros, e seu estilo de torra italiana resulta numa experiência única em sua xícara. Na versão Turim, um café com sabor forte e marcante, 100% arábica, com amargor presente e uma finalização inigualável. Café Italle Milão - Intensidade 12 Os Cafés Italle são colhidos por pequenos produtores brasileiros, e seu estilo de torra italiana resulta numa experiência única em sua xícara. A versão Milão traz um café arábica com toque de robusta, com sabor impactante, que domina o paladar. Experimente seu momento Italle!', 49.9, 39.92, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m18fmzwjnpya5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F334540655%2F7185182624', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
