INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12708967902', 'Kit Fralda Pampers Premium Care Jumbo Tamanho M com 160 unidades', 'O Kit contém: 2 pacotes de Fralda Pampers Premium Care Jumbo Tamanho M com 80 unidades cada. Pampers Premium Care , nossa proteção mais suave para a sua pele. É suave como o algodão° e ultra respirável. Também tem canais de ar para uma pele seca e arejada, e uma loção hipoalergênica exclusiva que ajuda a prevenir irritações. Suave como algodão°: a proteção mais suave da Pampers Canais de Ar: para uma pele arejada e sequinha Loção hipoalergênica exclusiva: ajuda a prevenir irritações Incrível sistema de absorção que oferece até 12 horas de sono sequinho** Ajuste cômodo e flexível: esticam e se ajustam aos movimentos do seu bebê Barreiras anti-derrames *Compre produtos Pampers', 342.49, 342.49, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/62f92ffd8b2ce55797f6fee98c38f486', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F12708967902', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
