INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19564207232', 'Creme Dental Colgate Natural Extracts Carvão Ativado e Menta 90g 3 unidades', 'Cuide naturalmente de sua boca com o novo creme dental Colgate® Natural Extracts Carvão Ativado e Menta, com ação purificante e branqueadora*. Pasta de dente com flúor, com uma embalagem 100% reciclável e um produto 100% vegano, não testado em animais. Descubra uma experiência incrível na escovação dos dentes graças ao novo sabor Carvão Ativado e Menta, que revitaliza o seu sorriso e também deixa os dentes mais brancos e saudáveis. Colgate Natural Extracts é perfeito para manter os dentes limpos! Sua fórmula com ingredientes naturais permite que você desfrute de um sorriso saudável a todo o momento. Benefícios: O creme dental Colgate Natural Extracts Carvão Ativado e Menta, com flúor, é uma explosão de sabores surpreendentes para o cuidado do seu sorriso com refrescância. Possui em sua fórmula extratos naturais de carvão ativado e menta, uma combinação inspirada na natureza que ajuda a deixar os dentes naturalmente brancos, removendo as impurezas, com escovação regular. Possui uma fórmula 100% vegana, não testada em animais. Possui uma embalagem reciclável, a primeira da Colgate no Brasil. Experimente nossa linha completa, que conta, também, com outros sabores, além de fio dental e enxaguante, sabor Carvão Ativado e Menta. *Fórmula com ingrediente purificante.', 40.69, 25.63, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd67-lvkmmqnk508eeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F19564207232', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
