INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27643553944', 'Linha Araty Best Cast Monofilamento Nylon 1/4LB Cor Laranja Para Pesca Esportiva Padrão IGFA Mazzaferro Várias Bitolas', 'Fabricada em copolímero de náilon com resina flexível, a Araty Best Cast oferece alta resistência, elasticidade equilibrada e memória reduzida, garantindo arremessos mais precisos e menos emaranhados. Desenvolvida para pescarias recreativas e esportivas, mantém desempenho estável mesmo após longas horas de uso, suportando abrasão e exposição solar sem perder qualidade. Sua cor laranja proporciona excelente visibilidade na superfície, facilitando o controle da linha durante o trabalho com iscas e fisgadas. Ideal para uso em água doce e costeira, atende tanto o pescador casual quanto o esportivo que busca custo-benefício e confiança em cada arremesso. Padrão IGFA Class. Ela é muito usada por pescadores que buscam recordes, precisão ou competições oficiais, mas também serve para quem quer confiança total na resistência declarada da linha. ESPECIFICAÇÕES: Marca: Araty Best Cast Fabricante: Mazzaferro Tipo: Linha monofilamento de nylon Cor: Laranja Peso: 1/4 lb Bitola: varia conforme o modelo escolhido Resistência: varia conforme a bitola selecionada Linha Araty Best Cast Mono Nylon 1/4lb Laranja Mazzaferro', 54.89, 39.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgz5jldpfbb4d8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F27643553944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
