INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20199771867', 'Dispositivo de Proteção Elétrica Intelbras EPS 302 BR', 'O EPS 302 é um dispositivo de proteção bivolt com 2 tomadas contra surtos de tensão provenientes da rede elétrica. O produto ainda conta com proteções essenciais para seu eletro, contra raios, curto-circuito e sobrecarga. Também possui filtro de linha para atenuação de ruídos EMI/RFI.', 57.9, 55.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > Lightning Protection', 'https://cf.shopee.com.br/file/sg-11134201-7rdxe-mdpiemozaxh814', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F859766415%2F20199771867', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399207451', 'CD The Rolling Stones - Aftermath - Importado', 'CD The Rolling Stones - Aftermath - Importado Aftermath é o quarto álbum de estúdio na discografia da banda de rock inglesa The Rolling Stones, lançado em 15 de abril de 1966 na Inglaterra, pela Decca Records e ABKCO Records e foi lançado em 20 de junho de 1966 nos Estados Unidos, pela London Records e ABKCO. Foi gravado nos estúdios da RCA, em Hollywood. Repertório do CD: 1. Paint It, Black 2. Stupid Girl 3. Lady Jane 4. Under My Thumb 5. Doncha Bother Me 6. Think 7. Flight 505 8. High And Dry 9. It''s Not Easy 10. I Am Waiting 11. Going Home', 99.9, 84.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-8261g-mkmsjszkyex249', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F22399207451', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393531273', 'CD Paul McCartney - McCartney III [(Standard)', 'CD Paul McCartney - McCartney III [(Standard) Digipack 50 anos após o lançamento de seu primeiro álbum solo auto intitulado McCartney, com Paul tocando todos os instrumentos e escrevendo e gravando todas as músicas, Paul McCartney lança McCartney III em 11 de dezembro de 2020. Paul não planejou lançar um álbum em 2020, mas no isolamento de “lockdown”, ele logo se viu desenvolvendo e criando. Em pouco tempo, uma coleção eclética de canções espontâneas se tornaria McCartney III: uma obra despojada, autoproduzida e, literalmente, solo marcando a abertura de uma nova década, na tradição de McCartney dos anos 1970 e McCartney II dos 1980. Gravado no início deste ano em Sussex (Reino Unido), McCartney III é principalmente construído a partir de tomadas ao vivo de Paul nos vocais e guitarra ou piano, fazendo overdubs em seu baixo, bateria, etc. McCartney III abrange uma vasta e íntima gama de modos e humores, de busca da alma a melancólica, de lúdico a ruidoso e todos os pontos intermediários - capturado com alguns dos mesmos equipamentos do Rude Studio de Paul usado já em 1971 sessões do Wings. E a gama de instrumentos vintage de Paul que ele tocou no novo álbum tem uma história ainda mais histórica, incluindo o contrabaixo original do trio de Bill Black de Elvis Presley ao lado do icônico baixo de violino Hofner de Paul e um mellotron do Abbey Road Studios usado em gravações dos Beatles. Assim como o lançamento de McCartney em 1970 marcou o retorno de Paul ao básico, após a maior separação da banda na história da música, e a obra-prima de vanguarda de 1980, McCartney II ressuscitou das cinzas do Wings, McCartney III encontra Paul de volta para contar a própria história. Repertório do vinil: 1. Long Tailed Winter Bird 2. Find My Way 3. Pretty Boys 4. Women and Wives 5. Lavatory Lil 6. Deep Deep Feeling 7. Slidin'' 8. The Kiss of Venus 9. Seize the Day 10. Deep Down 11. Winter Bird / When Winter Comes', 54.9, 41.9, NULL, 'Hobbies & Collections > CD, DVD & Bluray', 'https://cf.shopee.com.br/file/sg-11134201-8258r-mqnpyjyut2j2c0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F23393531273', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597425340', 'Carrinho De Praia Infantil Wagon Uni Duni - Kids Baby Hercules', 'Nosso Carrinho de praia Infantil Wagon é a escolha perfeita para as aventuras dos pequenos. Um lindo carrinho com adesivos, com puxador e rodas arrojadas! Agora a criançada vai levar seus brinquedos para todo lugar. Fácil de montar, prático, resistente e seguro. Com design adorável e cores vibrantes, este carrinho fará com que suas crianças explorem o mundo de forma segura e divertida. Feito com materiais de alta qualidade e rodas resistentes, ele é projetado para durar e suportar todas as brincadeiras imagináveis. Deixe a imaginação de seus filhos correr solta enquanto puxam seu carrinho em passeios emocionantes pelo jardim, sala de estar ou onde quer que a diversão os leve! Faça a escolha certa para o entretenimento infantil - escolha o nosso Carrinho de praia Infantil Wagon hoje mesmo!', 119.9, 119.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-7rbmw-lmq5g7wa3wih86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F829520727%2F21597425340', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201985354', 'Refrigerante Pepsi Black Sem Açúcar', 'Pepsi Black é um refrigerante com sabor intenso de cola e zero açúcar, ideal para quem busca o máximo de sabor sem culpa. Refrescante e saborosa, é perfeita para acompanhar seus momentos. Aproveite o sabor suave e a refrescância de Pepsi Black: * Zero açúcar * Aroma natural * Fabricado por Ambev S.A.', 9.49, 7.79, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-825an-mqnekkqqt6habb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554774%2F58201985354', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
