INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994675050', 'Lavadora Roupas Automática 10Kg, 15 Programas, 2 Molhos, 2 Enxágues, Entrada e Saída Água Automática', 'LAVADORA AUTOMÁTICA LATINA LA555 10KG A Lavadora Automática Latina LA555 é a escolha ideal para quem busca praticidade, eficiência e excelente custo-benefício no dia a dia. Com funcionamento totalmente automático, ela realiza todo o processo de lavagem sozinha — desde a entrada até a saída de água — proporcionando mais comodidade e economia de tempo. Equipada com 15 programas de lavagem, incluindo 2 opções de molho e 2 enxágues automáticos, a LA555 atende diferentes tipos de roupas e níveis de sujeira. Sua super turbina garante uma limpeza eficiente sem danificar os tecidos, enquanto o Maxifiltro de fiapos ajuda a manter as roupas sempre limpas e bem cuidadas. Com capacidade para até 10kg, possui amplo espaço interno, sendo capaz de lavar edredom de casal ou até 66 camisetas em um único ciclo. Conta ainda com dispensers separados para sabão e amaciante, pés reguláveis e alça para facilitar o transporte. Seu motor de alta performance com tecnologia WEG oferece mais durabilidade e eficiência no uso contínuo. Além disso, possui timer com desligamento automático, trazendo ainda mais praticidade e segurança. IMPORTANTE: Disponível nas versões 127V ou 220V (Não é bivolt) Cor: Branca e Preta Não possui função centrifugação ESPECIFICAÇÕES TÉCNICAS: Capacidade de lavagem: 10 kg Programas de lavagem: 15 (com 2 molhos e 2 enxágues) Entrada e saída de água: Automáticas Timer: Desligamento automático Dimensões (AxLxC): 93 x 53 x 53 cm Uma lavadora completa, prática e eficiente para facilitar sua rotina com mais economia e desempenho.', 1420.0, 849.0, NULL, 'Home Appliances > Large Household Appliances > Washing Machines & Dryers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdexm95ppbrla0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F286347381%2F22994675050', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
