INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193260687', 'Bíblia Sagrada NVI | Letra Grande | Capa Dura | Leão Promessas Divinas', 'O projeto de tradução para a língua portuguesa começou em 2000, a partir de uma reunião da comissão da Sociedade Bíblica Internacional. Um grupo formado por respeitados estudiosos brasileiros e de outros países foi reunido para produzi-la. Este projeto durou quase uma década. Muitos acham que é apenas uma tradução da americana, porém erram ao pensar assim, pois a versão em português foi feita no Brasil. O propósito dos idealizadores da NVI foi fazer um texto que se definisse por quatro elementos: precisão, clareza, beleza de estilo e dignidade. Com uma linguagem clara e mais próxima da atualidade, sem perder a beleza do estilo da linguagem bíblica. Cercada de elogios por conta do compromisso que conseguiu manter com os Escritos originais, esta versão da Bíblia já vendeu milhões de exemplares nos últimos anos, e vem se popularizando cada vez mais. 14x21cm 216 Páginas', 64.9, 64.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdvm-lzmkyotoei9z14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22193260687', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
