INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41528803297', 'Limpador Multiuso Valente Limpa Tudo Biodegradável 500ml Piso Clean', 'Valente Limpa Tudo combina limpeza e sustentabilidade. Produto com ativo biodegradável, pode ser usado em todas as superfícies laváveis. Ideal para limpar a sujeira da casa inteira. Remove com facilidade manchas difíceis como gorduras, canetas permanentes, café, vinho, sangue, manchas das necessidades fisiológicas de animais de estimação e etc. Como usar? 1. Aplique VALENTE Limpa Tudo puro nas superfícies e deixe agir por 5 minutos 2. Em seguida esfregue com pano ou esponja macia e então remova a sujeira. Não há necessidade de enxágue com água pois após a limpeza restará um mínimo de resíduo na superfície. Limpeza de Pisos: Para maior rendimento e economia pode-se diluir o produto meio a meio com água. Onde usar? Ambientes: Áreas internas, Áreas externas Revestimentos: Em todas as superfícies laváveis. Obs.: Limpeza de Pisos: Para maior rendimento e economia pode-se diluir o produto meio a meio com água. Rendimento: Até 5m²/Frasco', 34.54, 34.54, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8262r-mkv33z54hc750f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F41528803297', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43167680473', 'Fita Alumínio Manta Asfaltica Adesiva Impermeabilizante Vedatudo Dryko Multiuso Reparo Telhas', 'DRYKOFITA VEDATUDO CINZA 5cm x 10 Metros Fita autoadesiva multiuso à base de asfalto, protegida com filme na cor cinza que permite sua exposição a intempéries e aos raios solares, para solucionar problemas de gotejamento e vedações. Onde aplicar: • Telhados; • Rufos e chapas metálicas; • Dutos de ventilação e ar condicionado; • Sheds e cúpulas, • Vedações de domos e claraboia; • Reparos rápidos em baús, toldos e similares; • Sistema de reflexão térmica. Aplicação do primer: Aplique uma demão de DRYKOPRIMER ACQUA ou DRYKOPRIMER ECO e aguarde a secagem por no mínimo 6 horas antes da colagem. Aplicação da DRYKOFITA VEDATUDO CINZA Em telhados inicie a aplicação sempre do ponto mais baixo para o mais alto. Remova o filme plástico expondo o asfalto adesivo e aplique este lado na superfície imprimada pressionando para melhor aderência e removendo possíveis bolhas de ar. A DRYKOFITA VEDATUDO CINZA deve estar totalmente apoiada na superfície de aplicação. Em superfícies irregulares como telhados deve aplicar a DRYKOFITA VEDATUDO CINZA acompanhando as ondulações, removendo o filme plástico conforme faz a aderência na superfície. Em áreas muito frias promover o pré-aquecimento da DRYKOFITA VEDATUDO CINZA com ar quente ou através do calor do sol.', 22.0, 15.4, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/br-11134207-820le-mn4h0fqwmw3od7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F43167680473', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
