INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46452973039', 'Creme Texturizador Lola Cosmetics Creme Transiçao 500g', 'Descrição: O Creme Texturizador Lola Cosmetics Creme Transiçao 500g possui ativo patenteado para estimular o crescimentoé perfeito e vai ajudar seu cabelo a crescer mais forte e resistente. Além disso sou feito com Água de Rosas, Alecrim e Cera de Rosas, nutrientes poderosos que vão cuidar do interior do seu fio. Tudo que você precisa para esse momento. Fórmula vegana, dermatologicamente testada e que protege seus fios do calor do secador. MODO DE USAR: Divida o seu cabelo úmido (não molhado) em seis seções iguais, depois generosamente aplique o Creme Multi Texturas em cada seção. A quantidade certinha vai variar de acordo com a necessidade do seu fio. Finalize como de costume, preferencialmente modelando com as mãos de baixo para cima para estimular os cachos, deixando secar naturalmente ou usando o difusor. USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 500g. #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 44.9, 44.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-822zh-mi4m05qflwqq7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F46452973039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
