INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15018345352', 'Homens mais parecidos com Jesus | David J. Merkh', 'Os homens vivem buscando modelos de masculinidade para seguir. No entanto, acompanhar o padrão errado pode trazer consequências desastrosas e eternas para toda uma vida. Pensando nisso, o autor best-seller, David Merkh, apresenta nesta importante obra o modelo supremo de todo homem: JESUS. Aqui, o desafio é não apenas agir como o Filho de Deus agiu ou agiria. É preciso ultrapassar a barreira da conduta e adquirir o caráter de Jesus e tê-lo impresso em sua própria vida diária, com reflexos visíveis a todos, até nas pequenas decisões sobre família, amigos, filhos, igreja e trabalho. Se você quiser ser um homem segundo o coração de Deus, um líder de valor, estratégico, amoroso e que sabe servir à sociedade, tendo como principal legado o próprio exemplo, lembre-se destas duas verdades: masculinidade não é “machismo” e homens de verdade se parecem com o Filho de Deus.', 38.9, 36.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/a400e7dce868183536bf42e40063b192', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F15018345352', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51711604199', 'Kit 5 Roupinha Para Cachorro Inverno Pequena Média e Grande Porte Roupa Pet Frio', '⚠️ AS ESTAMPAS DAS ROUPINHAS SÃO ENVIADAS DE FORMA ALEATÓRIA ⚠️ 🐶 KIT COM 5 ROUPINHAS PARA CACHORRO – SUÉTER PET SOFT 🐶 Mantenha seu pet protegido, confortável e estiloso nos dias mais frios! O Kit com 5 Roupinhas Pet foi desenvolvido para proporcionar aconchego e liberdade de movimento para cães de pequeno, médio e grande porte. Produzidas em tecido Soft de alta qualidade, as roupinhas são macias, leves e ideais para manter seu amigo aquecido durante o inverno. ✅ Contém 5 roupinhas para cachorro ✅ Para machos e fêmeas ✅ Tecido Soft macio e confortável ✅ Acabamento reforçado em viés ✅ Fácil de vestir ✅ Não limita os movimentos do pet ✅ Ideal para dias frios e meia estação ✅ Diversas estampas sortidas 📦 Conteúdo da embalagem: • 05 Roupinhas 🐾 BENEFÍCIOS • Mantém o pet aquecido e confortável • Tecido suave que não irrita a pele • Excelente ajuste ao corpo • Durável e resistente ao uso diário • Pode ser utilizada para passeios ou dentro de casa 📏 IMPORTANTE Antes da compra, consulte a tabela de medidas e compare com as medidas do seu pet. Para maior conforto, recomendamos escolher um tamanho com pequena folga. 🧼 INSTRUÇÕES DE LAVAGEM • Lavar à mão ou em ciclo delicado • Não utilizar alvejante • Secar à sombra Seu melhor amigo merece conforto, proteção e muito estilo. Garanta agora o Kit com 4 Roupinhas Pet e deixe seu cãozinho preparado para os dias mais frios!', 79.99, 67.2, NULL, 'Pets > Pet Clothing & Accessories > Pet Clothing', 'https://cf.shopee.com.br/file/sg-11134201-823rl-mp195ynaew3wfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908280603%2F51711604199', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392157753', 'Ração Fórmula Natural Life Cães Adultos Porte Mini e Pequeno 10,1kg Adimax', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - Descrição: Com um conceito natural do produto às embalagens, a Fórmula Natural foi formulada para promover uma vida mais saudável, longeva e de bem-estar para cães e gatos. A linha oferece versões para diferentes portes e idades e proporciona entre outros benefícios, cuidados com a pele e pelagem, equilíbrio da flora intestinal e antioxidantes naturais. Fórmula Natural Super Premium Cães Adultos Portes Mini e Pequeno oferece todos os cuidados para cães adultos de porte miniatura e pequeno, a partir de um ano de idade. - - - - - Modo de Uso: A quantidade de ração para seu pet varia de acordo com o seu porte, peso e raça. - - - - - Enviamos o seu pedido o quanto antes possível! Obrigado pela preferência.', 354.1, 180.33, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ly5iemxirn7kb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F22392157753', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23312225128', 'O Batismo com o Espírito Santo | R. A. Torrey', 'Dividido em cinco capítulos, o livro tem o intuito de conscientizar o leitor de vários aspectos do batismo com o Espírito Santo, como a sua definição ( trazida pelo autor diretamente da própria bíblia ), suas eventualidades, o modo como é obtido e a importância da sua prática contínua, porque seu poder pode ser destituído. R. A. Torrey, ilustre evangelista e autor, trata do assunto de maneira séria, simples e direta, não abrindo espaços a interpretações dúbias quanto às posturas necessárias para a recepção do revestimento de poder que o batismo com o Espírito Santo oferece. Atentando a todos os possíveis desvios à sua conquista, a obra se estabelece como um guia fundamental a todo cristão que deseja compreender e alcançar tal experiência, além de ampliar suas concepções acerca do próprio Espírito Santo. Adquira o seu exemplar e garanta riquíssimos e essenciais conhecimentos para você, cristão, que deseja alcançar o batismo com o Espírito Santo. 14x21cm 48 Páginas', 18.9, 18.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-22120-q6otmwjqv8kved', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23312225128', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
