INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194935309', 'Camisa Retrô Vasco Jacquard 242783 Torcedor Premium Vintage Clássica Conforto', 'A Camisa Retrô Vasco Jacquard 242783 é perfeita para torcedores que valorizam tradição, estilo e qualidade premium. Com design inspirado nos uniformes clássicos do clube, traz um visual vintage autêntico com acabamento diferenciado em tecido jacquard. Produzida em material de alta qualidade, o tecido jacquard oferece textura sofisticada e maior durabilidade, além de proporcionar excelente caimento e conforto durante o uso. Ideal para o dia a dia, eventos esportivos ou momentos de torcida. Seu design clássico do Vasco transmite identidade e paixão pelo clube, sendo uma peça indispensável para torcedores e colecionadores. Destaques do produto: Tecido jacquard com acabamento premium Design retrô clássico do Vasco Ideal para torcedores e colecionadores Conforto para uso prolongado Estilo vintage sofisticado Alta durabilidade Ficha técnica: Marca: (varia conforme fornecedor) Modelo: Retrô Vasco Jacquard 242783 Categoria: Vestuário esportivo / casual Tipo: Camisa retrô Material: Jacquard (poliéster ou misto) Manga: Curta Indicado para: Torcida, lazer e uso casual Gênero: Masculino / Unissex (varia conforme versão) Time: Vasco da Gama Origem: Nacional', 189.9, 113.94, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-81zv3-mn0ib57awjcz23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1191965739%2F23194935309', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
