INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11713036162', 'Sensor De Ré + Espelho Camera Ré Chevrolet Cobalt Branco', '# OESTESOM # Espelho Retrovisor com Tela 4.3 Polegadas + Camera de Ré Borboleta + Sensor de Estacionamento 4 Pontos Solução Completa pra te ajudar estacionar e manobrar o veículo, aumentando a segurança e evitando pequenos acidentes, o espelho retrovisor com tela é de fácil instalação, basta encaixar em cima do retrovisor original do veículo e te permite ter uma visão em tempo real da traseira do veículo além do auxilio do sensor de estacionamento que emite um som conforme o veículo se aproxima dos obstaculos. -Tamanho compacto -Fácil instalação -Aciona automaticamente ao engatar a ré Dados técnicos: Aviso sonoro: Sim Aviso visual: Sim Liga/desliga aviso sonoro: Sim Alimentação: 12V Consumo: 4W Distancia de captação (m): 0,3 a 1,8 Frequência do ultrassom: 40KHZ0 Comprimento do cabo aproximado (m): 7,0 Medidas display (cm): 10,0 x 3,0 x 2,0 Medidas modulo controle (cm): 9,0 x 6,0 x 2,5 Itens inclusos: 1 Display, 4 Sensores, 1 Módulo de Controle, 1 Serra Copo, 1 Espelho Retrovisor com Tela 4,3 Polegadas e 1 Camera de Ré tipo Borboleta. Obs: Produto indicado para veículos que não possuem sensor de estacionamento de fábrica, "Esse produto não substitui o sensor de estacionamento de fábrica" Recomendamos que a instalação seja realizada por profissionais, não nos reponsabilizamos por danos causados por má instalação.', 215.6, 188.51, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Parking Cameras and Sensors', 'https://cf.shopee.com.br/file/b9c1a5af9f9144cffafbb1bf10a0c2cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F11713036162', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
