INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093983352', 'Resina Acrílica Fuseprotec | Brilhante, fosca, semibrilho | - 18l - Viapol', 'COMPRE APENAS 1 UNIDADE POR VEZ 30KG É O LIMITE DE PESO, E NÃO NOS PERMITE O ENVIO DE 2 OU MAIS PRODUTOS FUSEPROTEC® SUPER DESCRIÇÃO Fuseprotec® Super é um verniz à base de resina acrílica pura de alto desempenho dispersa em solvente, transparente, resistente ao intemperismo. VANTAGENS • Fácil aplicação e manuseio; • Resistente à ação dos raios solares e à alcalinidade do concreto; • Apresenta ótima resistência à água; • Não impregna sujeira, não amarela e não descasca. UTILIZAÇÕES • Fachadas; • Pisos cimentícios com tráfego leve de pessoas; • Paredes internas e externas; • Estruturas de concreto aparente; • Tijolos aparentes; • Pedras naturais com porosidade; • Telhas cerâmicas naturais; • Telhas de fibrocimento. PREPARAÇÃO DA SUPERFÍCIE A superfície deverá ser previamente lavada, seca, isenta de pó, vernizes, tintas, desmoldantes, ceras, fungos, bolor, carbonatação ou qualquer tipo de material que possa prejudicar a aderência do Fuseprotec® Super. FERRAMENTAS Rolo de pintura de lã de pelo curto ou Airless. Realizar a limpeza das ferramentas com Fuseprotec® Diluente Fuseprotec Brilhante Semi- Brilho Fosco', 1347.5, 875.88, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9k7q7o0ngua09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F22093983352', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
