INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499384666', 'Esquadro Articulado 6 Seções Vonder', 'Ref. Fornecedor: 3550012006 Marca: Vonder Conteúdo da embalagem: 1 Esquadro articulado. Acompanha: 3 marcadores para canos. Destaques e diferenciais: Possui marcações a laser, acompanha 3 marcadores para canos de 25 mm, 40 mm e 45 mm. Aplicações e dicas de uso: Indicado para marcações e transferências de ângulos e medidas na construção civil. Utilizado em telhados, canos, paredes, pisos, entre outros. Características Técnicas: Material: Alumínio Medidas do esquadro: 6 seções de 12 cm Largura do esquadro: 24 mm Graduação do esquadro: mm / pol Tipo de gravação do esquadro: Laser Tipo de trava: Parafuso auto-trava / ajustável', 68.9, 68.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdwi-m0fvu4p3vekac5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F20499384666', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3290202750', 'Bomba de Ar para Encher Pneus 60cm com Cabo T Vonder Plus', 'Conteúdo da embalagem 1 Bomba de ar com alavanca Aplicações e dicas de uso Indicada para encher pneus de carros, motos, bicicletas, entre outros. Nunca solte o cabo tipo "T" enquanto o mesmo estiver pressionado e pressurizado (risco de acidente). Destaques e diferenciais Possui corpo e plataforma de apoio em plástico reforçado, manômetro para indicação da pressão e mangueira plástica com 60 cm e bico DETALHES TÉCNICOS Material do corpo da bomba: Plástico reforçado Altura da bomba: 60 cm Cor do corpo da bomba: Preta e amarela Diâmetro do corpo da bomba: 1.1/2" - 38 mm Material do cabo da bomba: Plástico Tipo do cabo da bomba: Tipo "T" Comprimento da mangueira da bomba: 60,0 cm Pressão máxima da bomba: 80 lbf/pol²', 98.9, 98.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Measurement', 'https://cf.shopee.com.br/file/sg-11134201-7rbl0-llmk335nzoop72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F3290202750', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254583309', 'Mantecorp Episol Color Tom 1 Extra Claro FPS 70 - Protetor Solar Facial com Cor 40ml', 'Protetor solar facial. Mantecorp Episol Color FPS 70 proporciona tripla proteção de alta performance contra os raios UVA/UVB, Luz Visível e Infravermelho A. O Protetor Solar Facial Mantecorp Episol Color FPS 70 promove alta proteção e cobertura na pele com cor, de efeito natural matte e toque seco. A nova fórmula possui a tecnologia Soft Focus, suaviza as imperfeições, disfarça rugas finas, linhas de expressão e imperfeições da pele sem obstruir os poros. O uso regular do protetor solar auxilia na prevenção do câncer de pele e de outros efeitos danosos causados pelo sol. Hipoalergênico e não comedogênico. Sua nova fórmula não possui cheiro. Como usar: Deve ser aplicado em abundância e uniformemente sobre a pele seca antes da exposição ao sol ou sempre que necessário. Se a quantidade aplicada não for adequada, o nível de proteção será significativamente reduzido. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 92.9, 92.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-8261y-mka2r2o7od8of3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58254583309', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
