INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8035659433', 'Areon Aromatizante Automotivo Black 50ml Perfume + Difusor', 'Mundo Pecas, Empresa com mais de 21 anos no mercado de pecas para reposicao automotiva, com garantia de preco justo, atendimento sempre dando preferencia a Qualidade. O Melhor Aromatizante Automotivo do Mundo. Aromatizante de Carro Luxo Perfume Areon - Black 50ml + Difusor de papel Areon Quality Perfume, Luxuoso perfume para carros, com uma refinada selecao de perfumes. Fragrancia duradoura para quem gosta de manter seu carro sempre cheiroso. Mon Aeron e uma colecao contemporanea de aromatizantes que cativa seus sentidos. Detalhes tecnicos Design inspirador aliado a perfumes marcantes para um ambiente refrescante aonde quer que voce va. Aroma: Deliciosa fragrancia aromatica que mistura aromas citricos, especiarias e amadeirados. Familia olfativa: Spicy. Notas de saida: bergamota, toranja, pimenta. Notas de coracao: geranio, patchouli, cedro. Notas de fundo: vetiver, sandalo, almiscar. Conteudo da embalagem: 01 odorizador de ambiente spray (50ml) e um difusor de celulose. COMPRE DIRETO DO DISTRIBUIDOR COM TOTAL GARANTIA NA ENTREGA E NO POS VENDA, TIRE SUAS DUVIDAS DIRETO COM PESSOAS ESPECIALIZADAS NO RAMO AUTOMOTIVO!!', 73.9, 73.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Fragrances', 'https://cf.shopee.com.br/file/75f8f3645c1763b9aa759a980cb90e33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397020362%2F8035659433', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
