INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43831952558', 'Mini Fones de Ouvido Sem Fio 5s Pro, Hi-Fi Estéreo, À Prova D''Água, Controle por Toque, Cancelamento de Ruído ENC para', 'Desfrute de som premium com estes fones de ouvido sem fio, com 3 efeitos sonoros e tecnologia avançada 5.4 para ampla compatibilidade. Compactos e estilosos, são perfeitos para treinos ou jogos. Disponíveis em Branco, Preto, Rosa e Caqui. Características: • Design in-ear sem fios • Estrutura em plástico de alta qualidade • Fone: 2×1,6 cm; Estojo: 4,9×3,8 cm • Conectividade: Wireless • Aplicações: Música e chamadas • Bateria do fone: 30mAh; Estojo: 400mAh • Reprodução: 5 horas; Espera: 120 horas • Tempo de carregamento: 1 hora; Alcance: 15 m Controles (por fone): • 1 toque: Atender/finalizar chamada • Duplo toque: Próxima/anterior • Pressão de 2 seg: Volume ± • Triplo toque: Assistente de voz • Pressão de 5 seg: Ligar/desligar Conteúdo da embalagem: • 2 fones de ouvido • 1 estojo de carregamento • 1 cabo de carregamento • 1 manual do usuário 🎧 Eleve sua experiência sonora—liberdade sem fios, som profissional! 🎶✨', 22.0, 15.07, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134253-824gj-mptyquxn48p942', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F43831952558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
