INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794479236', 'Jogo Chave Fixa Mayle 6 a 22mm 100402MY 8 Peças Cromo', 'JG CHAVE FIXA MAYLE 6 A 22MM - 8 PEÇAS 100402MY Descrição O Jogo de Chave Fixa Mayle 6 a 22mm com 8 peças é a solução completa para afrouxar, apertar e regular porcas e parafusos sextavados. Fabricado em aço cromo vanádio com acabamento niquelado, oferece durabilidade e precisão para profissionais e entusiastas do "faça você mesmo". As cabeças com menor espessura permitem acesso a locais de difícil alcance, tornando este kit indispensável na sua caixa de ferramentas. 🌟 POR QUE O JOGO DE CHAVE FIXA MAYLE É IDEAL PARA VOCÊ? ✔️ Versatilidade Total: 8 tamanhos diferentes de chaves em um único kit, atendendo desde serviços leves até os mais pesados ✔️ Material Premium: Fabricado em aço cromo vanádio (CrV), garantindo alta resistência e longa vida útil ✔️ Acesso a Lugares Restritos: Cabeças com espessura reduzida que permitem trabalhar em espaços apertados ✔️ Proteção Superior: Acabamento niquelado/cromado que protege contra corrosão e oxidação 🎯 VANTAGENS EXCLUSIVAS: ✅ 8 Peças para 16 Medidas: Sistema de chave combinada com duas medidas por ferramenta ✅ Marca Reconhecida: Mayle é referência em ferramentas manuais no mercado brasileiro ✅ Ergonomia e Controle: Design que proporciona excelente conforto e evita escorregamentos ✅ Organização Inclusa: Acompanha estojo organizador para armazenamento e transporte 🔧 CARACTERÍSTICAS TÉCNICAS: → Marca: Mayle / Mayle Crescent → Modelo: 100402MY → Material: Aço Cromo Vanádio (CrV) → Acabamento: Niquelado / Cromado → Quantidade de Peças: 8 chaves → Garantia: 6 meses (3 meses legais + 3 meses do fabricante) 📦 ITENS INCLUSOS: • Chave 6 x 7 mm • Chave 8 x 9 mm • Chave 10 x 11 mm • Chave 12 x 13 mm • Chave 14 x 15 mm • Chave 16 x 17 mm • Chave 18 x 19 mm • Chave 20 x 22 mm • Estojo organizador 🛒 COMPRE AGORA E GARANTA O KIT COMPLETO PARA SUA OFICINA! 🚚 CONDIÇÕES DE ENTREGA: 📦 FRETE GRÁTIS 🆓 para todo Brasil! ⏰ Entrega Rápida - receba em até 7 dias úteis! 🛡️ Garantia do Fabricante - Consulte a garantia padrão com o distribuidor no ato da compra.', 76.66, 69.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lc-mmkfihxicmpzed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979559296%2F23794479236', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
