INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259234660', 'Geladeira EOS 192 Litros Duplex Inverse Preto ERV260IDP 220V', '❄️ Geladeira EOS 192 Litros Duplex Inverse Preto ERV260IDP ✨ Sofisticação, eficiência e praticidade para sua cozinha. Com 192 litros de capacidade total e design Duplex Inverse, ela oferece mais conforto no dia a dia ao posicionar o freezer na parte inferior, facilitando o acesso ao refrigerador e otimizando a organização dos alimentos. ✨ Destaques do Produto: ✅ Capacidade total de 192 Litros (135L refrigerador + 57L freezer) ✅ Sistema Duplex Inverse com freezer na parte inferior ✅ Faixa de temperatura de -22°C a 8°C ✅ Iluminação interna em LED ✅ Termostato ajustável para controle preciso de temperatura ✅ Prateleiras ajustáveis para melhor organização interna ✅ Compartimentos internos que facilitam a conservação dos alimentos ✅ Alta eficiência energética com classificação A++ ✅ Gás ecológico, mais sustentável e econômico ✅ Funcionamento silencioso de apenas 43 dB(A) ✅ Design moderno na cor preta com acabamento elegante 📏 Medidas (LxAxP/cm): 49,5 x 143 x 56 cm 💎 Mais praticidade, economia e elegância para o seu dia a dia na cozinha.', 2297.9, 2297.9, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-820o9-mnaehjbqjw8x69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1527564302%2F58259234660', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
