INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12732827170', 'Envelope saco plástico ofício 1380 cristal liso com 50 unidades Chies', 'Envelope Plástico A4 da Chies é a solução ideal para quem busca praticidade e organização. Composta por polipropileno de alta qualidade, este envelope é super resistente e não adere ao papel, garantindo a integridade dos seus documentos. Seu modelo de furação universal é versátil, permitindo que seja utilizado em fichários com 2, 3 ou 4 argolas. Detalhes: - Anti-reflexo. - Banda de reforço - Medidas: 23,8 x 33,4 cm - Produzido com polipropileno especial - cristal. - Perfeita transparência e sem aderência ao papel, 100% reciclável. - A impressão não gruda no plástico com o calor e também não arrisca. - Ideal para pastas catálogos, listas de preços, organização de documentos, arquivos, etc. - Possui furação universal para todos os tipos de arquivos com ferragem de 2, 3 e 4 argolas.', 44.88, 35.9, NULL, 'Stationery > Letters & Envelopes > Envelopes & Angpao', 'https://cf.shopee.com.br/file/sg-11134201-823rt-monycozs229sc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F12732827170', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
