INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998285912', 'Pistão Kit C/anel Kmp Xt 225 Std', 'PISTAO KIT C/ANEL KMP XT 225 STD O Pistão Kit com Anel KMP é composto por pistão com pino e travas incluindo Anéis de Segmento KMP. O pistão deste kit foi desenvolvido para utilizar anéis de segmento das CG s de modelos antigos pois as peças eram mais grossas e com isso o motor teria uma vida útil maior. Tudo isso com qualidade e tecnologia moderna da KMP marca líder no mercado. O Pistão KMP é líder de mercado graças à sua qualidade impecável. Esta peça acompanha pino e travas de pistão sendo a escolha perfeita para quem quer deixar o motor dentro das especificações do fabricante já que o produto está em conformidade com todas as especificações OEM (Original Equipment Manufacturer). Além disso o Pistão KMP é fabricado em liga de alumínio especial garantindo funcionamento perfeito em todas as faixas de rotações. O pino de pistão passa por um tratamento de elevação de dureza para garantir ótima performance e as travas que são produzidas em aço carbono recebem tratamentos exclusivos da KMP. Este é um produto que se destaca por ter altíssima qualidade e traz as mais modernas tecnologias em peças para moto. Os Anéis de Pistão KMP são um sucesso no mercado duas rodas por trazerem excelente performance para uma grande variedade de modelos de motos. Para um funcionamento impecável utilize este produto em conjunto com o Pistão KMP dessa forma o conjunto terá excelente rendimento.', 150.5, 150.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6s-m72bqkgs7m6k4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1117095756%2F22998285912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399893119', 'Kit 4 Aditivos Limpador De Vidro Parabrisa 200ml Volkswagen', 'KIT ADITIVOS LIMPEZA PARABRISA ORIGINAL VW PEÇAS NOVAS E ORIGINAIS VW G052164R1 4 UNIDADES COM 200 ML CADA. COMPATIVEL COM: TODA LINHA VW COMPRAS EFETIVADAS ATÉ AS 10:00H, SERÃO ENVIADAS NO MESMO DIA! PARA AVERIGUAÇÃO DE COMPATIBILIDADE, É NECESSÁRIO A NUMERAÇÃO COMPLETA DO CHASSI. PRODUTO NOVO, ORIGINAL! SOMOS CONCESSIONÁRIA VOLKSWAGEN. TIRE TODAS AS DÚVIDAS PELO CAMPO DE PERGUNTAS ANTES DE EFETUAR A COMPRA. VERIFIQUE SEU ENDEREÇO DE ENTREGA. SERÁ COBRADO UM NOVO FRETE CASO O PRODUTO RETORNE. FIQUE ATENTO AS SUAS MENSAGENS. GARANTIA: PEÇAS ORIGINAIS COMPRADA NA REDE VW TEM GARANTIA NACIONAL, SENDO QUE, SE A PEÇA FOR INSTALADA EM UMA CONCESSIONÁRIA TERÁ GARANTIA DE 1 ANO, INSTALAÇÃO FEITA EM OUTRA OFICINA TERÁ GARANTIA DE APENAS 90 DIAS! “AS PEÇAS ORIGINAIS VOLKSWAGEN REPRESENTAM SEMPRE A MELHOR ESCOLHA. UMA LINHA COMPLETA DE PEÇAS PROJETADAS, TESTADAS E PRODUZIDAS COM ALTO RIGOR TECNOLÓGICO PARA PROPORCIONAR O MÁXIMO EM DESEMPENHO COM CONFIABILIDADE E A MESMA SEGURANÇA DAS PEÇAS UTILIZADAS EM UM VEÍCULO ZERO QUILOMETRO”. CORREAUTO VW VOCÊ MERECE UM ATENDIMENTO 5 ESTRELAS!', 54.98, 54.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-824h2-met0h62ba4g6f1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1182059565%2F19399893119', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
