INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397162303', 'Chocolate Branco Lacta Laka 80g', 'Laka é um dos chocolates mais amados do Brasil. Com certeza quem experimenta nunca esquece seu sabor inconfundível, maciez espetacular e por conta de toda a qualidade Lacta, Laka é um dos chocolates queridinhos do país inteiro. Os chocolates Lacta fazem parte do Cocoa Life, que é um programa de uso de cacau sustentável, que torna o chocolate ainda mais delicioso e feito com muito carinho! Laka é perfeito para qualquer ocasião, como sobremesa depois daquela refeição deliciosa, pra presentear alguém especial, comer naquele cineminha em casa com a família. Marca: Lacta Peso líquido: 90 gramas Sabor: Chocolate Branco Ingredientes: Açúcar, leite em pó integral, manteiga de cacau, soro de leite em pó, gordura vegetal, extrato de malte, gordura de manteiga desidratada, emulsificantes: lecitina de soja e poliglicerol polirricinoleato e aromatizante.', 12.99, 11.99, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljbj15kpfbn4a1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1008814366%2F20397162303', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798322000', 'Tampa do Reservatório de Óleo do Motor Astra Meriva Stilo 1.8 5050146 MTA', 'LOJA OFICIAL NOVA CHEVROLET GM NOVA CHEVROLET, QUALIDADE E CONFIANÇA AO SEU ALCANCE! Tampa do Reservatório de Óleo do Motor MTA (Cód: 5050146) Especificação Técnica: Marca: MTA Código de referência: 5050146 Material: Plástico de alta qualidade Garantia: 3 Meses Valor: Unitário Produto Novo Aplicação do Produto: Fiat Palio, Siena e Strada (1.8, 2003 em diante) Fiat Stilo (1.8 8V e 16V, 2004 em diante) Fiat Idea e Punto (2005 em diante) Chevrolet Astra (2.0 8V, 2004 em diante) Chevrolet Meriva (1.8 16V, 2003 em diante) Conteúdo da Embalagem: 1 Tampa do Reservatório de Óleo do Motor Importante: A Garantia da Nova Chevrolet não cobre má instalação ou mau uso do produto. Recomendamos que a instalação seja feita por um profissional especializado para garantir o funcionamento correto e adequado da peça. Observações e Condições da Loja: Antes de comprar, tire suas dúvidas nas perguntas. Todos os nossos produtos são novos com garantia. Todas vendas acompanham nota fiscal eletrônica. Confirme aplicações técnicas com seu mecânico. Não entregamos em Caixa Postal dos Correios. Compre no CPF, pois no CNPJ terá o custo de ICMS pago pelo cliente. Mantenha seus dados pessoais atualizados no site. Receba o produto garantido ou seu dinheiro de volta. Economize adicionando vários produtos ao carrinho. Todos os produtos anunciados estão disponíveis para pronta entrega. Devolução só com o produto em embalagem intacta. O vendedor não tem autonomia sobre entregas. Compra errada não tem troca, apenas devolução. Suporte e Horários de Atendimento: Atendimento e suporte técnico à disposição. Segunda a Sexta: 8h às 20h Sábados: 8h às 12h', 45.0, 45.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7grb6f8sgqa3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F422105437%2F22798322000', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254682904', 'Óleo Compressor Ar Condicionado R134a E R1234yf Idemitsu', 'Produto: Oleo para Compressor R134a R1234yf. PAG46 Compatíveis com compressores elétricos Óleo produzido no Japão com a mais alta e renomada tecnologia mundial, atende todas os padrões de todas as montadoras tais como BMW Mercedes Jaguar Audi Land Rover Volkswagen Fiat Jeep e Demais montadora. Como distribuidor autorizado no Brasil. A Idemitsu é uma empresa japonesa que fabrica óleos lubrificantes para compressores de ar condicionado, refrigeração comercial e automotiva. Os óleos Idemitsu para compressores de ar condicionado são desenvolvidos para cada sistema de refrigeração. ******************Vantagens dos óleos Idemitsu***************************** *Proteção contra desgaste e temperaturas extremas *Aumento da vida útil do compressor e do sistema *Redução de custos de manutenção *Produto quimicamente diferente, com uma estrutura estável e não reativa Aplicações *Sistemas de A/C com R1234yf e R134a *Proteção contra desgaste e temperaturas extremas *Redução de custos de manutenção **************************Características dos óleos Idemitsu ********************* *Desenvolvem tecnologias exclusivas com especialização na área de PAG *Garantem o desempenho nas mais variadas temperaturas Proteção contra o desgaste dos compressores', 78.0, 78.0, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/sg-11134201-825zq-mkbrq4ze73lw5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1698877873%2F58254682904', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
