INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258290723', 'Tênis Olympikus Feminino Corre Max Corrida', 'Desperte o atleta dentro de você com o novo Olympikus Corre Max! Projetado para quem busca leveza e maciez em cada passada, ele é a escolha ideal para suas corridas leves. Seu cabedal, feito de tecido, garante respirabilidade e um toque macio incomparável, proporcionando conforto a cada passo. A palmilha Ortholite de 6 mm, confeccionada para uma pisada mais suave e revestida com tecido de poliéster, proporciona um ajuste perfeito, enquanto a entressola equipada com a tecnologia Eleva Pro Max eleva seus índices de resiliência, leveza, conforto e responsividade. Além disso, o solado com borracha antiderrapante Gripper oferece aderência firme no solo, garantindo estabilidade, mesmo nos desafios do seu dia a dia. Sinta a diferença, supere seus limites e leve sua experiência de corrida a um novo nível. Corra com o Olympikus Corre Max!', 729.89, 549.88, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-823ri-moo6wkt5xslo2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F58258290723', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250945286', 'Tênis Usaflex Feminino Slip On Tricot UD03005 Casual', 'Fique na moda com o tênis Usaflex Slip On Tricot UD03005! Com design moderno e versátil, é perfeito para quem busca praticidade no dia a dia sem abrir mão do estilo. Confeccionado em tecido tricot, o modelo oferece respirabilidade, flexibilidade e leveza, garantindo conforto desde o primeiro uso. No estilo slip on, possui calce fácil, envolvendo o pé de forma suave como uma meia. Isso proporciona um ajuste ergonômico e reduz a pressão nos pés, oferecendo uma experiência ainda mais confortável. A palmilha macia traz bem-estar a cada passo. O solado em EVA é leve e garante excelente amortecimento, aderência e durabilidade, com uma construção que oferece até 30% mais leveza em comparação a outros materiais. Garanta já o seu Usaflex e sinta a diferença a cada passo!', 289.89, 209.88, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-8224y-mhg9t1cr1fk207', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F58250945286', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
