INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48508328253', 'Forma Coração Lapidado Fatias 3 Partes 350g 10644', 'A Forma PVC Coração Fatias 350g BWB é ideal para moldar corações recheados em fatias com precisão, praticidade e acabamento profissional, sendo uma escolha indispensável para confeiteiros que buscam resultados diferenciados e de alto padrão em suas produções. Desenvolvida especialmente para facilitar o processo de moldagem de corações divididos em fatias, garante uniformidade e perfeição em cada peça produzida, proporcionando um resultado final sofisticado que encanta tanto pelo visual quanto pelo sabor e pelo cuidado em cada detalhe. Produzida em PVC resistente e transparente, permite visualizar o chocolate durante o processo de moldagem, facilitando o controle da quantidade e da distribuição do produto em cada cavidade. Sua estrutura firme e bem definida garante que os corações saiam com formato preciso e acabamento impecável, com superfície brilhante e uniforme que valoriza ainda mais a apresentação final. Esse nível de qualidade e consistência faz toda a diferença para confeiteiros que prezam pela padronização e pelo profissionalismo em cada peça entregue ao cliente. Com capacidade para 350g de chocolate e dimensões de 12,2 x 10,7 x 3,9 cm, resultando em um coração bem proporcionado e visualmente impactante, perfeita para produções de médio porte e para presentear em datas especiais como Dia dos Namorados, Páscoa, Dia das Mães e outras ocasiões que pedem um presente cheio de sabor e carinho. Material: PVC e Silicone Capacidade: 350g Dimensões: 12,2 x 10,7 x 3,9cm Indicação de uso: Ideal para moldar corações recheados em fatias Características: Forma articulada que garante precisão e acabamento profissional no preparo de corações em fatias', 26.06, 15.64, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/br-11134207-820m3-mmqf2futo1s0bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F48508328253', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
