INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55855900893', 'Desentupidor Elétrico 21V com Desentupidor De Esgoto Vaso Sanitário Ralo De Banheiro', 'O Desentupidor Elétrico GENAI GN-713 é a solução inteligente e eficiente para desobstruir canos e esgotos residenciais. Com tecnologia de embreagem automática e motor brushless de alta performance, ele oferece operação simples e segura, ideal para uso doméstico e profissional. Principais Características: Embreagem automática que protege o motor e aumenta a durabilidade Motor brushless 21V MAX com bateria de lítio 5.0Ah de longa duração Velocidade ajustável (0–1000 rpm) conforme a gravidade do entupimento Cabo termicamente tratado, resistente a emaranhados e torções Design ergonômico com botões de controle intuitivos Especificações Técnicas: Diâmetro do eixo flexível: 15–16 mm Velocidade em vazio: 0–1000 rpm Bateria: 21V MAX / XR 5.0Ah (inclui 2 baterias) Carregador: Entrada 110~240V CA, Saída 2,0A Compatível: Vaso sanitário, ralo de chão, ralo de cozinha, pia de banheiro, pia de lavabo Cenários de Uso: Desentupimento de vasos sanitários Limpeza de ralos de cozinha e banheiro Desobstrução de canos de pias e lavatórios Manutenção preventiva de tubulações residenciais Acessórios Incluídos: 1 Snake de limpeza de esgoto (16cm) 1 Snake de limpeza de esgoto (28cm) 2 Baterias recarregáveis 21V 5.0Ah 1 Carregador rápido 1 Par de luvas de proteção 1 Anel de fixação', 999.0, 529.99, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-825zy-mkdmt2nagao45b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F791248992%2F55855900893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
