INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251104289', 'Engate Reboque Fixo Jetta 2012 a 2018 700 Kg - Brucke VW5031', 'Engate Reboque Volkswagen Jetta 2012 a 2018 Fixo 700 Kg Marca: Brucke Modelo: VW5031 - Compatibilidade: Volkswagen Jetta 2012 Volkswagen Jetta 2013 Volkswagen Jetta 2014 Volkswagen Jetta 2015 Volkswagen Jetta 2016 Volkswagen Jetta 2017 Volkswagen Jetta 2018 O Engate Reboque para o Volkswagen Jetta de 2012 a 2018 Fixo da marca Brucke é a solução ideal para quem busca robustez e confiabilidade. Com uma capacidade de reboque de até 700 Kg, este modelo com ponteira Fixo tem resistência testada e garantida, garantindo que você possa transportar cargas pesadas com segurança! É compatível com carretinhas, trailers, transbikes. - Atributos do Produto: Tipo de ponteira: Fixo Medidas: 19 x 47 x 118 cm, 10kg. Capacidade de reboque tração: Até 700 Kg Capacidade de peso sobre a bola: Até 40 kg Material: Fabricado em Aço carbono Pintura: Acabamento em pintura eletrostática a pó na cor preta Homologação: Produto homologado pelo INMETRO (012587/2022) e regularizado conforme a resolução nº 197 do Contran. Acompanha bola de engate, tomada e acabamento (quando necessário) como nas imagens. Código interno: 882 Instalação: Instalação simples nas furações originais do veículo, sem necessidade de furos ou adaptações. A instalação deve ser feita por um profissional.', 580.83, 522.75, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Hitch', 'https://cf.shopee.com.br/file/sg-11134201-82274-mhjnez7tor2c70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1625011375%2F58251104289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
