INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259360486', 'Kit Esmalte Colorama Colecao Diabo Veste Prada Top Coat', '#html-body [data-pb-style=QB1QYDR]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}O Kit Esmalte Colorama Coleção Diabo Veste Prada + Top Coat é perfeito para quem busca unhas elegantes, modernas e com acabamento profissional. Inspirado no universo fashion do filme The Devil Wears Prada, traz cores sofisticadas que combinam com diferentes estilos e ocasiões. O kit conta com 4 esmaltes exclusivos da coleção, que proporcionam alta cobertura, brilho intenso e longa duração, além de um Top Coat, que potencializa o acabamento, aumenta a durabilidade e garante efeito gel às unhas. Kit contém: Rebeldia (H2755500): Tom marcante e moderno Item de Luxo (H2755600): Cor elegante e sofisticada Veste Prata (H2755700): Acabamento metálico estiloso Noite de Estreia (H2755800): Tom intenso e clássico Top Coat Gel 8ml: Brilho extra e maior fixação Modo de Uso: Esmalte: Aplique uma camada de base (opcional) Aplique o esmalte escolhido Aguarde secar e aplique uma segunda camada, se necessário Top Coat: Após o esmalte seco, aplique uma camada do top coat Aguarde secagem completa', 88.87, 88.87, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-820md-mndcrs94qzuoe9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F58259360486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43508748485', 'Enxaguante Bucal Listerine Zero Álcool 500ml', 'Enxaguante Bucal Listerine Zero Álcool 500ml O Enxaguante Bucal Listerine Zero Álcool 500ml oferece proteção eficaz contra os germes bucais com uma fórmula suave e livre de álcool. Ideal para quem busca uma rotina de higiene bucal eficiente sem abrir mão do conforto e do frescor. Principais Características: • Fórmula sem álcool, com sabor suave, ideal para uso diário • Ação antisséptica que elimina até 99,9% dos germes causadores de mau hálito, placa e gengivite • Alcança regiões que a escova e o fio dental não conseguem atingir Benefícios: • Proporciona hálito fresco por mais tempo • Reduz a placa bacteriana • Previne problemas gengivais • Sensação de limpeza completa sem ardência Diferenciais do Produto: • Eficácia comprovada na proteção bucal com fórmula livre de álcool • Suavidade no uso, sem irritar a mucosa oral • Indicado para pessoas com sensibilidade ou que preferem fórmulas mais leves Especificações Técnicas: - Peso: 500ml Instruções de Uso: - Utilize 20ml do produto duas vezes ao dia, após escovar os dentes. - Bocheche por 30 segundos e descarte o líquido. - Não é necessário enxaguar com água. - Não ingerir. Avisos e Precauções: - Não ingerir. - Uso externo. - Manter fora do alcance de crianças. - Em caso de irritação, interromper o uso e consultar um profissional de saúde. O que está incluso? - 1 unidade de Enxaguante Bucal Listerine Zero Álcool 500ml ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 47.49, 36.09, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mci6342izpq9c0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F43508748485', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
