INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697807636', 'Painel para TV até 75 Polegadas MDF 182CMX134CM Oslo Bege Off White/Canela', 'Transforme sua sala de estar com o sofisticado Painel Oslo 1.8. Este painel combina o acabamento off-white fosco com detalhes em canella, criando um contraste elegante e moderno que valoriza qualquer ambiente. Ideal para suportar TVs de até 75 polegadas, o Painel Oslo oferece não apenas beleza, mas também funcionalidade com seus espaços planejados para organizar aparelhos eletrônicos e acessórios. Design Moderno e Sofisticado: Acabamento off-white fosco que proporciona um visual clean e contemporâneo, com detalhes em canella para um toque de sofisticação. O LED é opcional. Espaço para TV: Ideal para TVs de até 75 polegadas, oferecendo uma base estável e segura. Material de Alta Qualidade: Produzido com materiais duráveis e de fácil manutenção, garantindo longa vida útil. Estilo: Moderno Peso (kg): 36.8 Garantia: 03 Meses Altura (cm): 134 Acabamento: Verniz Largura (cm): 182 Possui Pés: Não Possui Vidro: Não Possui Portas: Não Possui Gavetas: Não Possui Tomadas: Não Suporta Até (kg): 40 Possui Espelhos: Não Profundidade (cm): 7.5 Escala de Brilho: Fosco Acabamento Ripado: Não possui Acompanha Lâmpada: Não Origem do Produto: Nacional Possui Iluminação: Não Ambiente Principal: Sala de Estar Material Principal: MDF Necessita Montagem: Sim Possui Passa Cabos: Sim Possui Prateleiras: Não Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Ideal para TVs até (Polegadas): 75 Informações Complementares (Novo): ILUMINAÇÃO LED OPCIONAL Suporte de TV Universal Incluso: Não Marca: Província Cor: Off White/Canela Cor do Produto: Off White/Canella Itens Inclusos: 1 Painel, Kit Ferragens e Manual de Montagem Cor Predominante: Beg